-- ─── пачка 1 (2026-08-03) ───────────────────────────────────────────────────

-- iphone-13 — кут: вік моделі (телефон не новий, чохол йому не перший); побічні — блок камер і типові сюжети
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-iphone-13', 'template',
	 'Чохол з фото на замовлення для iPhone 13', 'Чехол с фото на заказ для iPhone 13',
	 'Чохол з фото для iPhone 13 — друк на замовлення | FLOY', 'Чехол с фото на заказ для iPhone 13 — UV-печать | FLOY',
	 'Друкуємо ваше фото на силіконовому чохлі для iPhone 13. Композицію підбираємо під квадратний блок камер, принт наносимо UV-друком по всій поверхні.',
	 'Печатаем ваше фото на силиконовом чехле для iPhone 13. Композицию подбираем под квадратный блок камер, рисунок наносим UV-печатью по всей поверхности.',
	 '<h2>Телефон той самий, вигляд новий</h2><p>iPhone 13 давно не новинка, і в більшості власників він устиг пережити кілька чохлів. Спершу прозорий, потім чорний силіконовий, далі знову прозорий — бо попередній пожовк. До самого телефона претензій немає, міняти його немає причин. Набридає якраз зовнішній вигляд.</p><p>Саме тут і працює друк на чохлі. Апарат лишається той самий, а в руці щоразу щось своє: кадр з відпустки, морда собаки, обкладинка улюбленого альбому, напис, зрозумілий двом людям.</p><h3>Блок камер задає композицію</h3><p>Дві камери в iPhone 13 стоять по діагоналі у квадратному блоці зліва вгорі, і цей квадрат займає помітну частину верху чохла. Для принта це головне обмеження. Обличчя, підпис чи центральний об&#39;єкт туди краще не заводити: на макеті все виглядає нормально, а на готовому чохлі частина зображення опиняється навколо блоку.</p><p>Простіше опустити головне нижче середини. Горизонтальні кадри — море, гори, панорама міста — лягають у нижні дві третини й нічого не втрачають. Для портрета беріть вертикальний кадр і зміщуйте його вправо. Коли фон суцільний — небо, стіна, вода, — блок камер перестає впадати в око: він заважає лише там, де розрізає щось важливе.</p><p>Ще одна річ, помітна саме на цьому корпусі. iPhone 13 не з великих телефонів, і в долоні нижня третина чохла майже завжди закрита пальцями. Дрібний напис під самим краєм побачить хіба той, хто бере телефон зі столу. Якщо підпис для вас важливий, піднімайте його ближче до середини й ставте збоку від головного об&#39;єкта — там він лишається на видноті.</p><h3>Що на цю модель друкують найчастіше</h3><p>За ці роки на неї встигли надрукувати геть усе, але кілька сюжетів повторюються постійно:</p><ul><li>спільні фото: удвох, компанією, весільний кадр;</li><li>домашні тварини, зазвичай один великий план;</li><li>знімки з поїздок, зроблені цим самим телефоном;</li><li>ім&#39;я або дата дрібним шрифтом унизу, поверх однотонного фону.</li></ul><p>Є ще один сценарій, якого пару років тому не було: Айфон 13 часто передають далі — дитині, молодшому братові, комусь із рідних. Телефон той самий, власник новий. Чохол зі своїм принтом — найпростіший спосіб зробити його справді своїм.</p><p>У конструкторі це збирається за кілька хвилин: завантажити фото, додати напис, вибрати шрифт, залити фон кольором, посунути шари. Подивіться на прев&#39;ю не тільки як на картинку — уявіть телефон, що лежить екраном донизу на столі в кафе. У такому вигляді чохол для iPhone 13 бачать найчастіше, і саме тоді видно, чи вдала композиція.</p>',
	 '<h2>Аппарат прежний, вид новый</h2><p>Айфон 13 уже давно не новинка. У большинства владельцев он пережил не один чехол: сначала прозрачный, потом чёрный силиконовый, затем снова прозрачный, потому что предыдущий пожелтел. Менять сам телефон незачем, он всё ещё устраивает. Приедается именно внешний вид.</p><p>Печать на чехле закрывает эту задачу. Устройство остаётся прежним, а в руке каждый раз что-то своё: кадр из отпуска, морда собаки, обложка любимого альбома, надпись, понятная двоим.</p><h3>Композицию диктует блок камер</h3><p>Две камеры iPhone 13 расположены по диагонали в квадратном блоке слева вверху, и квадрат этот занимает заметную часть верха чехла. Отсюда главное ограничение для принта. Лицо, подпись или центральный объект туда лучше не помещать: в макете всё смотрится нормально, а на готовом чехле часть изображения оказывается вокруг блока.</p><p>Проще опустить главное ниже середины. Горизонтальные кадры — море, горы, панорама города — ложатся в нижние две трети и ничего не теряют. Под портрет берите вертикальный снимок и сдвигайте его вправо. Со сплошным фоном — небо, стена, вода — блок камер вообще перестаёт бросаться в глаза: он мешает только там, где разрезает что-то важное.</p><p>Есть деталь, заметная именно на этом корпусе. Телефон не из крупных, и в ладони нижняя треть чехла почти всегда закрыта пальцами. Мелкую надпись у самого края увидит разве что тот, кто берёт телефон со стола. Так что важный текст поднимайте ближе к середине и ставьте сбоку от главного объекта — там он остаётся на виду.</p><h3>Что печатают на эту модель чаще всего</h3><p>За эти годы на неё напечатали вообще всё, но несколько сюжетов повторяются постоянно:</p><ul><li>совместные фото: вдвоём, компанией, свадебный кадр;</li><li>домашние животные, обычно один крупный план;</li><li>снимки из поездок, сделанные этим же телефоном;</li><li>имя или дата мелким шрифтом внизу, поверх однотонного фона.</li></ul><p>Появился и сценарий, которого пару лет назад не было: iPhone 13 часто передают дальше — ребёнку, младшему брату, кому-то из родни. Телефон тот же, владелец новый. Чехол со своим принтом делает его по-настоящему личным.</p><p>В конструкторе всё это собирается за несколько минут: загрузить фото, добавить надпись, выбрать шрифт, залить фон цветом, подвинуть слои. Посмотрите на превью не как на картинку — представьте телефон, лежащий экраном вниз на столе в кафе. Чехол для iPhone 13 видят чаще всего именно так, и там сразу понятно, удачная композиция или нет.</p>',
	 NULL, NULL, 1);

-- ─── пачка 2 (2026-08-04) ───────────────────────────────────────────────────

-- motorola-edge-50-fusion — кут: рідкісна модель, готових чохлів у продажу майже нема; побічне — фактурна спинка ховається під чохлом
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-motorola-edge-50-fusion', 'template',
	 'Чохол з фото на замовлення для Motorola Edge 50 Fusion', 'Чехол с фото на заказ для Motorola Edge 50 Fusion',
	 'Чохол з фото на Motorola Edge 50 Fusion — друк | FLOY', 'Чехол с фото на Motorola Edge 50 Fusion — печать | FLOY',
	 'Друкуємо ваше зображення на чохлі для Motorola Edge 50 Fusion. Модуль камер компактний, тож вертикальний кадр лягає на спинку майже без обрізання.',
	 'Печатаем ваше изображение на чехле для Motorola Edge 50 Fusion. Модуль камер компактный, поэтому вертикальный кадр ложится на спинку почти без обрезки.',
	 '<h2>Коли готового чохла просто немає</h2><p>З Моторолою є незручність, знайома кожному власнику. Заходиш у магазин аксесуарів, називаєш модель — і тобі виносять два чохли: прозорий і чорний. Буває, що й жодного, бо «на Моторолу мало питають». Полиця з десятками варіантів у магазині є, тільки вона для Samsung та iPhone.</p><p>Друк під конкретну модель це питання знімає. Форма й вирізи беруться з готової маски саме для Motorola Edge 50 Fusion, а що буде на спинці — вирішуєте ви, а не закупівля магазину.</p><h3>Фактурну спинку однаково не видно</h3><p>Частина власників брала цей телефон саме через задню панель: у деяких версіях вона зроблена під шкіру чи замшу, тепла на дотик і не ковзає в руці. Далі відбувається звичне — зверху вдягають чохол, і вся фактура зникає. Ходити без захисту теж так собі ідея: краї екрана вигнуті, і при падінні на кут дістається саме кромці.</p><p>Виходить чесний розмін. Якщо приємну спинку все одно закрито, хай на її місці буде щось ваше, а не сірий силікон з полиці.</p><h3>Що врахувати в макеті</h3><p>Корпус у Motorola Edge 50 Fusion тонкий і витягнутий, модуль камер компактний і сидить у лівому верхньому куті. Вільної площі під зображення лишається багато: вертикальний кадр стає майже цілим, без агресивного обрізання по боках. Це вже рідкість — на багатьох свіжих корпусах верхню третину з&#39;їдає широкий камерний блок.</p><p>Через видовжену форму тут добре працюють вертикальні сюжети: людина на повний зріст, дерево, дорога, що йде вглиб кадру. Панорама, розтягнута на всю спинку, навпаки, втрачає боки — краще взяти її фрагмент, ніж стискати цілу.</p><p>Одне спостереження з життя. Телефон тонкий, тому найчастіше він лежить у зовнішній кишені куртки або в бічній кишені рюкзака, спинкою назовні. У такому вигляді чохол бачать сторонні, а не ви, причому побіжним поглядом. Дрібна деталь, яку ви розглядаєте в конструкторі впритул, у цей момент не читається зовсім — велика проста форма працює краще.</p><p>Ще одне спостереження про власників. Едж 50 Фьюжн зазвичай беруть свідомо: це не той апарат, який дістається за замовчуванням разом із тарифом чи за порадою продавця. Його вибирають, порівнявши кілька варіантів і вирішивши не йти за більшістю. Логічно, що й чохол таким людям рідко хочеться брати перший-ліпший. У замовленнях на цю модель помітно більше не сімейних фото, а власних захоплень: кадр із вершини, мотоцикл, обкладинка платівки, знімок, зроблений самотужки на плівку.</p><p>Решта збирається в конструкторі за кілька хвилин: завантажити фото, посунути й змасштабувати, додати напис потрібним шрифтом, залити фон кольором там, де зображення не закриває всю площу. Чохол для Моторола Едж 50 Фьюжн вийде один такий — принаймні у вашому місті точно.</p>',
	 '<h2>Когда готового чехла просто нет</h2><p>С Моторолой знакома одна и та же история. Заходишь в салон аксессуаров, называешь модель — выносят два чехла: прозрачный и чёрный. Иногда не выносят ничего: «на Мотороллу почти не спрашивают». Стенд с десятками вариантов в магазине есть, но он под Samsung и iPhone.</p><p>Печать под конкретную модель этот вопрос закрывает. Форма и вырезы берутся из готовой маски для Motorola Edge 50 Fusion, а рисунок на спинке выбираете вы, а не закупщик торговой точки.</p><h3>Фактурную спинку всё равно не видно</h3><p>Многие выбирали этот аппарат из-за задней панели: в части версий она сделана под кожу или замшу, тёплая на ощупь и не выскальзывает. Дальше происходит привычное — сверху надевается чехол, и никакой фактуры уже нет. Ходить совсем без защиты тоже не вариант: края экрана скруглённые, и при падении на угол первой страдает кромка.</p><p>Размен получается честный. Раз приятную спинку всё равно закрыли, пусть вместо неё будет что-то ваше, а не серый силикон с витрины.</p><h3>Что учесть в макете</h3><p>Корпус у Motorola Edge 50 Fusion тонкий и вытянутый, блок камер небольшой и стоит в левом верхнем углу. Свободного места под изображение остаётся много: вертикальный снимок помещается почти целиком, без жёсткой обрезки по краям. По нынешним временам это редкость — у многих новых корпусов верхнюю треть съедает широкий камерный блок.</p><p>Из-за удлинённой формы хорошо заходят вертикальные сюжеты: человек в полный рост, дерево, уходящая вдаль дорога. А вот панорама, растянутая на всю спинку, теряет края — разумнее взять её фрагмент, чем сжимать целиком.</p><p>Наблюдение из практики. Аппарат тонкий, и чаще всего он лежит во внешнем кармане куртки или в боковом кармане рюкзака, спинкой наружу. Именно так чехол видят посторонние, а не владелец, — беглым взглядом. Мелкая деталь, которую вы вблизи разглядываете в конструкторе, в этот момент не читается вовсе, а крупная простая форма работает.</p><p>И ещё о самих владельцах. Эдж 50 Фьюжн обычно берут осознанно: этот аппарат не достаётся по умолчанию вместе с тарифом и не всплывает первым по совету продавца. Его выбирают, сравнив несколько вариантов и решив не идти за большинством. Понятно, что и чехол такие люди редко хотят брать первый попавшийся. В заказах на эту модель заметно больше не семейных снимков, а личных увлечений: кадр с вершины, мотоцикл, обложка пластинки, фотография, снятая своими руками на плёнку.</p><p>Остальное собирается в конструкторе за несколько минут: загрузить фото, сдвинуть и отмасштабировать, добавить надпись нужным шрифтом, залить фон цветом там, где картинка не покрывает всю площадь. Чехол для Моторола Эдж 50 Фьюжн получится единственный в своём роде.</p>',
	 NULL, NULL, 1);

-- samsung-galaxy-a07 — кут: хто цю модель купує (перший телефон, школа); побічне — дитячий малюнок як принт
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-samsung-galaxy-a07', 'template',
	 'Чохол з фото на замовлення для Samsung Galaxy A07', 'Чехол с фото на заказ для Samsung Galaxy A07',
	 'Чохол з принтом для Samsung Galaxy A07 на замовлення | FLOY', 'Чехол с принтом для Samsung Galaxy A07 на заказ | FLOY',
	 'Свій принт на чохлі для Samsung Galaxy A07: фото, напис або дитячий малюнок. Найпростіший спосіб не переплутати телефон з таким самим у класі чи вдома.',
	 'Свой принт на чехле для Samsung Galaxy A07: фото, надпись или детский рисунок. Простой способ не перепутать аппарат с точно таким же в классе или дома.',
	 '<h2>У класі таких телефонів кілька</h2><p>Samsung Galaxy A07 рідко буває єдиним апаратом у родині чи в компанії однолітків. Це телефон із тих, які беруть дитині в школу, купують батькам замість зношеного кнопкового або тримають другим номером для роботи. Тому ситуація типова: на парті лежать три однакові чорні прямокутники, і хто чий — питання відкрите.</p><p>Чохол зі своїм принтом вирішує це швидше за будь-яку наліпку. Телефон упізнається з іншого кінця столу, а не після розблокування екрана.</p><h3>Якщо телефон дитячий</h3><p>Тут є прийом, до якого доходять не одразу: надрукувати не фото з інтернету, а власний малюнок дитини. Сфотографуйте аркуш при денному світлі, завантажте в конструктор — і дракон із фломастерів переїжджає на спинку телефона. Дитина носить свою роботу з собою, а не забуту в шухляді.</p><p>Другий робочий варіант — ім&#39;я великим шрифтом на однотонному фоні. У початковій школі телефони плутають постійно, і підписаний чохол рятує від щоденних розборів, чий саме апарат лежить у роздягальні.</p><h3>Кілька слів про формат</h3><p>Корпус у Гелексі А07 великий і плаский, спинка майже без вигинів по краях. Це зручно для макета: зображення не «стікає» на боки, і те, що ви бачите в прев&#39;ю, майже так само лягає на готовий чохол. Дрібні деталі по кутах усе ж краще не заводити — саме кути телефон тримають пальці.</p><p>Для старшого покоління логіка інша. Батькам і бабусям зазвичай друкують велике фото онуків — одне, впізнаване, на весь чохол, без дрібного тексту й складних колажів. Телефон беруть у руки десятки разів на день, і кожного разу це працює.</p><p>З підлітками працює третій сценарій. У цьому віці телефон — частина образу, і чохли міняють задовго до того, як вони зношуються. На полиці для бюджетної моделі лежить приблизно те саме: квіточки, серця, кілька мультяшних персонажів. Улюбленої групи, кадру з гри чи власного колажу там не буде ніколи. Друк цю прогалину закриває повністю — що завантажили, те й опиняється на спинці.</p><p>Ще один сценарій: телефон переходить далі — від старшого брата молодшому, від батька дитині. Апарат той самий, а новий чохол з друком робить його наче щойно куплений. Зібрати макет для Samsung Galaxy A07 у конструкторі можна за кілька хвилин: фото, напис, шрифт, колір фону, порядок шарів. Один телефон — і жодного шансу переплутати його з сусідським.</p>',
	 '<h2>В классе таких телефонов несколько</h2><p>Samsung Galaxy A07 редко оказывается единственным аппаратом в семье или в компании ровесников. Это телефон из тех, что берут ребёнку в школу, покупают родителям взамен изношенной кнопочной трубки или держат вторым номером для работы. Отсюда узнаваемая картина: на парте лежат три одинаковых чёрных прямоугольника, и чей из них какой — вопрос открытый.</p><p>Чехол со своим рисунком решает это быстрее любой наклейки. Телефон узнаётся с другого конца стола, ещё до того, как его разблокировали.</p><h3>Если телефон детский</h3><p>Есть приём, до которого доходят не сразу: печатать не картинку из интернета, а собственный рисунок ребёнка. Снимите лист при дневном свете, загрузите в конструктор — и дракон, нарисованный фломастерами, переезжает на спинку телефона. Работа не лежит в ящике, а ездит с автором.</p><p>Второй рабочий вариант — имя крупным шрифтом поверх однотонного фона. В младших классах телефоны путают регулярно, и подписанный чехол избавляет от ежедневных выяснений, чей аппарат остался в раздевалке.</p><h3>Пара слов о формате</h3><p>Корпус у Галакси А07 крупный и плоский, спинка почти без заваленных краёв. Для макета это удобно: изображение не стекает на боковины, и превью близко к тому, что получится на готовом чехле. Мелкие детали по углам всё же лучше не размещать — за углы телефон и держат.</p><p>Для старшего поколения логика другая. Родителям и бабушкам обычно печатают одно большое фото внуков — узнаваемое, на весь чехол, без мелкого текста и многослойных коллажей. Телефон берут в руки десятки раз за день, и каждый раз это срабатывает.</p><p>С подростками действует третий сценарий. В этом возрасте телефон — часть образа, и чехлы меняют задолго до того, как они износятся. На витрине под бюджетную модель лежит примерно одно и то же: цветочки, сердечки, пара мультперсонажей. Любимой группы, кадра из игры или собственного коллажа там не появится никогда. Печать этот пробел закрывает целиком — что загрузили, то и окажется на спинке.</p><p>Ещё один сценарий: аппарат передают дальше — от старшего брата младшему, от отца ребёнку. Телефон прежний, а свежий чехол с печатью делает его почти новым. Собрать макет для Samsung Galaxy A07 в конструкторе можно за несколько минут: фото, надпись, шрифт, цвет фона, порядок слоёв. Один телефон — и ни единого шанса спутать его с соседским.</p>',
	 NULL, NULL, 1);

-- samsung-galaxy-a26-5g — кут: вертикальний острівець камер і композиція принта
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-samsung-galaxy-a26-5g', 'template',
	 'Чохол з фото на замовлення для Samsung Galaxy A26 5G', 'Чехол с фото на заказ для Samsung Galaxy A26 5G',
	 'Чохол з фото для Samsung Galaxy A26 5G — друк | FLOY', 'Чехол с фото для Samsung Galaxy A26 5G — печать | FLOY',
	 'Друк власного фото на чохлі для Samsung Galaxy A26 5G. Камери стоять вертикальною смугою зліва вгорі — показуємо, як під неї зібрати композицію.',
	 'Печать своего фото на чехле для Samsung Galaxy A26 5G. Камеры идут вертикальной полосой слева вверху — разбираем, как под неё собрать композицию.',
	 '<h2>Вертикальна смуга зліва вгорі</h2><p>У Samsung Galaxy A26 5G об&#39;єктиви зібрані в довгастий острівець і стоять стовпчиком у лівому верхньому куті, спалах — окремою краплею поруч. Для макета це головна деталь корпусу: смуга займає не кут, а помітну частину лівого краю зверху вниз.</p><p>Наслідок простий. Усе, що на зображенні стоїть по лівому боці й вище середини, ризикує опинитися впритул до цієї смуги. Обличчя людини, підпис, силует кота — переносьте їх правіше або нижче, і композиція збереться сама.</p><h3>Що лягає добре, а що бореться з корпусом</h3><p>Найспокійніше поводяться кадри з рівним фоном угорі: небо над морем, туман над лісом, однотонна стіна, градієнт. Верхня частина такого зображення нічого не втрачає, а острівець на ній майже не читається як чужорідний елемент.</p><p>Гірше з симетричними сюжетами — портрет строго по центру, круглий логотип, мандала. Симетрію око зчитує миттєво, і будь-яке зміщення відносно камер стає помітним. Якщо принт саме такий, простіше опустити його ближче до низу чохла, ніж намагатися вирівняти по верху.</p><p>Окремо про текст. Напис через усю ширину у верхній третині — найчастіша помилка в макетах для Гелексі А26. Літери, які проходять повз камерну смугу, читаються рвано. Той самий напис, поставлений під зображенням або збоку вертикально, виглядає навмисним прийомом, а не випадковістю. До речі, вертикаль тут узагалі виграшна: острівець уже задає корпусу вертикальний ритм, і макет, побудований стовпчиками, з ним не сперечається.</p><p>Є дрібниця, про яку згадують нечасто. Спалах винесений окремо від острівця, тож у верхній зоні фактично два вирізи, а не один. Для великого зображення це неважливо, а тонкий елемент — стебло, ниточка, край силуету — може пройти рівно між ними й розірватися надвоє.</p><h3>Коротка перевірка макета</h3><p>Перед тим як відправляти, подивіться на прев&#39;ю кілька секунд і дайте собі відповідь на два питання: що тут головне і чи не перетинає його верхній лівий кут. Такий погляд збоку ловить більшість проблем ще до замовлення. Якщо головного об&#39;єкта в кадрі немає взагалі — фактура, візерунок, абстракція — питання знімається, такі принти на Samsung Galaxy A26 5G сідають без єдиного компромісу.</p><p>Далі все в конструкторі: масштаб, поворот, шари, колір фону під зображенням і напис потрібним шрифтом. Пересунути фото на кілька пікселів займає секунду, а різницю на готовому чохлі видно з першого погляду.</p>',
	 '<h2>Вертикальная полоса слева вверху</h2><p>У Samsung Galaxy A26 5G объективы собраны в продолговатый островок и выстроены столбиком в левом верхнем углу, вспышка вынесена отдельной каплей рядом. Для макета это ключевая особенность корпуса: полоса занимает не уголок, а заметную часть левого края сверху вниз.</p><p>Вывод отсюда простой. Всё, что на картинке расположено слева и выше середины, рискует упереться в эту полосу. Лицо, подпись, силуэт кота — сдвигайте правее или ниже, и композиция соберётся почти сама.</p><h3>Что ложится легко, а что спорит с корпусом</h3><p>Спокойнее всего ведут себя кадры с ровным верхом: небо над морем, туман над лесом, однотонная стена, градиент. Верхняя часть такого изображения ничего не теряет, а островок перестаёт восприниматься как посторонний элемент.</p><p>Сложнее с симметричными сюжетами — портрет строго по центру, круглый логотип, мандала. Симметрию глаз считывает мгновенно, и любое смещение относительно камер сразу бросается в глаза. Если принт именно такой, проще опустить его ближе к низу чехла, чем выравнивать по верхнему краю.</p><p>Отдельно про текст. Надпись во всю ширину в верхней трети — самая частая ошибка в макетах для Галакси А26. Буквы, проходящие мимо камерной полосы, читаются рвано. Та же надпись под изображением или сбоку вертикально выглядит уже как приём, а не как случайность. Вертикаль здесь вообще в выигрыше: островок задаёт корпусу вертикальный ритм, и макет, собранный столбцами, с ним не спорит.</p><p>Есть мелочь, о которой вспоминают редко. Вспышка вынесена отдельно от островка, так что в верхней зоне получается два выреза, а не один. Крупному изображению это безразлично, а тонкий элемент — стебель, ниточка, край силуэта — способен пройти ровно между ними и разорваться надвое.</p><h3>Короткая проверка макета</h3><p>Перед отправкой посмотрите на превью несколько секунд и ответьте себе на два вопроса: что здесь главное и не пересекает ли его левый верхний угол. Такой взгляд со стороны ловит большинство проблем ещё до заказа. Если главного объекта в кадре нет вовсе — фактура, орнамент, абстракция, — вопрос снимается: такие принты на Samsung Galaxy A26 5G садятся вообще без компромиссов.</p><p>Дальше всё делается в конструкторе: масштаб, поворот, слои, цвет фона под картинкой, надпись выбранным шрифтом. Сдвинуть фото на пару пикселей — секунда, а разницу на готовом чехле видно с первого взгляда.</p>',
	 NULL, NULL, 1);

-- xiaomi-redmi-note-14-4g — кут: розмір корпусу і хват, велика площа під принт
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-xiaomi-redmi-note-14-4g', 'template',
	 'Чохол з фото на замовлення для Xiaomi Redmi Note 14 4G', 'Чехол с фото на заказ для Xiaomi Redmi Note 14 4G',
	 'Чохол з фото для Xiaomi Redmi Note 14 4G — друк | FLOY', 'Чехол с фото для Xiaomi Redmi Note 14 4G — печать | FLOY',
	 'Друкуємо фото на чохлі для Xiaomi Redmi Note 14 4G. Екран 6,67 дюйма означає велику спинку — на ній тримаються навіть детальні панорамні кадри.',
	 'Печатаем фото на чехле для Xiaomi Redmi Note 14 4G. Экран 6,67 дюйма означает большую спинку — на ней держатся даже детальные панорамные кадры.',
	 '<h2>Велика спинка — це можливість</h2><p>Xiaomi Redmi Note 14 4G належить до тих телефонів, що вже не поміщаються в кишеню джинсів по-людськи. Екран 6,67 дюйма, відповідний корпус, і спинка виходить площею з невелику листівку. Для друку це прямий плюс: на такому форматі виживають кадри, які на компактному чохлі перетворилися б на кашу.</p><p>Йдеться про кадри з деталями — на спинці Xiaomi Redmi Note 14 4G вони не гинуть. Вулиця з вивісками, гірський хребет з кількома планами, групове фото, де видно обличчя всіх шести людей, розворот старої мапи. На маленькому корпусі все це стискається до плям — тут кожна деталь лишається на місці.</p><h3>Хват диктує, де ставити головне</h3><p>Великий телефон тримають інакше: долоня охоплює нижню половину, пальці лягають на боки приблизно на третині висоти від низу. Дві речі з цього випливають одразу. Нижні два-три сантиметри чохла в руці майже завжди закриті — дрібний підпис там видно лише коли телефон лежить окремо. І бічні краї теж частково під пальцями, тому важливі елементи ближче до центру.</p><p>Верх у Redmi Note 14 4G лишається відкритим, але саме туди виведений модуль камер у лівому куті. Найспокійніша схема для такого корпусу: головний об&#39;єкт у середній третині, фон угорі й унизу, текст — праворуч від центру або під зображенням.</p><h3>Чого не варто робити з великим форматом</h3><p>Спокуса заповнити всю площу колажем із восьми фотографій висока, і майже завжди програшна. У руці чохол бачать із відстані витягнутої руки, а не з двадцяти сантиметрів: вісім дрібних кадрів зливаються в строкате полотно. Два-три великі працюють значно краще, а одне на всю спинку — ще краще.</p><p>Зате велика площа дозволяє те, чого не витримує компактний корпус, — довгий текст. Цитата у два-три рядки, куплет, дата з назвою міста під фотографією читаються тут спокійно, без напруження очей. Єдине правило: не притискайте рядки до самого краю. Залиште поле хоча б у кілька міліметрів, інакше текст візуально впирається в бортик чохла й виглядає обрізаним.</p><p>Друга спокуса — розтягнути горизонтальне фото на вертикальний чохол. Обрізається завжди найцікавіше. Простіше взяти з кадру фрагмент, який ви й так вважаєте головним, і дати йому весь простір.</p><p>У конструкторі це кілька рухів: завантажити зображення, підігнати масштаб, посунути, додати напис, за потреби залити фон кольором. Чохол для Сяомі Редмі Ноут 14 виходить помітним хоча б через розмір — тим більше сенсу поставити на нього щось своє.</p>',
	 '<h2>Большая спинка — это ресурс</h2><p>Xiaomi Redmi Note 14 4G относится к тем телефонам, которые в карман джинсов уже нормально не заходят. Экран 6,67 дюйма, соответствующий корпус, и спинка получается размером с небольшую открытку. Для печати это чистый плюс: на таком формате выживают кадры, которые на компактном чехле превратились бы в мешанину.</p><p>Речь о кадрах с деталями — на спинке Xiaomi Redmi Note 14 4G они не пропадают. Улица с вывесками, горный хребет в несколько планов, общее фото, где различимы лица всех шестерых, разворот старой карты. На маленьком корпусе всё это сжимается в пятна, здесь же каждая мелочь остаётся читаемой.</p><h3>Хват подсказывает, где ставить главное</h3><p>Крупный телефон держат иначе: ладонь охватывает нижнюю половину, пальцы ложатся на боковины примерно на трети высоты от низа. Отсюда сразу два следствия. Нижние два-три сантиметра чехла в руке почти всегда закрыты, и мелкую подпись там видно, только когда аппарат лежит отдельно. Боковые края тоже частично под пальцами, так что важные элементы держите ближе к центру.</p><p>Верх у Redmi Note 14 4G остаётся открытым, но именно туда, в левый угол, вынесен модуль камер. Самая спокойная схема для такого корпуса: главный объект в средней трети, фон сверху и снизу, текст справа от центра или под изображением.</p><h3>Чего не стоит делать с большим форматом</h3><p>Соблазн заполнить всю площадь коллажем из восьми фотографий велик и почти всегда проигрышен. Чехол разглядывают с расстояния вытянутой руки, а не с двадцати сантиметров: восемь мелких кадров сливаются в пёстрое полотно. Два-три крупных работают заметно лучше, а один во всю спинку — ещё лучше.</p><p>Зато большая площадь разрешает то, чего не выдерживает компактный корпус, — длинный текст. Цитата в две-три строки, куплет, дата с названием города под фотографией читаются здесь спокойно, без напряжения. Правило одно: не прижимайте строки к самому краю. Оставьте поле хотя бы в несколько миллиметров, иначе текст упирается в бортик чехла и кажется обрезанным.</p><p>Второй соблазн — растянуть горизонтальный снимок на вертикальный чехол. Обрезается при этом всегда самое интересное. Логичнее вырезать из кадра тот фрагмент, который вы и так считаете главным, и отдать ему всё пространство.</p><p>В конструкторе это несколько движений: загрузить изображение, подогнать масштаб, сдвинуть, добавить надпись, при необходимости залить фон цветом. Чехол для Сяоми Редми Ноут 14 заметен уже из-за размера — тем больше причин поставить на него что-то своё.</p>',
	 NULL, NULL, 1);

-- iphone-17-pro-max — кут: свіжий флагман, персоналізація дорогого апарата; побічне — широке плато камер
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-iphone-17-pro-max', 'template',
	 'Чохол з фото на замовлення для iPhone 17 Pro Max', 'Чехол с фото на заказ для iPhone 17 Pro Max',
	 'Чохол з фото на замовлення для iPhone 17 Pro Max | FLOY', 'Чехол с фото на заказ для iPhone 17 Pro Max | FLOY',
	 'Власний принт на чохлі для iPhone 17 Pro Max. Камерне плато займає верх майже на всю ширину, тому все важливе в композиції ставимо нижче за нього.',
	 'Свой принт на чехле для iPhone 17 Pro Max. Камерное плато занимает верх почти во всю ширину, поэтому всё важное в композиции ставим ниже него.',
	 '<h2>Однакових таких телефонів дуже багато</h2><p>iPhone 17 Pro Max купують не для того, щоб він був як у всіх, але виходить саме так. Кольорів у лінійці кілька, і на будь-якій зустрічі на столі опиняються два-три однакові апарати. Далі на них вдягають чохли — і ті теж однакові, бо продаються в тих самих кількох магазинах.</p><p>Друк власного зображення — по суті єдиний спосіб зробити дорогий телефон особистим, не втручаючись у сам пристрій. Апарат лишається заводським, змінюється тільки те, що зверху.</p><h3>Плато камер забирає верх</h3><p>У 17 Pro Max блок камер зроблений широким плато, яке тягнеться майже через усю ширину корпусу вгорі. Це найсильніша зміна вигляду за останні роки, і на макет вона впливає більше, ніж будь-що інше.</p><p>Верхня смуга чохла фактично випадає з композиції. Ставити туди обличчя, підпис або центральний елемент немає сенсу — на прев&#39;ю вони виглядають нормально, на готовому чохлі опиняються навколо плато. Робочий підхід: під плато лишається рівний фон — небо, вода, стіна, суцільний колір, — а все значуще починається нижче, у середній частині. Зображення при цьому не виглядає обрізаним, воно просто побудоване під конкретний корпус.</p><h3>Що на цю модель зазвичай ставлять</h3><p>Аудиторія тут своя, і запити відрізняються від масових моделей. Помітно частіше просять стриманіше: одна фотографія без тексту, монограма з двох літер, суцільний глибокий колір з дрібним написом збоку, кадр з поїздки в приглушених тонах. Яскраві багатоелементні колажі на iPhone 17 Pro Max замовляють рідше.</p><p>Окремо стоїть подарунковий сценарій. Телефон такого рівня часто вручають на подію: випуск, весілля, ювілей, велике замовлення. Сам апарат при цьому знеособлений — він однаковий у мільйонах коробок по всьому світу. Надрукований чохол із датою, ім&#39;ям або спільним кадром додає до подарунка рівно те, чого в коробці немає, і на тлі вартості самого телефона обходиться в дрібницю.</p><p>Ще одна деталь, характерна саме для нових флагманів: чохол часто беруть у перший тиждень після покупки, разом із захисним склом, коли телефон ще не встиг подряпатися. У цьому випадку є сенс одразу зробити два макети — робочий, спокійніший, і другий під настрій. Перемикати чохли простіше, ніж щоразу шукати компроміс в одному.</p><p>Конструктор дозволяє зібрати обидва за один вечір: фото, шрифт, колір фону, шари, масштаб. Айфон 17 Про Макс у результаті перестає бути просто ще одним чорним прямокутником на столі.</p>',
	 '<h2>Одинаковых таких аппаратов очень много</h2><p>iPhone 17 Pro Max берут не для того, чтобы он был как у всех, но получается именно так. Цветов в линейке немного, и на любой встрече на столе оказываются два-три одинаковых телефона. Дальше на них надевают чехлы — тоже одинаковые, потому что продаются они в одних и тех же нескольких магазинах.</p><p>Печать собственного изображения — по сути единственный способ сделать дорогой аппарат личным, не трогая сам аппарат. Устройство остаётся заводским, меняется только то, что сверху.</p><h3>Плато камер забирает верх</h3><p>Блок камер в 17 Pro Max выполнен широким плато, которое проходит почти через всю ширину корпуса. Это самое заметное изменение внешности за последние поколения, и на макет оно влияет сильнее всего остального.</p><p>Верхняя полоса чехла из композиции фактически выпадает. Лицо, подпись или центральный элемент туда ставить бессмысленно: в превью всё выглядит прилично, а на готовом чехле оказывается вокруг плато. Рабочий подход другой — под плато оставляем ровный фон: небо, воду, стену, плотный цвет, — а всё значимое начинается ниже, в средней части. Картинка при этом не кажется обрезанной, она просто построена под конкретный корпус.</p><h3>Что на эту модель ставят чаще всего</h3><p>Аудитория здесь своя, и запросы отличаются от массовых моделей. Заметно чаще просят сдержаннее: одна фотография без текста, монограмма из двух букв, плотный глубокий цвет с мелкой надписью сбоку, кадр из поездки в приглушённой гамме. Пёстрые многоэлементные коллажи на iPhone 17 Pro Max заказывают редко.</p><p>Отдельно стоит подарочный сюжет. Телефон такого класса нередко вручают к событию: выпускной, свадьба, юбилей, крупная сделка. Сам аппарат при этом обезличен — он одинаков в миллионах коробок по всему миру. Печатный чехол с датой, именем или общим снимком добавляет к подарку ровно то, чего в коробке нет, и на фоне стоимости самого телефона обходится в мелочь.</p><p>Есть деталь, свойственная именно свежим флагманам: чехол часто покупают в первую неделю, вместе с защитным стеклом, пока телефон ещё не поцарапан. В этом случае имеет смысл сразу собрать два макета — деловой, поспокойнее, и второй под настроение. Менять чехлы проще, чем каждый раз искать компромисс в одном.</p><p>Конструктор позволяет сделать оба за один вечер: фото, шрифт, цвет фона, слои, масштаб. Айфон 17 Про Макс после этого перестаёт быть очередным чёрным прямоугольником на столе.</p>',
	 NULL, NULL, 1);

-- samsung-galaxy-a36-5g — кут: робочий/діловий варіант (монограма, логотип, мінімалізм)
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-samsung-galaxy-a36-5g', 'template',
	 'Чохол з фото на замовлення для Samsung Galaxy A36 5G', 'Чехол с фото на заказ для Samsung Galaxy A36 5G',
	 'Чохол з друком для Samsung Galaxy A36 5G на замовлення | FLOY', 'Чехол с печатью для Samsung Galaxy A36 5G на заказ | FLOY',
	 'Друк на чохлі для Samsung Galaxy A36 5G: монограма, логотип або спокійний однотонний фон. Матова поверхня замість глянцю, який збирає відбитки.',
	 'Печать на чехле для Samsung Galaxy A36 5G: монограмма, логотип или спокойный однотонный фон. Матовая поверхность вместо глянца, собирающего отпечатки.',
	 '<h2>Коли телефон переважно робочий</h2><p>Samsung Galaxy A36 5G часто виявляється саме таким апаратом: на ньому робоча пошта, месенджери з клієнтами, банківські застосунки, і в руках він буває на людях по кілька разів на день. Малюнок з драконом сюди не дуже пасує, а ходити в чорному силіконі з магазину — рішення без жодної думки.</p><p>Між цими крайнощами є цілий пласт варіантів, і всі вони збираються в тому ж конструкторі, що й фото з відпустки.</p><h3>Три спокійні схеми</h3><ul><li><strong>Монограма.</strong> Дві літери ініціалів по центру або в нижньому правому куті, тонкий шрифт, фон одного кольору. Читається як фірмовий знак, а не як підпис на зошиті.</li><li><strong>Логотип.</strong> Якщо у вас своя справа — знак компанії на однотонному фоні. Телефон стає частиною того ж набору, що візитівка й підпис у пошті. Для невеликої команди можна зробити однакові чохли на всіх, у кого ця сама модель.</li><li><strong>Колір без зображення.</strong> Глибокий синій, графіт, темна зелень, теракота. Жодного принта, тільки суцільна заливка — і телефон уже не схожий на сусідній зі стенду.</li></ul><p>Спільне у всіх трьох: багато вільного простору. Спинка Samsung Galaxy A36 5G у діловому варіанті — це порожнеча й один акцент, а не заповнена площа. Помилка тут майже завжди одна й та сама — спроба вмістити і знак, і назву, і слоган, і контакти. Телефон не візитівка, дрібний блок тексту на ньому ніхто читати не буде.</p><p>Про шрифт варто сказати окремо, бо в діловому макеті він робить майже всю роботу. Ті самі дві літери тонким гротеском і жирним рубаним читаються як речі з різних світів. Якщо вагаєтесь, беріть найпростіший з доступних і зменшуйте розмір: стриманий напис рідко виглядає помилкою, великий декоративний — часто.</p><h3>Практичний момент із глянцем</h3><p>Чорний Galaxy A36 5G має глянсову задню панель, і відбитки пальців на ній видно постійно — телефон виглядає заяложеним уже через годину після протирання. Друкований чохол цю проблему просто прибирає: поверхня інша, сліди на ній не збираються так помітно.</p><p>Ще одна побутова деталь. Телефон у робочому режимі часто передають з рук у руки — показати документ, дати відсканувати код, підписати доставку. Спинку в цей момент бачать сторонні люди зблизька. Тому дрібний напис на діловому чохлі краще робити стриманим: ім&#39;я, ініціали, назва компанії. Особисті фото залиште для другого чохла: зібрати ще один макет для Гелексі А36 — питання кількох хвилин.</p>',
	 '<h2>Когда телефон в основном рабочий</h2><p>Samsung Galaxy A36 5G нередко оказывается именно таким аппаратом: рабочая почта, переписка с клиентами, банковские приложения, и на людях он появляется по нескольку раз в день. Картинка с драконом сюда подходит слабо, а ходить в чёрном силиконе из перехода — решение вообще без мысли.</p><p>Между этими крайностями лежит целый пласт вариантов, и собираются они в том же конструкторе, что и снимки из отпуска.</p><h3>Три спокойные схемы</h3><ul><li><strong>Монограмма.</strong> Две буквы инициалов по центру или в нижнем правом углу, тонкий шрифт, фон одного цвета. Выглядит как фирменный знак, а не как подпись на тетради.</li><li><strong>Логотип.</strong> Если у вас своё дело — знак компании на однотонном фоне. Телефон попадает в тот же набор, что визитка и подпись в письме. Небольшой команде можно сделать одинаковые чехлы всем, у кого эта же модель.</li><li><strong>Цвет без изображения.</strong> Глубокий синий, графит, тёмная зелень, терракота. Никакого принта, только сплошная заливка — и аппарат уже не двойник соседнего со стенда.</li></ul><p>Общее у всех трёх — много воздуха. Спинка Samsung Galaxy A36 5G в деловом варианте строится на пустом поле с одним акцентом, а не на заполненной площади. Ошибка тут почти всегда одна: попытка уместить и знак, и название, и слоган, и контакты. Телефон не визитка, мелкий блок текста на нём читать никто не станет.</p><p>О шрифте стоит сказать отдельно: в деловом макете он делает почти всю работу. Одни и те же две буквы тонким гротеском и жирным рубленым воспринимаются как вещи из разных миров. Сомневаетесь — берите самый простой из доступных и уменьшайте кегль: сдержанная надпись редко выглядит ошибкой, крупная декоративная — часто.</p><h3>Практический момент с глянцем</h3><p>У чёрного Galaxy A36 5G задняя панель глянцевая, и отпечатки на ней заметны постоянно: через час после протирания телефон снова выглядит захватанным. Печатный чехол эту проблему убирает — поверхность другая, следы на ней так не копятся.</p><p>Ещё одна бытовая деталь. Рабочий телефон часто передают из рук в руки: показать документ, дать отсканировать код, подтвердить доставку. Спинку в этот момент видят посторонние с близкого расстояния. Поэтому мелкую надпись на деловом чехле лучше держать сдержанной: имя, инициалы, название компании. Личные снимки оставьте для второго чехла: собрать ещё один макет для Галакси А36 — вопрос пары минут.</p>',
	 NULL, NULL, 1);

-- xiaomi-redmi-13 — кут: подарунковий сценарій
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-xiaomi-redmi-13', 'template',
	 'Чохол з фото на замовлення для Xiaomi Redmi 13', 'Чехол с фото на заказ для Xiaomi Redmi 13',
	 'Чохол з фото для Xiaomi Redmi 13 на подарунок | FLOY', 'Чехол с фото для Xiaomi Redmi 13 в подарок | FLOY',
	 'Чохол із власним фото для Xiaomi Redmi 13 як подарунок. Достатньо знати модель телефона — макет зі спільним кадром зберете в конструкторі за вечір.',
	 'Чехол с личным фото для Xiaomi Redmi 13 в подарок. Достаточно знать модель телефона — макет с общим снимком соберёте в конструкторе за один вечер.',
	 '<h2>Подарунок для того, хто нічого не просить</h2><p>Є категорія людей, яким складно щось дарувати: на питання «що тобі купити» вони відповідають «нічого не треба». Чохол з надрукованим фото працює тут краще за чергову чашку. Річ щоденна, витратна за природою, і при цьому цілком особиста — таку не купиш у переході.</p><p>Xiaomi Redmi 13 у цьому сенсі зручний: модель поширена, тож імовірність, що телефон саме такий, висока, а розібратися напевно — питання тридцяти секунд.</p><h3>Як дізнатися модель непомітно</h3><p>Найпростіше — узяти телефон у руки під приводом «покажи фото» і подивитися напис дрібним шрифтом на задній панелі знизу. Другий шлях: у налаштуваннях розділ «Про телефон», перший рядок. Третій, найтихіший — запитати в когось із родини, хто цей телефон купував або допомагав налаштовувати. Вирізи в чохлі робляться під конкретний корпус, тому назву варто знати точно, а не приблизно.</p><h3>Що друкувати, щоб влучити</h3><p>Найнадійніші сюжети для чохла Xiaomi Redmi 13 перевірені сотнями замовлень:</p><ul><li>спільне фото — ваше з ним, сімейне, з поїздки, яку обидва пам&#39;ятаєте;</li><li>домашня тварина великим планом, без тексту;</li><li>дата й кілька слів, зрозумілих тільки вам двом;</li><li>кадр із дитинства, відсканований зі старого альбому.</li></ul><p>Останній варіант діє найсильніше. Стара фотографія на новому телефоні — це той тип подарунка, який не викидають при зміні апарата, а перевозять у шухляду.</p><p>Чого краще уникати: перевантажених колажів і жартів, які через місяць перестануть бути смішними. Чохол носять щодня, і жарт має витримати цей ритм. З тієї ж причини обережніше з надто дрібним текстом: те, що чудово читається на екрані ноутбука, на спинці телефона перетворюється на сіру смужку.</p><p>Про сам момент вручення теж варто подумати. Чохол погано працює як єдиний подарунок у порожній коробці — надто буденна річ на вигляд. Зате він добре доповнює основне: конверт, книжку, квіти. Людина спершу відкриває головне, а потім бачить власне фото на телефоні, який щойно лежав у неї в кишені. Ефект у цю секунду сильніший, ніж від будь-якої окремої речі того ж рівня.</p><p>Ще одна порада для тих, хто дарує вперше. Не намагайтеся вгадати улюблений колір — беріть фотографію. Колір може не збігтися зі смаком, а спільний кадр не промахується ніколи. Зібрати макет для Сяомі Редмі 13 у конструкторі можна за вечір: завантажили фото, підписали, підібрали шрифт, подивилися прев&#39;ю. Чохол з фото на замовлення тим і хороший, що робиться під одну конкретну людину.</p>',
	 '<h2>Подарок тому, кто ничего не просит</h2><p>Есть люди, которым сложно что-то дарить: на вопрос «что тебе купить» они отвечают «ничего не надо». Чехол с напечатанным фото здесь работает лучше очередной кружки. Вещь ежедневная, по природе расходная и при этом абсолютно личная — такую в переходе не купишь.</p><p>Xiaomi Redmi 13 в этом смысле удобен: модель распространённая, так что вероятность попасть высокая, а уточнить наверняка — дело тридцати секунд.</p><h3>Как узнать модель незаметно</h3><p>Проще всего взять телефон в руки под предлогом «покажи фотографии» и прочитать мелкую надпись на задней панели внизу. Второй путь: настройки, раздел «О телефоне», самая первая строка. Третий, самый тихий, — спросить у кого-то из родни, кто этот телефон покупал или помогал настраивать. Вырезы делаются под конкретный корпус, поэтому название нужно знать точно, а не примерно.</p><h3>Что печатать, чтобы попасть</h3><p>Самые надёжные сюжеты для чехла Xiaomi Redmi 13 проверены сотнями заказов:</p><ul><li>общая фотография — ваша с ним, семейная, из поездки, которую помните оба;</li><li>домашнее животное крупным планом, без текста;</li><li>дата и несколько слов, понятных только вам двоим;</li><li>кадр из детства, отсканированный из старого альбома.</li></ul><p>Последний вариант бьёт точнее всего. Старый снимок на новом телефоне — из тех подарков, которые при смене аппарата не выбрасывают, а перекладывают в ящик.</p><p>Чего лучше избегать: перегруженных коллажей и шуток, которые через месяц перестанут быть смешными. Чехол носят каждый день, и шутка должна этот ритм выдержать. По той же причине аккуратнее с очень мелким текстом: то, что прекрасно читается на экране ноутбука, на спинке телефона превращается в серую полоску.</p><p>Стоит продумать и сам момент вручения. Единственным подарком в пустой коробке чехол смотрится слабо — слишком обыденная на вид вещь. Зато он отлично достраивает основное: конверт, книгу, цветы. Человек сначала открывает главное, а потом видит собственную фотографию на телефоне, который только что лежал у него в кармане. Эффект в эту секунду сильнее, чем от любой отдельной вещи того же порядка.</p><p>Совет для тех, кто дарит впервые. Не пытайтесь угадать любимый цвет — берите фотографию. С цветом можно не совпасть, а общий кадр не промахивается никогда. Собрать макет для Сяоми Редми 13 в конструкторе получится за вечер: загрузили фото, подписали, подобрали шрифт, посмотрели превью. Чехол с фото на заказ тем и хорош, что делается под одного конкретного человека.</p>',
	 NULL, NULL, 1);

-- xiaomi-redmi-note-11 — кут: парний/сімейний набір з двох однакових чохлів (одна маска на 11 і 11s)
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-xiaomi-redmi-note-11', 'template',
	 'Чохол з фото на замовлення для Xiaomi Redmi Note 11 / 11s', 'Чехол с фото на заказ для Xiaomi Redmi Note 11 / 11s',
	 'Чохол з фото для Xiaomi Redmi Note 11 та 11s — друк | FLOY', 'Чехол с фото для Xiaomi Redmi Note 11 и 11s — печать | FLOY',
	 'Друк фото на чохлі для Xiaomi Redmi Note 11 та 11s. Корпус у цих моделей однаковий, тому два парні чохли виходять ідентичними за формою й вирізами.',
	 'Печать фото на чехле для Xiaomi Redmi Note 11 и 11s. Корпус у этих моделей одинаковый, поэтому парные чехлы получаются идентичными по форме и вырезам.',
	 '<h2>Два телефони — один задум</h2><p>Xiaomi Redmi Note 11 свого часу розійшовся дуже широко, і зараз він часто зустрічається парами: у чоловіка й дружини, у двох сестер, у мами й дочки-підлітка. Купували разом, в одному магазині, іноді навіть в один день. Звідси й сценарій, якого немає в рідкісних моделей — парні чохли.</p><p>Технічно тут усе просто. Redmi Note 11 і 11s мають однаковий корпус, тому маска для друку в них спільна: незалежно від того, у кого яка версія, два чохли вийдуть однаковими за формою й вирізами.</p><h3>Як роблять пару</h3><p>Три схеми, які реально працюють.</p><p><strong>Одне фото на два чохли.</strong> Знімок ділиться навпіл: на одному чохлі ліва частина, на другому права. Поруч кадр складається, окремо кожна половина живе самостійно. Найкраще підходять горизонтальні фото, де є двоє людей або два об&#39;єкти.</p><p><strong>Однакова тема, різні кадри.</strong> Той самий колір фону й той самий шрифт, але в кожного своє фото. Здалеку набір читається як комплект, зблизька — як дві різні речі.</p><p><strong>Дзеркальний напис.</strong> На одному чохлі фраза, на другому — її продовження. Працює у пар і в подруг, які часто фотографуються разом.</p><h3>Сімейний варіант</h3><p>Із дітьми логіка інша. Дитині зазвичай друкують те, що вона сама вибрала, а батькам — фото цієї ж дитини. Виходить пара без зайвої символіки: у кожного своє, але зв&#39;язок очевидний. Підліток при цьому не носить на телефоні напис «мама і донька» — а саме цього в такому віці найбільше й уникають.</p><p>Буває й ширший випадок — не пара, а невелика група. Однокурсники, команда, компанія, що разом їздила в похід: одна фотографія розкладається на кілька чохлів, кожному свій фрагмент. Xiaomi Redmi Note 11 для такого підходить саме тому, що в подібній компанії вона майже напевно є не в однієї людини.</p><p>Практичне зауваження. Телефон із 2022 року в багатьох уже пожив: подряпини на рамці, потертий кут, вицвілий старий чохол. Новий друкований чохол на такому апараті працює сильніше, ніж на щойно купленому, — контраст помітніший. І ще: якщо робите два, робіть їх в одному замовленні. Кольори між партіями можуть трохи відрізнятися, а в парі це видно одразу.</p><p>Далі все звично: фото, шрифт, колір фону, шари в конструкторі. Чохол на Сяомі Редмі Ноут 11 — річ недорога, а два однакові виглядають як домовленість, про яку не треба говорити вголос.</p>',
	 '<h2>Два телефона — один замысел</h2><p>Xiaomi Redmi Note 11 в своё время разошёлся огромным тиражом, и сейчас он часто встречается парами: у мужа и жены, у двух сестёр, у мамы и дочери-подростка. Покупали вместе, в одном магазине, порой в один день. Отсюда сценарий, которого нет у редких моделей, — парные чехлы.</p><p>Технически всё просто. У Redmi Note 11 и 11s корпус одинаковый, значит и маска для печати общая: чья бы версия ни была, два чехла совпадут и по форме, и по вырезам.</p><h3>Как делают пару</h3><p>Три схемы, которые действительно работают.</p><p><strong>Один снимок на два чехла.</strong> Фотография делится пополам: на одном чехле левая часть, на втором правая. Рядом кадр собирается целиком, по отдельности каждая половина смотрится самостоятельно. Лучше всего подходят горизонтальные снимки с двумя людьми или двумя объектами.</p><p><strong>Общая тема, разные кадры.</strong> Тот же цвет фона и тот же шрифт, но фотография у каждого своя. Издали набор читается как комплект, вблизи — как две разные вещи.</p><p><strong>Надпись с продолжением.</strong> На одном чехле фраза, на втором её вторая половина. Приём для пар и для подруг, которые часто снимаются вместе.</p><h3>Семейный вариант</h3><p>С детьми логика другая. Ребёнку печатают то, что он выбрал сам, а родителю — фотографию этого же ребёнка. Пара выходит без лишней символики: у каждого своё, но связь очевидна. И подросток при этом не носит на телефоне надпись «мама и дочка» — как раз этого в таком возрасте избегают сильнее всего.</p><p>Бывает и более широкий случай — не пара, а небольшая группа. Однокурсники, команда, компания, съездившая вместе в поход: одна фотография раскладывается на несколько чехлов, каждому свой фрагмент. Xiaomi Redmi Note 11 для такого годится именно потому, что в подобной компании она наверняка есть не у одного человека.</p><p>Практическое замечание. Аппарат родом из 2022 года у многих уже пожил: царапины на рамке, потёртый угол, выцветший старый чехол. На таком телефоне свежий печатный чехол срабатывает сильнее, чем на только что купленном, — контраст заметнее. И ещё: если делаете два, оформляйте их одним заказом. Между партиями цвет может слегка отличаться, а в паре это видно сразу.</p><p>Дальше всё привычно: фото, шрифт, цвет фона, слои в конструкторе. Чехол на Сяоми Редми Ноут 11 стоит недорого, а два одинаковых читаются как договорённость, которую не нужно проговаривать вслух.</p>',
	 NULL, NULL, 1);

-- ─── пачка 3 (2026-08-04) ───────────────────────────────────────────────────

-- zte-nubia-neo-3-gt — кут: ігровий телефон, який тримають горизонтально; композицію перевіряємо боком
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-zte-nubia-neo-3-gt', 'template',
	 'Чохол з фото на замовлення для ZTE Nubia Neo 3 GT', 'Чехол с фото на заказ для ZTE Nubia Neo 3 GT',
	 'Чохол з принтом для ZTE Nubia Neo 3 GT — друк | FLOY', 'Чехол с принтом для ZTE Nubia Neo 3 GT — печать | FLOY',
	 'Свій принт на чохлі для ZTE Nubia Neo 3 GT. Ігровий телефон тримають горизонтально, тому макет тут варто перевіряти повернутим на бік.',
	 'Свой принт на чехле для ZTE Nubia Neo 3 GT. Игровой телефон держат горизонтально, поэтому макет здесь стоит проверять повёрнутым на бок.',
	 '<h2>Цей телефон частіше лежить боком</h2><p>ZTE Nubia Neo 3 GT беруть під ігри. Тригери на бічних гранях, підсвітка, вага за двісті грамів — на апарат для листування він схожий мало. І тримають його інакше: не вертикально однією рукою, а горизонтально двома, по кілька годин поспіль.</p><p>Для принта це змінює головне. Макет ви збираєте вертикально, а бачити його будете переважно поверненим на дев&#39;яносто градусів — між долонями, збоку, під кутом.</p><h3>Подивіться на макет боком</h3><p>Перевірка займає секунду: нахиліть голову вліво й гляньте на прев&#39;ю. Портрет, який у вертикальному положенні виглядав нормально, у грі лежить на боці — і саме таким його бачать усі, хто сидить поруч. Сюжети, яким байдужа орієнтація, тут у виграші: геометрія, текстура, симетричний персонаж, емблема, абстрактний градієнт.</p><p>Друга особливість хвату. У горизонтальному положенні долоні накривають ліву й праву третини чохла, вільною лишається середня вертикальна смуга. Нік, обличчя персонажа чи знак команди тримайте по центру — з країв їх просто не буде видно рівно в ті години, коли телефон у роботі.</p><h3>Тут можна те, чого не можна на робочому</h3><p>Ігровий апарат рідко буває єдиним. Часто це другий телефон, з яким не ходять у банк і не показують документи, а значить, і планка пристойності на спинці зовсім інша. Персонаж у повний зріст, кислотний неон, власний нік великими літерами, кадр із гри — усе те, що на діловому телефоні виглядало б дивно, тут доречне.</p><p>Готових чохлів із такими сюжетами під ZTE Nubia Neo 3 GT у магазинах не буває майже ніколи: ігрові принти під конкретну гру ніхто не возить, а ваш нік — тим більше. Тому друк для цієї моделі закриває запит, який інакше не закривається взагалі.</p><p>Врахуйте лише заводську зовнішність апарата. Neo 3 GT продається в помітних кольорах на кшталт електрично-жовтого, і корпус сам по собі кричущий. Якщо принт теж яскравий і строкатий, телефон перетворюється на суцільну пляму. Простіше піти в один із двох боків: або взяти чохол у тон корпусу, або, навпаки, зробити його темним і графічним, щоб він гасив надлишок.</p><p>Побутова деталь наостанок. Neo 3 GT важкий, і в довгих сесіях він то в руках, то на столі поруч із павербанком, спинкою вгору. Чохол на цьому телефоні бачать більше, ніж на будь-якому іншому, — у тому числі ті, хто дивиться на вашу гру через плече. Зібрати макет для ЗТЕ Нубія Нео 3 ДжіТі можна за один перерв між матчами: фото або готовий принт, напис, шрифт, колір фону.</p>',
	 '<h2>Этот телефон чаще лежит боком</h2><p>ZTE Nubia Neo 3 GT берут под игры. Триггеры на боковых гранях, подсветка, вес за двести граммов — на аппарат для переписки он похож слабо. И держат его иначе: не вертикально одной рукой, а горизонтально двумя, по нескольку часов подряд.</p><p>Для принта отсюда следует главное. Макет вы собираете вертикально, а видеть его будете в основном повёрнутым на девяносто градусов — между ладонями, сбоку, под углом.</p><h3>Взгляните на макет боком</h3><p>Проверка занимает секунду: наклоните голову влево и посмотрите на превью. Портрет, который вертикально смотрелся нормально, в игре лежит на боку — и именно таким его видят все, кто сидит рядом. Сюжеты, безразличные к ориентации, здесь в плюсе: геометрия, текстура, симметричный персонаж, эмблема, абстрактный градиент.</p><p>Вторая особенность хвата. В горизонтальном положении ладони накрывают левую и правую трети чехла, свободной остаётся средняя вертикальная полоса. Ник, лицо персонажа или знак команды держите по центру — с краёв их не будет видно ровно в те часы, когда телефон в деле.</p><h3>Здесь можно то, чего нельзя на рабочем</h3><p>Игровой аппарат редко бывает единственным. Чаще это второй телефон, с которым не идут в банк и не показывают документы, а значит, и планка приличий на спинке совсем другая. Персонаж в полный рост, кислотный неон, собственный ник крупными буквами, кадр из игры — всё, что на деловом телефоне выглядело бы странно, здесь на своём месте.</p><p>Готовых чехлов с такими сюжетами под ZTE Nubia Neo 3 GT в магазинах почти не бывает: принты под конкретную игру никто не возит, а ваш ник — тем более. Печать для этой модели закрывает запрос, который иначе не закрывается вообще.</p><p>Стоит учесть и заводскую внешность аппарата. Neo 3 GT продаётся в заметных цветах вроде электрически-жёлтого, корпус и сам по себе кричащий. Если принт тоже яркий и пёстрый, телефон превращается в сплошное пятно. Проще уйти в одну из двух сторон: либо чехол в тон корпусу, либо, наоборот, тёмный и графичный, гасящий избыток.</p><p>Бытовая деталь напоследок. Neo 3 GT тяжёлый, и в долгих сессиях он то в руках, то на столе рядом с павербанком, спинкой вверх. Чехол на этом телефоне видят чаще, чем на любом другом, — включая тех, кто смотрит вашу игру через плечо. Собрать макет для ЗТЕ Нубия Нео 3 ДжиТи можно за один перерыв между матчами: фото или готовый принт, надпись, шрифт, цвет фона.</p>',
	 NULL, NULL, 1);

-- samsung-galaxy-a17 — кут: як вибрати сюжет, який не набридне за два роки
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-samsung-galaxy-a17', 'template',
	 'Чохол з фото на замовлення для Samsung Galaxy A17', 'Чехол с фото на заказ для Samsung Galaxy A17',
	 'Чохол з фото для Samsung Galaxy A17 — друк на замовлення | FLOY', 'Чехол с фото для Samsung Galaxy A17 — печать на заказ | FLOY',
	 'Друкуємо ваш принт на чохлі для Samsung Galaxy A17. Розбираємо, які сюжети не набридають за рік-два щоденного носіння, а які втомлюють за місяць.',
	 'Печатаем ваш принт на чехле для Samsung Galaxy A17. Разбираем, какие сюжеты не надоедают за год-два ежедневной носки, а какие утомляют за месяц.',
	 '<h2>Принт, який доведеться бачити щодня</h2><p>Samsung Galaxy A17 беруть надовго. Це не апарат «на сезон»: телефон А-серії живе в кишені кілька років, і чохол на ньому теж міняють не щомісяця. Виходить, картинку, яку ви оберете сьогодні, ви побачите тисячі разів — у транспорті, на роботі, вночі на тумбочці.</p><p>Це трохи інша задача, ніж «вибрати гарне». Гарне подобається на екрані ноутбука. Витримує щоденний перегляд — не завжди те саме.</p><h3>Що втомлює першим</h3><p>За досвідом замовлень швидше за все набридають три речі. Меми й гострі жарти: контекст вивітрюється за пару місяців, а телефон лишається. Кислотні градієнти на весь чохол: перші дні вони бадьорять, потім починають дратувати саме через яскравість. І дрібний повторюваний візерунок — око постійно намагається його зчитати й не встигає, від цього виникає відчуття суєти.</p><p>Ще одна пастка — надто конкретна дата чи подія. Чохол із написом про літо конкретного року в грудні виглядає, як застаріла новина. Те саме з логотипами серіалів і музичних турів: сезон закінчується, хайп минає, а силікон лишається таким, як був.</p><h3>Що витримує роки</h3><p>Довше за все живуть спокійні сюжети з особистим значенням:</p><ul><li>місце, де вам добре: море, ліс, вулиця рідного міста;</li><li>тварина — своя, знята зблизька, з простим фоном;</li><li>одна велика форма: силует гори, хвиля, лист, півмісяць;</li><li>приглушена палітра з двох-трьох кольорів без різких переходів.</li></ul><p>Спинка в Гелексі А17 рівна й чимала, тому сюжет видно цілком, а не шматком. Це працює в обидва боки: спокійне зображення виглядає тут виграшно, а зайвий шум у макеті помітний одразу.</p><p>Є ще один спосіб перевірити сюжет заздалегідь, і він майже безпомилковий. Поставте вибране зображення на заставку самого телефона й проживіть із ним тиждень. Ви бачитимете його стільки ж разів, скільки потім бачитимете чохол. Якщо на сьомий день рука не тягнеться змінити картинку — можна друкувати. Якщо набридло на третій, ви щойно зекономили собі чохол.</p><p>Простий тест перед замовленням. Уявіть цей чохол у грудні й у липні. Уявіть його на робочій нараді й на пляжі. Якщо в жодній із чотирьох картинок він не викликає бажання зняти — сюжет вибрано правильно. А якщо все ж набридне, чохол для Samsung Galaxy A17 не та річ, з якою страшно розлучитися: можна надрукувати новий, з іншим кадром, і лишити старий у шухляді про запас.</p>',
	 '<h2>Принт, который придётся видеть каждый день</h2><p>Samsung Galaxy A17 покупают надолго. Это не аппарат на сезон: телефон А-серии живёт в кармане несколько лет, и чехол на нём тоже не меняют ежемесячно. Значит, картинку, выбранную сегодня, вы увидите тысячи раз — в транспорте, на работе, ночью на тумбочке.</p><p>Задача тут чуть иная, чем «выбрать красивое». Красивое нравится на экране ноутбука. Выдерживает ежедневный просмотр — далеко не всегда то же самое.</p><h3>Что утомляет первым</h3><p>По опыту заказов быстрее всего приедаются три вещи. Мемы и острые шутки: контекст выветривается за пару месяцев, а телефон остаётся. Кислотные градиенты во всю спинку: первые дни бодрят, потом начинают раздражать именно яркостью. И мелкий повторяющийся узор — глаз всё время пытается его считать и не успевает, отсюда ощущение суеты.</p><p>Ещё одна ловушка — слишком конкретная дата или событие. Чехол с надписью про лето определённого года в декабре выглядит как устаревшая новость. То же с логотипами сериалов и музыкальных туров: сезон заканчивается, хайп проходит, а силикон остаётся прежним.</p><h3>Что держится годами</h3><p>Дольше всего живут спокойные сюжеты с личным смыслом:</p><ul><li>место, где вам хорошо: море, лес, улица родного города;</li><li>животное — своё, снятое вблизи, на простом фоне;</li><li>одна крупная форма: силуэт горы, волна, лист, полумесяц;</li><li>приглушённая палитра из двух-трёх цветов без резких переходов.</li></ul><p>Спинка у Галакси А17 ровная и немаленькая, поэтому сюжет виден целиком, а не куском. Работает это в обе стороны: спокойное изображение здесь выигрывает, а лишний шум в макете заметен сразу.</p><p>Есть и способ проверить сюжет заранее, почти безошибочный. Поставьте выбранное изображение на обои самого телефона и проживите с ним неделю. Видеть его вы будете столько же раз, сколько потом будете видеть чехол. Не тянет сменить картинку на седьмой день — можно печатать. Надоело на третий — вы только что сэкономили себе чехол.</p><p>Простой тест перед заказом. Представьте этот чехол в декабре и в июле. Представьте его на рабочем совещании и на пляже. Если ни в одной из четырёх картинок снять его не хочется — сюжет выбран верно. А если всё же надоест, чехол для Samsung Galaxy A17 не та вещь, с которой жалко расставаться: печатается новый, с другим кадром, а прежний остаётся в ящике про запас.</p>',
	 NULL, NULL, 1);

-- zte-nubia-v70-design — кут: кілька змінних чохлів на один телефон
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-zte-nubia-v70-design', 'template',
	 'Чохол з фото на замовлення для ZTE Nubia V70 Design', 'Чехол с фото на заказ для ZTE Nubia V70 Design',
	 'Чохол з фото для ZTE Nubia V70 Design — друк | FLOY', 'Чехол с фото для ZTE Nubia V70 Design — печать | FLOY',
	 'Друк власного зображення на чохлі для ZTE Nubia V70 Design. Силіконовий чохол знімається за секунду, тому їх спокійно роблять кілька — під різні випадки.',
	 'Печать своего изображения на чехле для ZTE Nubia V70 Design. Силиконовый чехол снимается за секунду, поэтому их спокойно делают несколько — под разные случаи.',
	 '<h2>Чохол не обов&#39;язково має бути один</h2><p>Звичка тут стара: купили чохол — носимо, поки не порветься. Хоча силіконовий знімається за секунду, і нічого не заважає мати два чи три та міняти їх, як міняють шарф чи ремінець годинника. З друком це стає осмисленим: кожен чохол виходить не просто іншого кольору, а з іншим змістом.</p><p>Для власників ZTE Nubia V70 Design аргумент зайвий — цю модель обирають ті, хто дивиться на вигляд телефона. Слово Design у назві тут не випадкове, і зупинятися на одному оформленні якось нелогічно.</p><h3>Три схеми на вибір</h3><p><strong>Будні й вихідні.</strong> Один спокійний, майже однотонний — з ним ідете на роботу, до лікаря, у державну установу. Другий вільніший: фото, яскравий кадр, напис. Перемикання займає стільки ж часу, скільки перевзутися.</p><p><strong>За сезоном.</strong> Восени й узимку природніше виглядають глибокі темні тони, навесні й улітку — світлі й теплі. Змінювати чохол двічі на рік — приблизно та сама історія, що діставати іншу куртку.</p><p><strong>Під подію.</strong> Поїздка, весілля, день народження, зустріч випускників. Чохол із кадром саме цієї події, надрукований заздалегідь, потім лишається як маленький сувенір — і його не соромно передарувати учаснику тієї ж історії.</p><h3>Щоб набір не злився в одне</h3><p>Головна помилка — зробити всі чохли схожими: три фотографії з однієї поїздки, зняті в один день, різняться тільки деталями, і сенс змінності зникає. Беріть різні за характером зображення: одне фото, одна суцільна заливка з дрібним написом, один графічний сюжет без фотографії. Тоді щоразу, змінюючи чохол, ви справді змінюєте вигляд телефона, а не переставляєте той самий кадр на кілька міліметрів.</p><p>Де тримати другий — питання звички. Хтось лишає його в бардачку, хтось у внутрішній кишені сумки, хтось просто на полиці біля ключів. Заміна забирає секунд десять, і в неї є приємний побічний ефект: раз на кілька тижнів телефон опиняється без чохла, і його нарешті протирають — разом із пилом, що набився по краях.</p><p>Практична дрібниця. ZTE Nubia V70 Design — телефон не з легких, і чохол на ньому відчувається в руці. Якщо робите пару, зробіть їх за один раз: у людини, яка вже тримала два різні чохли на одному апараті, третій зазвичай з&#39;являється сам. Чохол на ЗТЕ Нубія В70 Дизайн з власним принтом коштує менше, ніж більшість речей, які ми міняємо за настроєм.</p>',
	 '<h2>Чехол не обязан быть один</h2><p>Привычка тут давняя: купили чехол — носим, пока не порвётся. Хотя силиконовый снимается за секунду, и ничто не мешает держать два или три и менять их, как меняют шарф или ремешок часов. С печатью это обретает смысл: каждый чехол получается не просто другого цвета, а с другим содержанием.</p><p>Владельцам ZTE Nubia V70 Design этот довод объяснять не нужно — модель выбирают те, кто смотрит на внешность телефона. Слово Design в названии стоит не случайно, и останавливаться на одном оформлении как-то нелогично.</p><h3>Три схемы на выбор</h3><p><strong>Будни и выходные.</strong> Один спокойный, почти однотонный — с ним на работу, к врачу, в госучреждение. Второй свободнее: фотография, яркий кадр, надпись. Переключение занимает столько же времени, сколько сменить обувь.</p><p><strong>По сезону.</strong> Осенью и зимой естественнее смотрятся глубокие тёмные тона, весной и летом — светлые и тёплые. Менять чехол дважды в год — примерно та же история, что доставать другую куртку.</p><p><strong>Под событие.</strong> Поездка, свадьба, день рождения, встреча выпускников. Чехол с кадром именно этого события, напечатанный заранее, потом остаётся как маленький сувенир — и его не стыдно передарить участнику той же истории.</p><h3>Чтобы набор не слился в одно</h3><p>Главная ошибка — сделать чехлы похожими: три снимка из одной поездки, снятые в один день, отличаются лишь деталями, и смысл сменности пропадает. Берите разные по характеру изображения: одно фото, одна сплошная заливка с мелкой надписью, один графический сюжет без фотографии вовсе. Тогда, меняя чехол, вы действительно меняете вид телефона, а не переставляете тот же кадр на пару миллиметров.</p><p>Где держать второй — дело привычки. Кто-то оставляет его в бардачке, кто-то во внутреннем кармане сумки, кто-то просто на полке у ключей. Смена занимает секунд десять, и есть у неё приятный побочный эффект: раз в несколько недель телефон оказывается без чехла, и его наконец протирают — вместе с пылью, набившейся по краям.</p><p>Практическая мелочь. ZTE Nubia V70 Design — телефон не из лёгких, и чехол на нём в руке ощущается. Если делаете пару, делайте её за один раз: у человека, который однажды подержал два разных чехла на одном аппарате, третий обычно появляется сам. Чехол на ЗТЕ Нубия В70 Дизайн со своим принтом обходится дешевле большинства вещей, которые мы меняем по настроению.</p>',
	 NULL, NULL, 1);

-- samsung-galaxy-a16 — кут: заміна старого чохла (пожовклий прозорий, розтягнутий силікон)
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-samsung-galaxy-a16', 'template',
	 'Чохол з фото на замовлення для Samsung Galaxy A16', 'Чехол с фото на заказ для Samsung Galaxy A16',
	 'Чохол з фото для Samsung Galaxy A16 на замовлення | FLOY', 'Чехол с фото для Samsung Galaxy A16 на заказ | FLOY',
	 'Час міняти чохол на Samsung Galaxy A16? Замість чергового прозорого, який знову пожовкне, надрукуйте на новому власне фото або напис.',
	 'Пора менять чехол на Samsung Galaxy A16? Вместо очередного прозрачного, который снова пожелтеет, напечатайте на новом своё фото или надпись.',
	 '<h2>Старий чохол доживає своє</h2><p>Момент, коли чохол пора міняти, впізнається без роздумів. Прозорий силікон пожовк і став схожий на пластик від старої техніки. Чорний розтягнувся, вилазить із кутів і починає зісковзувати. На кутах — потертості, всередині — пил, який уже не вимивається. У Samsung Galaxy A16 корпус чималий, тож розтягнутий чохол на ньому помітний одразу: телефон у руці ледь помітно ворушиться.</p><p>Найпростіше в цей момент купити такий самий. Найкращий — використати нагоду й нарешті поставити на телефон те, що ви самі оберете.</p><h3>Чому прозорий доводиться міняти найчастіше</h3><p>М&#39;який прозорий пластик темніє від тепла й ультрафіолету — це його природна властивість, а не брак конкретної партії. Кілька місяців у сонці й у кишені поруч із теплим телефоном, і колишня прозорість перетворюється на жовтуватий відтінок, який не відмивається. Далі власник купує новий прозорий, і цикл повторюється.</p><p>Друкований чохол цю петлю розриває просто тому, що на ньому є зображення. Колір фону, фотографія, темна заливка — усе це живе своїм життям, і легкі зміни матеріалу на ньому не читаються так, як на прозорому.</p><h3>З чим приходять на заміну</h3><p>Найчастіші сценарії однакові з року в рік: набридла нейтральність, хочеться нарешті «свій» телефон; попередній чохол з магазинним малюнком облізав; телефон дістався від когось, і його треба зробити своїм. Іноді причина зовсім проста — телефон часто плутають із таким самим у родині. Буває й навпаки: чохол міняють не тому, що він зносився, а тому, що змінилося життя, і старий принт більше не відповідає власнику.</p><p>Дивно, але заміну зазвичай відкладають місяцями. Розтягнутий чохол терплять, бо «поки тримається», і звикають до телефона, який трохи ковзає в долоні. Різницю відчуваєш одразу, щойно вдягнеш новий: свіжий силікон сидить щільно, апарат перестає ворушитися й уже не намагається вислизнути з руки, коли дістаєш його з кишені.</p><p>Порада зі спостережень: не викидайте старий чохол одразу. Лишіть його в шухляді як запасний на випадок, коли новий буде в дорозі або поїде з вами в поїздку. Другий такий момент настане швидше, ніж здається.</p><p>Що поставити на новий чохол для Гелексі А16, вирішувати вам: фотографія, напис, суцільний колір. У конструкторі зображення можна посунути й масштабувати, а текст поставити поверх або під ним. Головне, щоб після заміни телефон виглядав не так, як усі інші Samsung Galaxy A16 у вашому оточенні.</p>',
	 '<h2>Старый чехол доживает своё</h2><p>Момент, когда чехол пора менять, узнаётся без раздумий. Прозрачный силикон пожелтел и стал похож на пластик от старой техники. Чёрный растянулся, вылезает из углов и начинает соскальзывать. По углам потёртости, внутри пыль, которую уже не вымыть. Корпус у Samsung Galaxy A16 немаленький, так что растянутый чехол виден сразу: телефон в руке еле заметно ходит.</p><p>Проще всего в этот момент купить такой же. Правильнее — воспользоваться поводом и наконец поставить на телефон то, что выберете вы сами.</p><h3>Почему прозрачный меняют чаще прочих</h3><p>Мягкий прозрачный пластик темнеет от тепла и ультрафиолета — это его свойство, а не брак конкретной партии. Несколько месяцев на солнце и в кармане рядом с тёплым телефоном, и прежняя прозрачность превращается в желтоватый оттенок, который не отмывается. Дальше покупается новый прозрачный, и круг замыкается.</p><p>Печатный чехол эту петлю разрывает уже тем, что на нём есть изображение. Цвет фона, фотография, плотная заливка живут своей жизнью, и лёгкие изменения материала на них не читаются так, как на прозрачном.</p><h3>С чем приходят на замену</h3><p>Сценарии повторяются из года в год: надоела нейтральность и хочется наконец свой телефон; на прежнем чехле облез магазинный рисунок; аппарат достался от кого-то, и его нужно сделать своим. Иногда причина совсем бытовая — телефон путают с точно таким же в семье. Бывает и обратное: чехол меняют не потому, что износился, а потому, что изменилась жизнь и прежний принт владельцу больше не про него.</p><p>Странным образом замену обычно откладывают месяцами. Растянутый чехол терпят, потому что «пока держится», и привыкают к телефону, который слегка скользит в ладони. Разница чувствуется сразу, стоит надеть новый: свежий силикон сидит плотно, аппарат перестаёт болтаться и не норовит выскользнуть, когда достаёшь его из кармана.</p><p>Совет из наблюдений: не выбрасывайте старый чехол сразу. Оставьте его в ящике как запасной — на случай, когда новый в дороге, или чтобы взять в поездку. Второй такой момент наступает быстрее, чем кажется.</p><p>Что поставить на новый чехол для Галакси А16, решать вам: фотография, надпись, сплошной цвет. В конструкторе изображение двигается и масштабируется, а текст ложится поверх него или под ним. Главное, чтобы после замены телефон перестал выглядеть так же, как все остальные Samsung Galaxy A16 вокруг.</p>',
	 NULL, NULL, 1);

-- xiaomi-poco-c85 — кут: колір фону і контраст у макеті
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-xiaomi-poco-c85', 'template',
	 'Чохол з фото на замовлення для Xiaomi Poco C85', 'Чехол с фото на заказ для Xiaomi Poco C85',
	 'Чохол з фото для Xiaomi Poco C85 — друк на замовлення | FLOY', 'Чехол с фото для Xiaomi Poco C85 — печать на заказ | FLOY',
	 'Друкуємо принт на чохлі для Xiaomi Poco C85. Спинка тут велика, і колір фону вирішує більше за саме зображення — розбираємо, як його підібрати.',
	 'Печатаем принт на чехле для Xiaomi Poco C85. Спинка здесь большая, и цвет фона решает больше самого изображения — разбираем, как его подобрать.',
	 '<h2>Колір фону вирішує більше, ніж здається</h2><p>У конструкторі колір фону виглядає другорядним: спершу ставиш фото, підписуєш, а заливку чіпаєш в останню чергу. На готовому чохлі все навпаки. Xiaomi Poco C85 має екран близько 6,9 дюйма й відповідну спинку — площа велика, і саме фон займає більшу її частину. Перше, що бачить людина, — колірна пляма, а вже потім деталі знімка.</p><h3>Чотири правила, які рятують макет</h3><ul><li><strong>Темний фон прощає більше.</strong> На глибокому синьому, графіті чи темно-зеленому й фото, і текст виглядають зібрано, а дрібні недоліки композиції менш помітні.</li><li><strong>Чиста біла заливка виглядає порожньою.</strong> Якщо хочеться світлого, беріть теплий відтінок: піщаний, вершковий, блідо-сірий.</li><li><strong>Колір беріть із самого фото.</strong> Найспокійніший результат дає заливка в тон одного з кольорів знімка — неба, піску, светра на людині. Тоді фон і зображення читаються як одне ціле.</li><li><strong>Текст ставте на однорідну ділянку.</strong> Напис поверх строкатої частини фотографії губиться, той самий напис на рівному фоні поруч читається з відстані.</li></ul><h3>Коли фон і є весь дизайн</h3><p>Окремий варіант — обійтися взагалі без фотографії. Один насичений колір на всю спинку плюс невеликий напис збоку виглядає стримано й дорого, а на великому корпусі Поко С85 така суцільна пляма працює навіть виграшніше, ніж на компактному телефоні.</p><p>Ще один прийом для цієї моделі: два кольори, розділені по горизонталі приблизно на третині висоти. Зверху темніший, знизу світліший — або навпаки. Прийом простий, а телефон із ним виглядає навмисно оформленим, а не випадково залитим. У місце стику зручно ставити напис: там він не конкурує ні з чим і читається без зусиль, навіть коли літери невеликі.</p><p>Кілька пар, які майже завжди спрацьовують: темно-синій із піщаним, графіт із теракотою, темно-зелений із вершковим, чорний із приглушеним золотистим. У кожній парі один колір займає більшу площу, другий іде на напис або тонку смугу. Рівний поділ навпіл виглядає гірше — око не розуміє, який із двох кольорів головний.</p><p>Перевірка наприкінці. Відсуньтеся від екрана на витягнуту руку й подивіться на прев&#39;ю примруженим оком. Якщо на такій відстані макет розсипається на плями й нічого не читається — питання майже завжди до кольору, а не до самого фото. Змінити заливку в конструкторі для Xiaomi Poco C85 — це один рух, а різниця виходить помітною.</p>',
	 '<h2>Цвет фона решает больше, чем кажется</h2><p>В конструкторе цвет фона выглядит второстепенным: сначала ставишь фото, подписываешь, а заливку трогаешь в последнюю очередь. На готовом чехле всё наоборот. У Xiaomi Poco C85 экран около 6,9 дюйма и соответствующая спинка — площадь большая, и основную её часть занимает как раз фон. Первое, что видит человек, — цветовое пятно, и только потом детали снимка.</p><h3>Четыре правила, которые спасают макет</h3><ul><li><strong>Тёмный фон прощает больше.</strong> На глубоком синем, графите или тёмно-зелёном и фотография, и текст выглядят собранно, а мелкие огрехи композиции не так заметны.</li><li><strong>Чистая белая заливка смотрится пустой.</strong> Хочется светлого — берите тёплый оттенок: песочный, сливочный, бледно-серый.</li><li><strong>Цвет берите из самого снимка.</strong> Самый спокойный результат даёт заливка в тон одного из цветов фотографии — неба, песка, свитера на человеке. Тогда фон и изображение читаются как одно целое.</li><li><strong>Текст ставьте на однородный участок.</strong> Надпись поверх пёстрой части фотографии теряется, та же надпись на ровном фоне рядом читается с расстояния.</li></ul><h3>Когда фон и есть весь дизайн</h3><p>Отдельный вариант — обойтись без фотографии вообще. Один насыщенный цвет во всю спинку плюс небольшая надпись сбоку выглядит сдержанно и дорого, а на крупном корпусе Поко С85 такое сплошное пятно работает даже выигрышнее, чем на компактном телефоне.</p><p>Ещё приём для этой модели: два цвета, разделённые по горизонтали примерно на трети высоты. Сверху темнее, снизу светлее — или наоборот. Приём простой, а телефон с ним выглядит оформленным намеренно, а не залитым наугад. В место стыка удобно поставить надпись: там она ни с чем не конкурирует и читается без усилий, даже если буквы небольшие.</p><p>Несколько пар, которые срабатывают почти всегда: тёмно-синий с песочным, графит с терракотой, тёмно-зелёный со сливочным, чёрный с приглушённым золотистым. В каждой паре один цвет занимает большую площадь, второй уходит на надпись или тонкую полосу. Ровное деление пополам работает хуже — глаз не понимает, какой из двух цветов главный.</p><p>Проверка напоследок. Отодвиньтесь от экрана на вытянутую руку и посмотрите на превью прищурившись. Если на таком расстоянии макет рассыпается на пятна и ничего не читается — вопрос почти всегда к цвету, а не к самому фото. Сменить заливку в конструкторе для Xiaomi Poco C85 — одно движение, а разница получается заметной.</p>',
	 NULL, NULL, 1);

-- xiaomi-redmi-note-13-pro — кут: друкувати власні кадри, зняті цим же телефоном
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-xiaomi-redmi-note-13-pro', 'template',
	 'Чохол з фото на замовлення для Xiaomi Redmi Note 13 Pro', 'Чехол с фото на заказ для Xiaomi Redmi Note 13 Pro',
	 'Чохол з власним фото для Xiaomi Redmi Note 13 Pro | FLOY', 'Чехол со своим фото для Xiaomi Redmi Note 13 Pro | FLOY',
	 'Друк вашого кадру на чохлі для Xiaomi Redmi Note 13 Pro. Головна камера тут на 200 Мп — знімки з самого телефона підходять для друку якнайкраще.',
	 'Печать вашего кадра на чехле для Xiaomi Redmi Note 13 Pro. Главная камера здесь 200 Мп — снимки с самого телефона подходят для печати лучше всего.',
	 '<h2>Найкращий кадр уже у вас у галереї</h2><p>Xiaomi Redmi Note 13 Pro — один із небагатьох телефонів свого класу з головною камерою на 200 мегапікселів і стабілізацією. Люди беруть його саме заради зйомки: діти, поїздки, концерти, кіт на підвіконні. За рік у галереї збирається кілька тисяч кадрів, і майже всі вони так і лишаються в телефоні.</p><p>Друк на чохлі — один із небагатьох способів витягнути звідти хоча б один знімок у фізичний світ. Причому знятий тим самим апаратом, на якому ви його потім носите.</p><h3>Як вибрати з тисяч фото</h3><p>Прокручувати галерею з початку — найгірша стратегія: до середини ви втомитесь і поставите щось випадкове. Працює інше.</p><p>Згадайте кадр, до якого ви самі повертаєтесь, і знайдіть його пошуком за датою чи місцем. Такий знімок зазвичай один-два на рік, і саме він буде правильним. Далі подивіться на нього як на композицію, а не як на спогад: великий план з простим фоном на чохлі виглядає сильно, а загальний план, де все дрібне, розсипається.</p><p>Ще одна підказка. Кадри, зняті вертикально, лягають на чохол природніше — не треба нічого обрізати. Горизонтальні теж працюють, але з них зазвичай доводиться брати фрагмент.</p><h3>Дві речі, про які забувають</h3><p>Перша: у Redmi Note 13 Pro квадратний модуль камер великий і сидить у верхньому лівому куті. Обличчя й підписи туди краще не заводити — саме там принт частково губиться.</p><p>Друга: фото з екрана телефона й фото на чохлі сприймаються по-різному. На екрані знімок світиться, на силіконі — ні. Тому темні, знято-в-сутінках кадри на чохлі виглядають глухіше, ніж у галереї. Якщо любите вечірні фото, беріть із них те, де є хоч одне яскраве джерело світла: ліхтар, вікно, вогонь.</p><p>Є ще питання моменту. Найвдаліші замовлення зазвичай приходять одразу після поїздки чи події, поки враження свіже й ви точно пам&#39;ятаєте, який саме кадр вам дорогий. Через півроку та сама галерея виглядає рівним потоком, у якому важко когось виділити. Тож якщо ви тільки повернулися звідкись і в телефоні є той самий знімок, це найкращий час.</p><p>Решта — питання кількох хвилин у конструкторі. Чохол для Сяомі Редмі Ноут 13 Про з власним кадром відрізняється від магазинного принта тим, що історію за ним знаєте тільки ви — і саме тому його не набридає діставати з кишені.</p>',
	 '<h2>Лучший кадр уже лежит в вашей галерее</h2><p>Xiaomi Redmi Note 13 Pro — один из немногих телефонов своего класса с главной камерой на 200 мегапикселей и стабилизацией. Его и берут ради съёмки: дети, поездки, концерты, кот на подоконнике. За год в галерее набирается несколько тысяч кадров, и почти все они так и остаются в телефоне.</p><p>Печать на чехле — один из немногих способов вытащить оттуда хотя бы один снимок в физический мир. Причём снятый тем же аппаратом, на котором вы его потом носите.</p><h3>Как выбрать из тысяч снимков</h3><p>Листать галерею с начала — худшая стратегия: к середине вы устанете и поставите что-то случайное. Работает другое.</p><p>Вспомните кадр, к которому возвращаетесь сами, и найдите его поиском по дате или месту. Таких снимков обычно один-два за год, и именно он окажется верным. Дальше посмотрите на него как на композицию, а не как на воспоминание: крупный план на простом фоне на чехле смотрится сильно, а общий, где всё мелкое, рассыпается.</p><p>Ещё подсказка. Кадры, снятые вертикально, ложатся на чехол естественнее — обрезать ничего не нужно. Горизонтальные тоже работают, но из них обычно приходится брать фрагмент.</p><h3>Две вещи, о которых забывают</h3><p>Первая: у Redmi Note 13 Pro квадратный модуль камер крупный и стоит в верхнем левом углу. Лица и подписи туда заводить не стоит — именно там принт частично теряется.</p><p>Вторая: снимок на экране телефона и он же на чехле воспринимаются по-разному. На экране кадр светится, на силиконе — нет. Поэтому тёмные, снятые в сумерках фотографии на чехле выглядят глуше, чем в галерее. Любите вечерние кадры — берите тот, где есть хотя бы один яркий источник света: фонарь, окно, огонь.</p><p>Есть и вопрос момента. Самые удачные заказы обычно приходят сразу после поездки или события, пока впечатление свежее и вы точно помните, какой кадр вам дорог. Через полгода та же галерея выглядит ровным потоком, из которого трудно кого-то выделить. Так что если вы только вернулись откуда-то и нужный снимок в телефоне — это лучшее время.</p><p>Остальное — вопрос нескольких минут в конструкторе. Чехол для Сяоми Редми Ноут 13 Про с личным кадром отличается от магазинного принта тем, что историю за ним знаете только вы, — потому его и не надоедает доставать из кармана.</p>',
	 NULL, NULL, 1);

-- iphone-15 — кут: приватність принта, спинку телефона бачать сторонні
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-iphone-15', 'template',
	 'Чохол з фото на замовлення для iPhone 15', 'Чехол с фото на заказ для iPhone 15',
	 'Чохол з фото на замовлення для iPhone 15 — друк | FLOY', 'Чехол с фото на заказ для iPhone 15 — печать | FLOY',
	 'Власне фото на чохлі для iPhone 15. Спинку телефона бачать усі навколо — розбираємо, як зробити принт особистим і при цьому не надто відкритим.',
	 'Своё фото на чехле для iPhone 15. Спинку телефона видят все вокруг — разбираем, как сделать принт личным и при этом не слишком открытым.',
	 '<h2>Спинку телефона бачать усі, крім вас</h2><p>Екран ми ховаємо: пароль, приховані сповіщення, поворот дисплея від сусіда в маршрутці. А спинка весь день відкрита. iPhone 15 дістають частіше за багато інших телефонів — оплата на касі, квиток, код, фото, — і кожного разу принт бачать сторонні люди зблизька.</p><p>Це не привід відмовлятися від особистого зображення. Це привід вибрати його усвідомлено.</p><h3>Що краще не виносити на спинку</h3><p>Кілька речей, про які шкодують уже після отримання. Фото дитини разом з ім&#39;ям і роком народження великим шрифтом — забагато інформації для випадкового погляду. Домашня адреса чи номер, «щоб повернули, якщо загублю»: телефон повертають не так часто, а от прочитати це може будь-хто. Занадто відверті кадри, які нормально виглядають у телефоні, але не на предметі, що лежить екраном донизу поруч із чужими руками.</p><p>Окрема історія — фото партнера в повний кадр. Річ приємна, але чохол переживає не всі стосунки, а друк не переробляється.</p><h3>Особисте, яке не читається стороннім</h3><p>Найцікавіші макети для iPhone 15 зазвичай саме такі: сторонньому це просто гарна картинка, а ви бачите за нею конкретний день.</p><ul><li>фрагмент замість повного кадру: руки, тінь удвох, край моря на тому самому пляжі;</li><li>координати місця дрібним шрифтом замість назви;</li><li>дата без пояснення, що вона означає;</li><li>кадр зі спини або здалеку, де облич не розібрати;</li><li>абстракція, зроблена з вашої ж фотографії — наближений фрагмент фактури.</li></ul><p>Такий принт працює на двох рівнях одночасно. Для касира це просто море й тепле світло. Для вас — конкретна поїздка, після якої ви й купили той Айфон 15.</p><p>Варто визнати ще одну річ: принт на спинці читають як повідомлення про вас. Людина, яка бачить телефон на столі перемовин чи на стійці кав&#39;ярні, робить із нього швидкий висновок — так само, як із взуття чи сумки. Це не привід ховатися за нейтральним чорним, а привід один раз вирішити, що саме ваш чохол про вас каже. Спокійний кадр природи, чіткий графічний знак і фотографія компанії друзів говорять різні речі, і всі три варіанти нормальні — важливо лише, щоб обране було вашим свідомим вибором.</p><p>І практична дрібниця: якщо все ж хочеться відкритого сімейного фото, лишіть його для другого чохла, домашнього. Такі теж роблять — носять по черзі, залежно від того, куди йдуть.</p>',
	 '<h2>Спинку телефона видят все, кроме вас</h2><p>Экран мы прячем: пароль, скрытые уведомления, разворот дисплея от соседа в маршрутке. А спинка весь день открыта. iPhone 15 достают чаще многих других телефонов — оплата на кассе, билет, код, съёмка, — и каждый раз принт видят посторонние с близкого расстояния.</p><p>Это не повод отказываться от личного изображения. Это повод выбрать его осознанно.</p><h3>Что лучше не выносить на спинку</h3><p>Несколько вещей, о которых жалеют уже после получения. Фотография ребёнка вместе с именем и годом рождения крупным шрифтом — слишком много сведений для случайного взгляда. Домашний адрес или номер «чтобы вернули, если потеряю»: телефоны возвращают редко, а прочитать это может кто угодно. Слишком откровенные кадры, которые нормальны в галерее, но не на предмете, лежащем экраном вниз рядом с чужими руками.</p><p>Отдельная история — фото партнёра во весь кадр. Вещь приятная, но чехол переживает не все отношения, а печать не переделывается.</p><h3>Личное, которое посторонний не прочтёт</h3><p>Самые интересные макеты для iPhone 15 обычно как раз такие: для чужого глаза это просто красивая картинка, а вы видите за ней конкретный день.</p><ul><li>фрагмент вместо полного кадра: руки, тень вдвоём, край моря на том самом пляже;</li><li>координаты места мелким шрифтом вместо названия;</li><li>дата без пояснения, что она значит;</li><li>кадр со спины или издалека, где лиц не разобрать;</li><li>абстракция, сделанная из вашей же фотографии, — приближенный фрагмент фактуры.</li></ul><p>Такой принт работает сразу на двух уровнях. Для кассира это просто море и тёплый свет. Для вас — конкретная поездка, после которой вы и купили тот Айфон 15.</p><p>Стоит признать и другое: принт на спинке читают как сообщение о вас. Человек, увидевший телефон на переговорном столе или на стойке кофейни, делает быстрый вывод — ровно так же, как по обуви или сумке. Это не повод прятаться за нейтральным чёрным, а повод один раз решить, что именно ваш чехол о вас говорит. Спокойный кадр природы, чёткий графический знак и фотография компании друзей сообщают разное, и все три варианта нормальны — важно, чтобы выбор был осознанным.</p><p>И практическая мелочь: если открытого семейного фото всё-таки хочется, оставьте его для второго чехла, домашнего. Так тоже делают — носят по очереди, в зависимости от того, куда идут.</p>',
	 NULL, NULL, 1);

-- iphone-15-pro-max — кут: наступність, той самий сюжет переїжджає на наступний телефон
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-iphone-15-pro-max', 'template',
	 'Чохол з фото на замовлення для iPhone 15 Pro Max', 'Чехол с фото на заказ для iPhone 15 Pro Max',
	 'Чохол з фото для iPhone 15 Pro Max — друк на замовлення | FLOY', 'Чехол с фото для iPhone 15 Pro Max — печать на заказ | FLOY',
	 'Друк власного зображення на чохлі для iPhone 15 Pro Max. Телефон рано чи пізно зміниться, а сюжет можна перенести на чохол наступної моделі.',
	 'Печать своего изображения на чехле для iPhone 15 Pro Max. Телефон рано или поздно сменится, а сюжет можно перенести на чехол следующей модели.',
	 '<h2>Телефон зміниться, зображення лишиться</h2><p>З iPhone 15 Pro Max рідко розлучаються через поломку. Частіше буває інакше: апарат у порядку, але виходить нове покоління, і телефон іде далі — у продаж, комусь із родини, у шухляду як запасний. Разом із ним із життя зникає й чохол, бо вирізи під наступну модель уже не збігаються.</p><p>Це трохи змінює погляд на друк. Ви замовляєте не річ на роки, а конкретне оформлення на цей період — і в цьому є своя свобода.</p><h3>Зберігайте оригінал, а не чохол</h3><p>Практичне правило, яке варто завести одразу. Фотографію, з якої ви робили макет, покладіть в окремий альбом — назвіть його «для друку» й тримайте там повнорозмірні файли, а не пересланий у месенджері варіант. Коли телефон зміниться, ви за хвилину зберете той самий сюжет під новий корпус.</p><p>Просто скопіювати старий макет не вийде, і це нормально: у кожного покоління свій блок камер і свої пропорції спинки. Зображення доведеться посунути. А от сама фотографія лишається тією самою — і чохол сприймається як продовження попереднього, а не як щось геть нове.</p><h3>Що це дає на практиці</h3><p>У людей, які так роблять, з&#39;являється власна лінійка. Одна й та сама світлина, надрукована на трьох чохлах поспіль, перетворюється на особистий знак: телефон міняється, а річ у руці впізнається як ваша. Другий варіант — навпаки, щоразу новий кадр, і тоді чохли утворюють щось на кшталт хроніки: цей був після Карпат, той — після народження дитини.</p><p>Ще один момент, характерний саме для дорогих моделей. iPhone 15 Pro Max часто готують до перепродажу, і чохол тут працює на обидві задачі: закриває корпус від подряпин, а знімається безслідно — на самому телефоні жодних наліпок і плівок з малюнком.</p><p>Наповнювати той альбом краще протягом року, а не в останній вечір. Правило просте: побачили в галереї кадр, який не соромно було б повісити на стіну, — одразу відправляйте його туди. За рік набереться десяток, і вибирати доведеться не з семи тисяч знімків, а з десяти справді вартих.</p><p>Тож перед тим, як зібрати макет для Айфон 15 Про Макс, витратьте зайву хвилину й знайдіть оригінал знімка в найкращій якості. Наступний чохол — уже під іншу модель — ви зробите з того самого файлу.</p>',
	 '<h2>Телефон сменится, изображение останется</h2><p>С iPhone 15 Pro Max редко расстаются из-за поломки. Обычно иначе: аппарат в полном порядке, но выходит новое поколение, и телефон уходит дальше — на продажу, кому-то из родни, в ящик про запас. Вместе с ним из обихода исчезает и чехол: вырезы под следующую модель уже не совпадают.</p><p>Это слегка меняет взгляд на печать. Вы заказываете не вещь на годы, а конкретное оформление на этот период — и в этом есть своя свобода.</p><h3>Храните оригинал, а не чехол</h3><p>Правило, которое стоит завести сразу. Фотографию, из которой собран макет, положите в отдельный альбом — назовите его «для печати» и держите там полноразмерные файлы, а не вариант, пересланный в мессенджере. Когда телефон сменится, вы за минуту соберёте тот же сюжет под новый корпус.</p><p>Просто скопировать старый макет не получится, и это нормально: у каждого поколения свой блок камер и свои пропорции спинки. Изображение придётся подвинуть. Зато сама фотография остаётся прежней — и чехол читается как продолжение предыдущего, а не как нечто совсем новое.</p><h3>Что это даёт на практике</h3><p>У тех, кто так делает, появляется собственная линейка. Один и тот же снимок, напечатанный на трёх чехлах подряд, превращается в личный знак: телефон меняется, а вещь в руке узнаётся как ваша. Второй путь — наоборот, каждый раз новый кадр, и тогда чехлы складываются в хронику: этот был после Карпат, тот — после рождения ребёнка.</p><p>Есть момент, характерный именно для дорогих моделей. iPhone 15 Pro Max часто готовят к перепродаже, и чехол работает на обе задачи сразу: закрывает корпус от царапин и снимается бесследно — никаких наклеек и плёнок с рисунком на самом телефоне. Покупателю уходит аппарат в заводском виде, а личное оформление остаётся у вас — вместе с файлом, из которого оно собрано.</p><p>Наполнять такой альбом лучше в течение года, а не в последний вечер. Правило простое: увидели в галерее кадр, который не стыдно повесить на стену, — сразу отправляйте его туда. За год наберётся десяток, и выбирать придётся не из семи тысяч снимков, а из десяти по-настоящему стоящих.</p><p>Так что перед тем, как собирать макет для Айфон 15 Про Макс, потратьте лишнюю минуту и найдите оригинал снимка в лучшем качестве. Следующий чехол — уже под другую модель — вы сделаете из того же файла.</p>',
	 NULL, NULL, 1);

