-- iphone-17-pro — кут: серед десятка однакових айфонів свій має впізнаватися здалеку
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-iphone-17-pro', 'template',
	 'Чохол з фото на замовлення для iPhone 17 Pro', 'Чехол с фото на заказ для iPhone 17 Pro',
	 'Чохол з принтом для iPhone 17 Pro — друк на замовлення | FLOY', 'Чехол с принтом для iPhone 17 Pro — печать на заказ | FLOY',
	 'Свій принт на чохлі для iPhone 17 Pro. Навколо десятки таких самих апаратів — показуємо, як зробити свій телефон упізнаваним з двох метрів.',
	 'Свой принт на чехле для iPhone 17 Pro. Вокруг десятки таких же аппаратов — показываем, как сделать свой телефон узнаваемым с двух метров.',
	 '<h2>Коли поруч десяток таких самих</h2><p>З iPhone 17 Pro є побутова незручність, про яку не пишуть в оглядах: навколо повно точно таких апаратів. На нараді, у спортзалі, на столику в кав&#39;ярні поруч опиняється той самий телефон — у тому ж кольорі й у прозорому чохлі з вітрини. Далі класика жанру: два однакові прямокутники лежать екраном донизу, і власники по черзі беруть їх, щоб зрозуміти, чий який.</p><p>Надрукований принт закриває це питання остаточно. Не через захист і не через красу — телефон просто стає єдиним таким у кімнаті.</p><h3>Впізнаваність дає пляма, а не деталі</h3><p>З двох метрів око зчитує тільки колір і велику форму. Дрібниці воно розбирає з півметра — тобто вже тоді, коли телефон у вас у руці й шукати нічого не треба. Тому працює просте:</p><ul><li>один насичений колір фону — той, якого немає в заводській палітрі;</li><li>велика форма по центру: коло, силует, ініціал на пів чохла;</li><li>дві контрастні заливки з чіткою межею між ними;</li><li>своє фото, у якому переважає один відтінок.</li></ul><p>Дрібний повторюваний візерунок, навпаки, з відстані злипається в сірувату текстуру — і телефон знову виглядає як усі.</p><h3>Де це справді стає в пригоді</h3><p>Найчастіше вдома, де ввечері на одному подовжувачі заряджаються три айфони родини. Далі спільний стіл на роботі, де техніка колег лежить упереміш. Потім тренування: телефон чекає на лавці серед чужих речей. І врешті звичайне «та де ж він» — чорний прямокутник у кімнаті ви шукатимете хвилину, а помітну спинку побачите з порога.</p><p>Окремий випадок — родина, де в усіх однакові телефони. Дитина бере зі столу перший-ліпший, бо всі три виглядають однаково, а потім починаються розмови про чужі повідомлення. Різні спинки прибирають привід для таких сцен швидше за будь-які домовленості.</p><p>Тим, кому яскравість не підходить, є тихіший варіант. Темний фон, близький до заводського, і одна невелика деталь: ініціали, тонка лінія, дрібний знак у нижньому куті. Здалеку телефон виглядає стримано, зблизька його неможливо переплутати з сусіднім.</p><p>Макет для Айфон 17 Про збирається за кілька хвилин: власне фото або готовий сюжет, колір фону, напис. Перевірка теж проста — уявіть цей чохол поруч із чорним, білим і прозорим. Якщо ваш телефон у такій компанії помічають першим, ви все зробили правильно. Ще надійніше — попросити когось із дому глянути на прев&#39;ю з іншого кінця кімнати: чужий погляд помічає те, до чого ви за пів години в конструкторі вже звикли.</p>',
	 '<h2>Когда рядом десяток таких же</h2><p>У iPhone 17 Pro есть бытовое неудобство, о котором не пишут в обзорах: вокруг полно точно таких же аппаратов. На совещании, в спортзале, на столике в кофейне рядом оказывается тот же телефон — в том же цвете и в прозрачном чехле с витрины. Дальше классика: два одинаковых прямоугольника лежат экраном вниз, и владельцы по очереди берут их, чтобы разобраться, чей какой.</p><p>Напечатанный принт снимает вопрос совсем. Не ради защиты и не ради красоты — телефон просто становится единственным таким в комнате.</p><h3>Узнаваемость даёт пятно, а не детали</h3><p>С двух метров глаз считывает только цвет и крупную форму. Мелочи он разбирает с полуметра — то есть уже тогда, когда телефон у вас в руке и искать нечего. Поэтому работает простое:</p><ul><li>один насыщенный цвет фона — тот, которого нет в заводской палитре;</li><li>крупная форма по центру: круг, силуэт, инициал в пол-чехла;</li><li>две контрастные заливки с чёткой границей;</li><li>своё фото, где преобладает один оттенок.</li></ul><p>Мелкий повторяющийся узор, наоборот, с расстояния слипается в сероватую текстуру — и телефон снова выглядит как все.</p><h3>Где это выручает</h3><p>Чаще всего дома, где вечером на одном удлинителе заряжаются три айфона семьи. Дальше общий стол на работе, где техника коллег лежит вперемешку. Потом тренировка: телефон ждёт на скамейке среди чужих вещей. И наконец обычное «да где же он» — чёрный прямоугольник в комнате вы будете искать минуту, а заметную спинку увидите с порога.</p><p>Отдельный случай — семья, где у всех одинаковые телефоны. Ребёнок берёт со стола первый попавшийся, потому что все три на вид одинаковы, а дальше начинаются разговоры про чужие сообщения. Разные спинки убирают повод для таких сцен быстрее любых договорённостей.</p><p>Тем, кому яркость не подходит, есть тихий вариант. Тёмный фон, близкий к заводскому, и одна небольшая деталь: инициалы, тонкая линия, мелкий знак в нижнем углу. Издалека телефон выглядит сдержанно, вблизи его невозможно спутать с соседним.</p><p>Макет для Айфон 17 Про собирается за несколько минут: своё фото или готовый сюжет, цвет фона, надпись. Проверка тоже простая — представьте этот чехол рядом с чёрным, белым и прозрачным. Если ваш телефон в такой компании замечают первым, всё сделано верно. Ещё надёжнее — попросить кого-нибудь из домашних взглянуть на превью с другого конца комнаты: чужой глаз замечает то, к чему вы за полчаса в конструкторе успели привыкнуть.</p>',
	 NULL, NULL, 1);

-- hmd-pulse-pro — кут: перший досвід персоналізації у прагматичного власника
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-hmd-pulse-pro', 'template',
	 'Чохол з фото на замовлення для HMD Pulse Pro', 'Чехол с фото на заказ для HMD Pulse Pro',
	 'Чохол з фото для HMD Pulse Pro — друк на замовлення | FLOY', 'Чехол с фото для HMD Pulse Pro — печать на заказ | FLOY',
	 'Друк власного зображення на чохлі для HMD Pulse Pro. З чого почати, якщо ви ніколи нічого не персоналізували, і чому «просто прозорий» тут програє.',
	 'Печать своего изображения на чехле для HMD Pulse Pro. С чего начать, если вы никогда ничего не персонализировали, и почему «просто прозрачный» проигрывает.',
	 '<h2>Практичний телефон і одна непрактична деталь</h2><p>HMD Pulse Pro беруть не під враженням від реклами. Це вибір людини, яка порівняла кілька моделей, вирішила не переплачувати за напис на корпусі й узяла апарат під конкретні задачі: дзвінки, месенджери, маршрути, камера для побутових кадрів. Усе зважено, без зайвого.</p><p>Тим цікавіше, що чохол із власним принтом такому підходу не суперечить. Це єдине місце у дуже практичній речі, де можна дозволити собі щось необов&#39;язкове.</p><h3>«Найдешевший, аби закривав» — логіка, яка підводить</h3><p>Коли телефон обирали головою, чохол зазвичай беруть за тим самим принципом: перший-ліпший прозорий із каси. Ніби послідовно, а результат виходить дивний. Телефон — предмет, до якого ви торкаєтесь частіше, ніж до ключів, гаманця чи улюбленої чашки: він у руці по кілька годин на день, роками. І весь цей час у долоні нічий безбарвний пластик.</p><p>HMD від початку будувала свою лінійку навколо думки, що телефон має служити довго, а не змінюватись раз на два сезони. Якщо апарат лишається з вами кілька років, оформлення варте однієї усвідомленої дії.</p><h3>Якщо ви робите таке вперше</h3><p>Більшість власників ЕйчЕмДі Пульс Про ніколи раніше нічого не персоналізували — і помилка тут майже завжди одна: людина шукає ідеальний знімок, не знаходить і закриває вкладку.</p><p>Простіше почати з малого. Візьміть однотонний фон і поставте одну літеру або своє ім&#39;я — це вже ваш телефон, і піде на це хвилина. Другий шлях — сфотографувати щось просто зараз: рослину на підвіконні, фактуру столу, кота, який спить. Кадр не мусить бути шедевром, йому достатньо бути вашим.</p><p>Третій спосіб — узяти готовий сюжет із тем і додати до нього дату або коротке слово. Так роблять ті, хто не довіряє власному смаку в композиції, і виходить, як правило, добре.</p><p>Заважає почати й думка, ніби вибір треба зробити ідеально з першого разу. Випадок не той. Чохол — не гравіювання на годиннику: у того, хто зробив перший, другий зазвичай виходить точнішим, бо своє зображення він уже бачив не на екрані, а на речі в руці. Найгірший результат тут не невдалий макет, а порожня спинка, до якої ви щодня збираєтесь дійти руками.</p><p>І порада, яка економить нерви: не намагайтеся вкласти в один чохол усе про себе. Одна думка на макет. HMD Pulse Pro прослужить довго, а от чохол за цей час цілком може виявитись не єдиним.</p>',
	 '<h2>Практичный телефон и одна непрактичная деталь</h2><p>HMD Pulse Pro берут не под впечатлением от рекламы. Так поступает человек, который сравнил несколько моделей, решил не переплачивать за надпись на корпусе и взял аппарат под конкретные задачи: звонки, мессенджеры, маршруты, камера для бытовых кадров. Всё взвешено, ничего лишнего.</p><p>Тем интереснее, что чехол со своим принтом этому подходу не противоречит. Это единственное место в очень практичной вещи, где можно позволить себе необязательное.</p><h3>«Подешевле, лишь бы закрывал» — логика, которая подводит</h3><p>Когда телефон выбирали головой, чехол обычно берут по тому же принципу: первый попавшийся прозрачный у кассы. Вроде последовательно, а результат странный. Телефон — предмет, к которому вы прикасаетесь чаще, чем к ключам, кошельку или любимой чашке: он в руке по нескольку часов в день, годами. И всё это время в ладони ничей бесцветный пластик.</p><p>HMD с самого начала строила линейку вокруг мысли, что телефон должен служить долго, а не меняться раз в два сезона. Если аппарат остаётся с вами несколько лет, оформление стоит одного осознанного решения.</p><h3>Если вы делаете такое впервые</h3><p>Большинство владельцев ЭйчЭмДи Пульс Про никогда ничего не персонализировали, и ошибка тут почти всегда одна: человек ищет идеальный снимок, не находит и закрывает вкладку.</p><p>Проще начать с малого. Возьмите однотонный фон и поставьте одну букву или своё имя — это уже ваш телефон, и уйдёт на это минута. Второй путь — снять что-нибудь прямо сейчас: растение на подоконнике, фактуру стола, спящего кота. Кадру не обязательно быть шедевром, ему достаточно быть вашим.</p><p>Третий способ — взять готовый сюжет из тем и добавить к нему дату или короткое слово. Так делают те, кто не доверяет своему вкусу в композиции, и получается, как правило, хорошо.</p><p>Мешает начать и мысль, будто выбор нужно сделать идеально с первого раза. Случай не тот. Чехол — не гравировка на часах: у того, кто сделал первый, второй обычно выходит точнее, потому что своё изображение он уже видел не на экране, а на вещи в руке. Худший исход здесь не неудачный макет, а пустая спинка, до которой вы каждый день собираетесь добраться.</p><p>И совет, экономящий нервы: не пытайтесь уместить в один чехол всё о себе. Одна мысль на макет. HMD Pulse Pro прослужит долго, а вот чехол за это время вполне может оказаться не единственным.</p>',
	 NULL, NULL, 1);

-- infinix-gt-20-pro — кут: текстовий макет, довжина напису, шрифт і розташування
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-infinix-gt-20-pro', 'template',
	 'Чохол з фото на замовлення для Infinix GT 20 Pro', 'Чехол с фото на заказ для Infinix GT 20 Pro',
	 'Чохол з принтом для Infinix GT 20 Pro — друк | FLOY', 'Чехол с принтом для Infinix GT 20 Pro — печать | FLOY',
	 'Свій напис на чохлі для Infinix GT 20 Pro. Розбираємо довжину тексту, вибір шрифта й розташування, щоб нік або фраза читалися з відстані.',
	 'Своя надпись на чехле для Infinix GT 20 Pro. Разбираем длину текста, выбор шрифта и расположение, чтобы ник или фраза читались с расстояния.',
	 '<h2>Коли принт — це текст, а не картинка</h2><p>Не в кожного є фотографія, яку хочеться носити на спинці роками. Зате майже в кожного є слово: нік, прізвисько, назва команди, рядок із пісні, одне ім&#39;я, дата. Infinix GT 20 Pro обирають ті, кому небайдужий вигляд телефона, і текстовий макет на ньому працює краще за випадковий знімок із галереї.</p><h3>Чим коротше, тим сильніше</h3><p>Головне обмеження — довжина. Одне слово великими літерами на всю ширину читається миттєво й виглядає як знак. Фраза на два рядки вже вимагає зменшити кегль, і замість знака виходить дрібний підпис, який ніхто не читає.</p><ul><li>до восьми символів — можна на пів чохла;</li><li>до двадцяти — рівно один рядок нормального розміру;</li><li>довше — тільки як дрібний підпис під основним елементом.</li></ul><p>Тому цитати з двох речень майже завжди програють одному слову. Якщо фраза дорога вам цілком, розбийте її: головне слово великим, решта — маленьким рядком нижче.</p><h3>Шрифт говорить голосніше за саме слово</h3><p>Один і той самий нік у різних накресленнях звучить по-різному. Широкий рубаний без засічок — техніка, спорт, упевненість. Тонкий світлий — стриманість. Рукописний — щось особисте, ім&#39;я близької людини. Для Інфінікс ДжіТі 20 Про частіше просять перший варіант, і це логічно: апарат і сам виглядає технічно.</p><p>Розташування змінює настрій не менше. Напис по центру — спокійно й офіційно. Ближче до низу — легше, бо верх лишається під блок камер. По діагоналі — динамічно, але тоді в макеті більше нічого бути не повинно.</p><p>Окремо про колір напису. Текст читається тим краще, чим більша різниця в яскравості між ним і фоном, — і йдеться саме про яскравість, а не про колір. Червоне на синьому здається контрастним на екрані, але обидва кольори темні, і на чохлі літери злипаються з тлом. Світле на темному або темне на світлому працює завжди, у будь-якій парі відтінків.</p><p>Чого краще не робити: складати обводку, тінь і градієнт в одному написі; ставити рукописний шрифт великими літерами; заводити текст під самий край. Останнє помітно вже на готовому чохлі, коли літера впирається в бортик.</p><p>І про мову. Латиниця виглядає нейтральніше й краще тримає форму у великому кеглі, кирилиця — тепліше й особистіше. Нік із гри беріть у тому написанні, у якому вас знають. Ім&#39;я близької людини — у тому, яким її звуть удома.</p>',
	 '<h2>Когда принт — это текст, а не картинка</h2><p>Не у каждого есть фотография, которую хочется носить на спинке годами. Зато почти у каждого есть слово: ник, прозвище, название команды, строчка из песни, одно имя, дата. Infinix GT 20 Pro выбирают те, кому не безразличен вид телефона, и текстовый макет здесь работает лучше случайного снимка из галереи.</p><h3>Чем короче, тем сильнее</h3><p>Главное ограничение — длина. Одно слово крупными буквами во всю ширину читается мгновенно и выглядит как знак. Фраза в две строки уже требует уменьшить кегль, и вместо знака получается мелкая подпись, которую никто не читает.</p><ul><li>до восьми символов — можно в пол-чехла;</li><li>до двадцати — ровно одна строка нормального размера;</li><li>длиннее — только мелкой подписью под основным элементом.</li></ul><p>Поэтому цитаты в два предложения почти всегда проигрывают одному слову. Если фраза дорога целиком, разбейте её: ключевое слово крупно, остальное — маленькой строкой ниже.</p><h3>Шрифт говорит громче самого слова</h3><p>Один и тот же ник в разных начертаниях звучит по-разному. Широкий рубленый — техника, спорт, уверенность. Тонкий светлый — сдержанность. Рукописный — что-то личное, имя близкого человека. Для Инфиникс ДжиТи 20 Про чаще просят первое, и это логично: аппарат и сам выглядит технично.</p><p>Расположение меняет настроение не меньше. Надпись по центру — спокойно и официально. Ближе к низу — легче, потому что верх остаётся под блок камер. По диагонали — динамично, но тогда в макете больше ничего быть не должно.</p><p>Отдельно про цвет надписи. Текст читается тем лучше, чем больше разница в яркости между ним и фоном, — речь именно о яркости, а не о цвете. Красное на синем кажется контрастным на экране, но оба цвета тёмные, и на чехле буквы слипаются с фоном. Светлое на тёмном или тёмное на светлом работает всегда, в любой паре оттенков.</p><p>Чего лучше не делать: собирать обводку, тень и градиент в одной надписи; ставить рукописный шрифт заглавными; заводить текст под самый край. Последнее заметно уже на готовом чехле, когда буква упирается в бортик.</p><p>И про язык. Латиница выглядит нейтральнее и лучше держит форму в крупном кегле, кириллица — теплее и личнее. Ник из игры берите в том написании, в котором вас знают. Имя близкого человека — в том, которым его зовут дома.</p>',
	 NULL, NULL, 1);

-- realme-c85 — кут: що робити, коли гідного фото в галереї немає
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-realme-c85', 'template',
	 'Чохол з фото на замовлення для Realme C85', 'Чехол с фото на заказ для Realme C85',
	 'Чохол з фото для Realme C85 — друк на замовлення | FLOY', 'Чехол с фото для Realme C85 — печать на заказ | FLOY',
	 'Чохол зі своїм оформленням для Realme C85, навіть якщо годящого фото немає. Готовий сюжет плюс ваша деталь і три способи зняти кадр спеціально.',
	 'Чехол со своим оформлением для Realme C85, даже если подходящего фото нет. Готовый сюжет плюс ваша деталь и три способа снять кадр специально.',
	 '<h2>Коли в галереї немає нічого підхожого</h2><p>Ситуація частіша, ніж здається: чохол зі своїм оформленням хочеться, а знімка, який не соромно носити рік, немає. У галереї скріншоти, фото документів, три тисячі однакових кадрів з однієї вечері й нічого такого, що варто збільшити на всю спинку. Лишати через це Realme C85 у прозорому чохлі не обов&#39;язково — просто шлях інший.</p><h3>Готовий сюжет плюс одна ваша деталь</h3><p>Схема проста: береться готовий дизайн із тем, а до нього додається одне, чого немає більше ні в кого. Ім&#39;я. Ініціали. Дата. Коротке слово, зрозуміле двом людям. Виходить не «картинка з інтернету», а ваша річ — і на це потрібно менше хвилини.</p><p>Працює це навіть із найнейтральнішими сюжетами. Абстрактний градієнт з ініціалом у кутку виглядає зробленим на замовлення, хоча змінили ви в ньому рівно один елемент.</p><h3>Три способи зняти фото спеціально для чохла</h3><p>Другий шлях — не шукати кадр у минулому, а зробити його зараз. П&#39;ять хвилин, і результат зазвичай кращий, ніж після години розкопок в архіві.</p><ul><li><strong>Предмет на однотонному тлі.</strong> Улюблена чашка, книжка, кросівки, гітара, ключі від першої машини. Кладете на стіл біля вікна, знімаєте зверху — і маєте чистий кадр із характером.</li><li><strong>Фактура зблизька.</strong> Кора дерева, вода, тканина, зім&#39;ятий папір, стіна старого будинку. На чохлі така поверхня читається як дорогий матеріал, а не як фотографія.</li><li><strong>Небо або вода.</strong> Знімок неба на світанку чи ввечері — готова заливка з переходом кольору, живіша за будь-який намальований градієнт.</li></ul><p>Знімаючи спеціально, тримайте телефон вертикально й лишайте навколо предмета трохи вільного місця. Виглядає нелогічно — хочеться підійти ближче, — але саме запас по краях дає свободу потім: у конструкторі кадр можна збільшити й посунути, а домалювати те, що не влізло, нічим. Зайвий сантиметр повітря на знімку рятує макет частіше, ніж вдалий ракурс.</p><p>Є варіант і для тих, хто зображень не хоче взагалі. Один щільний колір на всю спинку і більше нічого — рішення, яке не набридає й не виходить із моди. Телефон при цьому виглядає так, ніби Реалмі С85 випустили в кольорі, якого в продажу не було.</p><p>Головне — не чекати ідеї, яка прийде сама. Найгірші макети виходять не в тих, хто мало вміє, а в тих, хто півгодини гортав галерею й нарешті поставив хоч щось.</p>',
	 '<h2>Когда в галерее нет ничего подходящего</h2><p>Ситуация чаще, чем кажется: чехол со своим оформлением хочется, а снимка, который не стыдно носить год, нет. В галерее скриншоты, фото документов, три тысячи одинаковых кадров с одного ужина и ничего такого, что стоит увеличить во всю спинку. Оставлять из-за этого Realme C85 в прозрачном чехле не обязательно — просто путь другой.</p><h3>Готовый сюжет плюс одна ваша деталь</h3><p>Схема простая: берётся готовый дизайн из тем, а к нему добавляется одно, чего больше ни у кого нет. Имя. Инициалы. Дата. Короткое слово, понятное двоим. Получается не «картинка из интернета», а ваша вещь — и уходит на это меньше минуты.</p><p>Работает даже с самыми нейтральными сюжетами. Абстрактный градиент с инициалом в углу выглядит сделанным на заказ, хотя изменили вы в нём ровно один элемент.</p><h3>Три способа снять фото специально для чехла</h3><p>Второй путь — не искать кадр в прошлом, а сделать его сейчас. Пять минут, и результат обычно лучше, чем после часа раскопок в архиве.</p><ul><li><strong>Предмет на однотонном фоне.</strong> Любимая чашка, книга, кроссовки, гитара, ключи от первой машины. Кладёте на стол у окна, снимаете сверху — и получаете чистый кадр с характером.</li><li><strong>Фактура вблизи.</strong> Кора дерева, вода, ткань, смятая бумага, стена старого дома. На чехле такая поверхность читается как дорогой материал, а не как фотография.</li><li><strong>Небо или вода.</strong> Снимок неба на рассвете или вечером — готовая заливка с переходом цвета, живее любого нарисованного градиента.</li></ul><p>Снимая специально, держите телефон вертикально и оставляйте вокруг предмета немного свободного места. Выглядит нелогично — тянет подойти ближе, — но именно запас по краям даёт свободу дальше: в конструкторе кадр можно увеличить и сдвинуть, а дорисовать то, что не поместилось, нечем. Лишний сантиметр воздуха на снимке спасает макет чаще, чем удачный ракурс.</p><p>Есть вариант и для тех, кто изображений не хочет вовсе. Один плотный цвет во всю спинку и больше ничего — решение, которое не надоедает и не выходит из моды. Телефон при этом выглядит так, будто Реалми С85 выпустили в цвете, которого в продаже не было.</p><p>Главное — не ждать идеи, которая придёт сама. Худшие макеты получаются не у тех, кто мало умеет, а у тех, кто полчаса листал галерею и в итоге поставил хоть что-нибудь.</p>',
	 NULL, NULL, 1);

-- xiaomi-poco-x8-pro-max — кут: колаж із кількох кадрів на великій спинці
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-xiaomi-poco-x8-pro-max', 'template',
	 'Чохол з фото на замовлення для Xiaomi Poco X8 Pro Max', 'Чехол с фото на заказ для Xiaomi Poco X8 Pro Max',
	 'Чохол з фото для Xiaomi Poco X8 Pro Max — друк | FLOY', 'Чехол с фото для Xiaomi Poco X8 Pro Max — печать | FLOY',
	 'Друк кількох фото на чохлі для Xiaomi Poco X8 Pro Max. Спинка тут велика — розбираємо сітки колажу й помилки, через які кадри зливаються в кашу.',
	 'Печать нескольких фото на чехле для Xiaomi Poco X8 Pro Max. Спинка здесь большая — разбираем сетки коллажа и ошибки, из-за которых кадры сливаются.',
	 '<h2>Кілька кадрів на одній спинці</h2><p>Одне фото на чохлі — рішення за замовчуванням, і найчастіше правильне. Але буває, що вибрати неможливо: троє дітей, дві поїздки за рік, чотири місця, до яких повертаєшся. Тоді роблять колаж, і Xiaomi Poco X8 Pro Max для цього підходить краще за середній телефон — моделі з приставкою Max найбільші в лінійці, і два-три кадри на такій спинці не перетворюються на поштові марки.</p><h3>Скільки кадрів витримує чохол</h3><p>Два — завжди добре. Три — межа, після якої починаються компроміси. Чотири й більше працюють лише в одному випадку: коли всі знімки однотипні за кольором і планом, і сітка читається як візерунок, а не як набір різних картинок.</p><p>Рахуйте не кадри, а обличчя. Три портрети великим планом — нормально. Три групові фото, де в кожному по п&#39;ятеро людей, — це п&#39;ятнадцять облич завбільшки з ніготь, і жодного з них ви на чохлі не впізнаєте.</p><h3>Сітки, які виглядають зібрано</h3><ul><li><strong>Дві горизонтальні смуги.</strong> Верхня й нижня половина, межа рівно посередині. Найпростіше й майже безпрограшно.</li><li><strong>Один великий і два маленькі.</strong> Головний кадр займає дві третини висоти, два допоміжні стоять під ним поруч. Одразу видно, що тут основне.</li><li><strong>Смуга збоку.</strong> Велике фото на всю спинку, а вздовж краю — вузька колонка з двох-трьох маленьких. Схоже на плівку й добре тримає вертикаль.</li></ul><h3>Що псує колаж найчастіше</h3><p>Різна тональність. Один кадр літній і жовтий, другий зимовий і синій, третій знятий у кімнаті при лампі — разом вони не склеюються. Якщо знімки з різних сезонів, зробіть їх усі чорно-білими: колаж одразу стає цілим.</p><p>Друге — нерівні проміжки. Відстані між кадрами мають бути однакові, інакше око чіпляється саме за них, а не за фотографії.</p><p>Окреме питання — підписи. Дати чи назви міст під кожним кадром здаються гарною ідеєю, поки не побачиш їх надрукованими: чотири дрібні рядки перетворюють чохол на сторінку зі щоденника. Якщо підпис потрібен, лишіть один, спільний для всього набору, — рік, назву поїздки, одне ім&#39;я. Тоді колаж читається як ціла річ, а не як добірка окремих фотографій.</p><p>І третє: верхній лівий кут спинки Сяомі Поко Х8 Про Макс зайнятий блоком камер. Кадр, який ви вважаєте головним, туди ставити не варто — віддайте цей кут фоновому або найменш важливому знімку.</p>',
	 '<h2>Несколько кадров на одной спинке</h2><p>Одно фото на чехле — решение по умолчанию, и чаще всего верное. Но бывает, что выбрать невозможно: трое детей, две поездки за год, четыре места, куда возвращаешься. Тогда делают коллаж, и Xiaomi Poco X8 Pro Max подходит для этого лучше среднего телефона — модели с приставкой Max самые крупные в линейке, и два-три кадра на такой спинке не превращаются в почтовые марки.</p><h3>Сколько кадров выдерживает чехол</h3><p>Два — всегда хорошо. Три — предел, за которым начинаются компромиссы. Четыре и больше работают в одном случае: когда все снимки однотипны по цвету и плану, и сетка читается как узор, а не как набор разных картинок.</p><p>Считайте не кадры, а лица. Три портрета крупным планом — нормально. Три групповых снимка, где в каждом по пятеро, — это пятнадцать лиц размером с ноготь, и ни одно из них на чехле не узнать.</p><h3>Сетки, которые выглядят собранно</h3><ul><li><strong>Две горизонтальные полосы.</strong> Верхняя и нижняя половина, граница ровно посередине. Проще всего и почти беспроигрышно.</li><li><strong>Один крупный и два мелких.</strong> Главный кадр занимает две трети высоты, два вспомогательных стоят под ним рядом. Сразу видно, что здесь основное.</li><li><strong>Полоса сбоку.</strong> Большое фото во всю спинку, а вдоль края — узкая колонка из двух-трёх маленьких. Похоже на плёнку и хорошо держит вертикаль.</li></ul><h3>Что портит коллаж чаще всего</h3><p>Разная тональность. Один кадр летний и жёлтый, второй зимний и синий, третий снят в комнате при лампе — вместе они не склеиваются. Если снимки из разных сезонов, переведите все в чёрно-белое: коллаж сразу становится целым.</p><p>Второе — неровные промежутки. Расстояния между кадрами должны быть одинаковыми, иначе глаз цепляется именно за них, а не за фотографии.</p><p>Отдельный вопрос — подписи. Даты или названия городов под каждым кадром кажутся хорошей идеей, пока не увидишь их напечатанными: четыре мелкие строки превращают чехол в страницу дневника. Если подпись нужна, оставьте одну, общую для всего набора, — год, название поездки, одно имя. Тогда коллаж читается как цельная вещь, а не как подборка отдельных фотографий.</p><p>И третье: верхний левый угол спинки Сяоми Поко Х8 Про Макс занят блоком камер. Кадр, который вы считаете главным, туда лучше не ставить — отдайте этот угол фоновому или наименее важному снимку.</p>',
	 NULL, NULL, 1);

-- iphone-xi — кут: телефон, який дістався від когось; зробити вживаний апарат своїм
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-iphone-xi', 'template',
	 'Чохол з фото на замовлення для iPhone 11', 'Чехол с фото на заказ для iPhone 11',
	 'Чохол з фото для iPhone 11 — друк на замовлення | FLOY', 'Чехол с фото для iPhone 11 — печать на заказ | FLOY',
	 'Власне фото на чохлі для iPhone 11. Телефон часто дістається від когось із родини — свій принт швидко робить вживаний апарат по-справжньому вашим.',
	 'Своё фото на чехле для iPhone 11. Телефон часто достаётся от кого-то из родных — свой принт быстро делает подержанный аппарат по-настоящему вашим.',
	 '<h2>Телефон із чужою історією</h2><p>iPhone 11 вийшов у 2019 році, і сьогодні він рідко буває в перших руках. Апарат живучий, тому й мандрує далі: старший купив новий — віддав молодшому, чоловік поміняв — телефон дістався дружині, хтось узяв з рук за половину ціни. Разом із телефоном зазвичай переїжджає і чохол попереднього власника.</p><p>Саме він і створює відчуття, що річ не зовсім ваша. Усе працює, все влаштовує, але в руці — чужий вибір.</p><h3>Що змінюється після заміни</h3><p>Це найдешевша зміна і найвідчутніша. Телефон із власним принтом перестає бути «татовим старим» чи «купленим по оголошенню» — він стає просто вашим. Особливо це помітно, коли апарат передали дитині або підлітку: свій чохол перетворює вживану річ на подарунок.</p><p>Спрацьовує це швидко: телефон починає подобатись більше, хоча в самому апараті не змінилось нічого.</p><p>Є й практичний бік. За шість років спинка Айфон 11 у більшості вже не заводська: подряпини, сліди піску з кишені, іноді тріщинка в кутку. Силіконовий чохол із друком закриває це повністю, і телефон знову виглядає цілим.</p><h3>Що ставлять на такі телефони</h3><p>Тут є закономірність. Якщо телефон дістався від когось із родини, найчастіше друкують щось спільне з цією людиною — стару фотографію, місце, куди їздили разом. Виходить не приховування історії апарата, а її продовження.</p><p>Якщо телефон куплений з рук у незнайомця, працює протилежне: беруть максимально своє й нове, щоб ніщо не нагадувало про попереднє життя цієї речі.</p><p>З композицією тут просто. У iPhone 11 квадратний блок із двома об&#39;єктивами у верхньому лівому куті, решта спинки — рівне поле. Обличчя й написи ставте нижче цього кута, і макет складеться сам.</p><p>Є й дзеркальна ситуація — коли телефон віддаєте ви. Апарат, переданий разом із надрукованим чохлом, сприймається зовсім інакше, ніж просто вручений із зарядкою: це вже не «бери, мені все одно не потрібен», а нормальний подарунок. Особливо коли на спинці спільне фото або те, що любить новий власник. Кілька хвилин роботи, а різниця у відчутті велика.</p><p>І сценарій, про який рідко думають. Якщо телефон у вас тимчасово, до наступної покупки, це якраз привід зробити чохол не «на роки», а під настрій. Річ недорога, а апарат, що дістався випадково, після цього перестає сприйматися як тимчасовий.</p>',
	 '<h2>Телефон с чужой историей</h2><p>iPhone 11 вышел в 2019 году, и сегодня он редко бывает в первых руках. Аппарат живучий, поэтому и путешествует дальше: старший купил новый — отдал младшему, муж поменял — телефон достался жене, кто-то взял с рук за половину цены. Вместе с телефоном обычно переезжает и чехол прежнего владельца.</p><p>Он-то и создаёт ощущение, что вещь не совсем ваша. Всё работает, всё устраивает, но в руке — чужой выбор.</p><h3>Что меняется после замены</h3><p>Это самое дешёвое изменение и самое ощутимое. Телефон со своим принтом перестаёт быть «папиным старым» или «купленным по объявлению» — он становится просто вашим. Особенно заметно, когда аппарат передали ребёнку или подростку: свой чехол превращает подержанную вещь в подарок.</p><p>Срабатывает это быстро: телефон начинает нравиться больше, хотя в самом аппарате не изменилось ничего. Вещь та же, а отношение к ней другое.</p><p>Есть и практическая сторона. За шесть лет спинка Айфон 11 у большинства уже не заводская: царапины, следы песка из кармана, иногда трещинка в углу. Силиконовый чехол с печатью закрывает это целиком, и телефон снова выглядит целым.</p><h3>Что ставят на такие телефоны</h3><p>Тут есть закономерность. Если телефон достался от кого-то из родных, чаще печатают что-то общее с этим человеком — старую фотографию, место, куда ездили вместе. Получается не сокрытие истории аппарата, а её продолжение.</p><p>Если телефон куплен с рук у незнакомца, работает обратное: берут максимально своё и новое, чтобы ничто не напоминало о прежней жизни вещи.</p><p>С композицией здесь просто. У iPhone 11 квадратный блок с двумя объективами в верхнем левом углу, остальная спинка — ровное поле. Лица и надписи ставьте ниже этого угла, и макет сложится сам.</p><p>Бывает и зеркальная ситуация — когда телефон отдаёте вы. Аппарат, переданный вместе с напечатанным чехлом, воспринимается совсем иначе, чем просто вручённый с зарядкой: это уже не «бери, мне всё равно не нужен», а нормальный подарок. Особенно если на спинке общее фото или то, что любит новый владелец. Несколько минут работы, а разница в ощущении большая.</p><p>И сценарий, о котором редко думают. Если телефон у вас временно, до следующей покупки, это как раз повод сделать чехол не «на годы», а под настроение. Вещь недорогая, а аппарат, доставшийся случайно, после этого перестаёт восприниматься как временный.</p>',
	 NULL, NULL, 1);

-- blackview-oscal-c80 — кут: недорогий телефон і те, що насправді видає бюджетність
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-blackview-oscal-c80', 'template',
	 'Чохол з фото на замовлення для Blackview Oscal C80', 'Чехол с фото на заказ для Blackview Oscal C80',
	 'Чохол з принтом для Blackview Oscal C80 — друк | FLOY', 'Чехол с принтом для Blackview Oscal C80 — печать | FLOY',
	 'Друк власного принта на чохлі для Blackview Oscal C80. Що насправді видає недорогий телефон і які прийоми в макеті працюють на його вигляд.',
	 'Печать своего принта на чехле для Blackview Oscal C80. Что на самом деле выдаёт недорогой телефон и какие приёмы в макете работают на его вид.',
	 '<h2>Недорогий телефон не зобов&#39;язаний виглядати дешево</h2><p>Blackview Oscal C80 — апарат із нижнього цінового поверху, і купують його свідомо: потрібен робочий телефон, а не статус. Але між «недорогий» і «виглядає дешево» знака рівності немає. Здалеку ціну корпусу ніхто не зчитує — зчитують інше.</p><h3>Що насправді видає бюджетність</h3><p>Не форма й не матеріал корпусу. Видають дрібниці навколо: наліпка з характеристиками, яку так і не зняли зі спинки; захисна плівка з бульбашками, що відходить по краю; чохол із логотипом чужого магазину; тріщинка на склі, з якою ходять півроку. Усе це помітно з півтора метра, а сам апарат — ні.</p><p>Чохол тут найпростіший важіль. Він закриває більшу частину видимої площі телефона, і в очі кидається саме він.</p><p>Перевірити це легко на чужих телефонах. Згадайте, чи ви колись у транспорті придивлялись, яка модель у сусіда. Найімовірніше, ні — зате запам&#39;ятали чохол із незвичним малюнком, побачений місяць тому. Апарат розчиняється в загальній масі, оформлення — ні.</p><h3>Прийоми, які працюють на вигляд</h3><ul><li><strong>Щільний темний колір.</strong> Глибокий синій, графіт, темно-зелений, винний. Такі заливки виглядають дорожче за будь-який строкатий сюжет.</li><li><strong>Мінімум елементів.</strong> Одне зображення або один напис. Кожна зайва деталь у макеті здешевлює результат.</li><li><strong>Без блиску й переливів.</strong> Імітація золота, металу й «діамантів» дає рівно протилежний ефект.</li><li><strong>Один шрифт.</strong> Два різні накреслення в одному макеті одразу видають саморобність.</li></ul><p>Найсильніший варіант для такої моделі — суцільний темний фон і невеликий світлий напис ближче до низу. Блеквью Оскал С80 у такому чохлі не вдає із себе дорожчий апарат, ніж він є, — він просто виглядає доглянутим. Це різні речі, і люди зчитують другу.</p><p>Окремо про вибір між фотографією й однотонним фоном. На бюджетному апараті суцільний колір майже завжди виграє: фото на спинці вимагає, щоб і сам кадр був сильним, інакше він тягне за собою відчуття випадковості. Один колір випадковим не буває — він виглядає як рішення. Тому для першого чохла на такий телефон простий фон із дрібним написом — найкоротший шлях до пристойного результату.</p><p>Ще одне спостереження. Дорогі телефони частіше носять голими або в прозорому — там показують сам апарат. Недорогі виграють від протилежного: коли на спинці ваше зображення, увага йде до нього, а не до того, що це за модель. Питання «що в тебе за телефон?» просто не виникає — виникає «а де ти таке взяв?».</p>',
	 '<h2>Недорогой телефон не обязан выглядеть дёшево</h2><p>Blackview Oscal C80 — аппарат с нижнего ценового этажа, и покупают его осознанно: нужен рабочий телефон, а не статус. Но между «недорогой» и «выглядит дёшево» знака равенства нет. Издалека цену корпуса никто не считывает — считывают другое.</p><h3>Что на самом деле выдаёт бюджетность</h3><p>Не форма и не материал корпуса. Выдают мелочи вокруг: наклейка с характеристиками, которую так и не сняли со спинки; защитная плёнка с пузырями, отходящая по краю; чехол с логотипом чужого магазина; трещинка на стекле, с которой ходят полгода. Всё это видно с полутора метров, а сам аппарат — нет.</p><p>Чехол здесь самый простой рычаг. Он закрывает большую часть видимой площади телефона, и в глаза бросается именно он.</p><p>Проверить это легко на чужих телефонах. Вспомните, приглядывались ли вы когда-нибудь в транспорте, какая модель у соседа. Скорее всего, нет — зато запомнили чехол с необычным рисунком, увиденный месяц назад. Аппарат растворяется в общей массе, оформление — нет.</p><h3>Приёмы, работающие на внешность</h3><ul><li><strong>Плотный тёмный цвет.</strong> Глубокий синий, графит, тёмно-зелёный, винный. Такие заливки выглядят дороже любого пёстрого сюжета.</li><li><strong>Минимум элементов.</strong> Одно изображение или одна надпись. Каждая лишняя деталь в макете удешевляет результат.</li><li><strong>Без блеска и переливов.</strong> Имитация золота, металла и «бриллиантов» даёт ровно обратный эффект.</li><li><strong>Один шрифт.</strong> Два разных начертания в одном макете сразу выдают самоделку.</li></ul><p>Самый сильный вариант для такой модели — сплошной тёмный фон и небольшая светлая надпись ближе к низу. Блэквью Оскал С80 в таком чехле не притворяется дороже, чем он есть, — он просто выглядит ухоженным. Это разные вещи, и окружающие считывают вторую.</p><p>Отдельно о выборе между фотографией и однотонным фоном. На бюджетном аппарате сплошной цвет почти всегда выигрывает: фото на спинке требует, чтобы и сам кадр был сильным, иначе он тянет за собой ощущение случайности. Один цвет случайным не бывает — он выглядит как решение. Поэтому для первого чехла на такой телефон простой фон с мелкой надписью — самый короткий путь к приличному результату.</p><p>Ещё наблюдение. Дорогие телефоны чаще носят голыми или в прозрачном — там показывают сам аппарат. Недорогие выигрывают от обратного: когда на спинке ваше изображение, внимание уходит к нему, а не к тому, что это за модель. Вопрос «что у тебя за телефон?» просто не возникает — возникает «а где ты такое взял?».</p>',
	 NULL, NULL, 1);

-- samsung-galaxy-a56-5g — кут: які сюжети замовляють найчастіше і чого в списку немає
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-samsung-galaxy-a56-5g', 'template',
	 'Чохол з фото на замовлення для Samsung Galaxy A56 5G', 'Чехол с фото на заказ для Samsung Galaxy A56 5G',
	 'Чохол з фото для Samsung Galaxy A56 5G — друк | FLOY', 'Чехол с фото для Samsung Galaxy A56 5G — печать | FLOY',
	 'Свій принт на чохлі для Samsung Galaxy A56 5G. Чотири теми, які замовляють найчастіше, і сюжети, яких майже ніхто не друкує, — а варто було б.',
	 'Свой принт на чехле для Samsung Galaxy A56 5G. Четыре темы, которые заказывают чаще всего, и сюжеты, которые почти никто не печатает, — а зря.',
	 '<h2>Що люди насправді ставлять на чохли</h2><p>Коли перед вами порожній конструктор, найважче не техніка, а вибір сюжету. Тут допомагає підглянути, що замовляють інші. Samsung Galaxy A56 5G — модель масова, і картина по ній та сама, що по всьому середньому сегменту: сюжети повторюються з місяця в місяць, і їх насправді небагато.</p><h3>Чотири теми, на яких тримається більшість замовлень</h3><p><strong>Люди.</strong> Діти, пара, батьки, компанія друзів. Найчастіша категорія і найризикованіша: групові кадри на чохлі майже завжди програють одному портрету великим планом.</p><p><strong>Тварини.</strong> Свій кіт, собака, кінь, зрідка папуга. Друга за частотою тема й найбезпечніша: улюбленець не змінює зачіску й не свариться з вами.</p><p><strong>Місця.</strong> Море, гори, вулиця рідного міста, будинок у селі. Працює тоді, коли в кадрі є одна велика форма — горизонт, схил, стіна. Загальні краєвиди з дрібними деталями на спинці розсипаються.</p><p><strong>Слова.</strong> Ім&#39;я, дата, коротка фраза, ініціали. Найлегший за зусиллями і найстабільніший за результатом варіант.</p><p>Розподіл між цими темами тримається рівним рік у рік і майже не залежить від моделі телефона. Змінюється хіба сезонність: ближче до свят більшає замовлень із дітьми й підписами, влітку — з морем і горами, у вересні — зі шкільними кадрами.</p><h3>Чого в цьому списку немає</h3><p>Майже ніхто не друкує складні колажі з шести фотографій, дрібний текст на кілька речень і чужі логотипи. Перші два фізично не читаються, третє легко купити готовим.</p><p>Є й те, чого в замовленнях мало, хоча воно того варте, — предмети. Стара камера, велосипед, шахова дошка, інструмент, з яким ви працюєте. Такі чохли запам&#39;ятовуються краще за портрети, бо їх майже ні в кого немає.</p><p>Варто сказати й про те, як ці теми поєднуються. Найстійкіші макети виходять, коли головна тема одна, а друга додана дрібно: портрет із датою в куті, гори з назвою місця маленьким рядком, тварина з одним словом унизу. А спроба звести дві сильні теми в один макет — фото людини й фото собаки поруч — майже завжди лишає відчуття, що на чохол не вистачило місця.</p><p>Практичний висновок для власника Самсунг Галаксі А56 5G простий. Ідеї немає взагалі — беріть тварину або слово, це два безпрограшні шляхи. Хочеться, щоб чохол помічали, — шукайте сюжет за межами чотирьох звичних тем.</p>',
	 '<h2>Что люди на самом деле ставят на чехлы</h2><p>Когда перед вами пустой конструктор, тяжелее всего не техника, а выбор сюжета. Тут помогает подсмотреть, что заказывают другие. Samsung Galaxy A56 5G — модель массовая, и картина по ней та же, что по всему среднему сегменту: сюжеты повторяются из месяца в месяц, и их на самом деле немного.</p><h3>Четыре темы, на которых держится большинство заказов</h3><p><strong>Люди.</strong> Дети, пара, родители, компания друзей. Самая частая категория и самая рискованная: групповые кадры на чехле почти всегда проигрывают одному портрету крупным планом.</p><p><strong>Животные.</strong> Свой кот, собака, лошадь, изредка попугай. Вторая по частоте тема и самая безопасная: питомец не меняет причёску и не ссорится с вами.</p><p><strong>Места.</strong> Море, горы, улица родного города, дом в селе. Работает, когда в кадре есть одна крупная форма — горизонт, склон, стена. Общие виды с мелкими деталями на спинке рассыпаются.</p><p><strong>Слова.</strong> Имя, дата, короткая фраза, инициалы. Самый лёгкий по усилиям и самый стабильный по результату вариант.</p><p>Соотношение между этими темами держится ровным год от года и почти не зависит от модели телефона. Меняется разве что сезонность: ближе к праздникам прибавляется заказов с детьми и подписями, летом — с морем и горами, в сентябре — со школьными кадрами.</p><h3>Чего в этом списке нет</h3><p>Почти никто не печатает сложные коллажи из шести фотографий, мелкий текст в несколько предложений и чужие логотипы. Первые два физически не читаются, третье легко купить готовым.</p><p>Есть и то, чего в заказах мало, хотя оно того стоит, — предметы. Старая камера, велосипед, шахматная доска, инструмент, с которым вы работаете. Такие чехлы запоминаются лучше портретов, потому что их почти ни у кого нет.</p><p>Стоит сказать и о том, как эти темы сочетаются. Самые устойчивые макеты получаются, когда главная тема одна, а вторая добавлена мелко: портрет с датой в углу, горы с названием места маленькой строкой, животное с одним словом внизу. А попытка свести две сильные темы в один макет — фото человека и фото собаки рядом — почти всегда оставляет ощущение, что на чехол не хватило места.</p><p>Практический вывод для владельца Самсунг Галакси А56 5G простой. Идеи нет вообще — берите животное или слово, это два беспроигрышных пути. Хочется, чтобы чехол замечали, — ищите сюжет за пределами четырёх привычных тем.</p>',
	 NULL, NULL, 1);

-- zte-blade-a76 — кут: домашній улюбленець на чохлі, як зняти тварину для друку
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-zte-blade-a76', 'template',
	 'Чохол з фото на замовлення для ZTE Blade A76', 'Чехол с фото на заказ для ZTE Blade A76',
	 'Чохол з фото улюбленця для ZTE Blade A76 — друк | FLOY', 'Чехол с фото питомца для ZTE Blade A76 — печать | FLOY',
	 'Чохол із фото кота чи собаки для ZTE Blade A76. Як зняти тварину так, щоб на друку вона лишилася впізнаваною: світло, ракурс, фон, кадрування.',
	 'Чехол с фото кота или собаки для ZTE Blade A76. Как снять питомца так, чтобы на печати он остался узнаваемым: свет, ракурс, фон, кадрирование.',
	 '<h2>Кіт, який їде з вами в кишені</h2><p>Свій пес чи кіт — один із найчастіших сюжетів на чохлах і найпростіший у виборі: кого друкувати, тут сумнівів не виникає. Складність в іншому — тварину треба зняти так, щоб на силіконі вона лишилася впізнаваною. Виходить це далеко не з кожного кадру в галереї.</p><h3>Кадр, який добре друкується</h3><p>Тварина не позує, тому в галереї зазвичай сотні фото й жодного придатного: то змазано, то видно саму спину, то фоном килим із візерунком. Кілька правил економлять годину гортання:</p><ul><li>знімайте при світлі з вікна, без спалаху — від спалаху очі світяться зеленим, і на друку це вже не виправити;</li><li>тримайте камеру на рівні очей тварини, а не згори: вигляд зверху перетворює морду на пляму;</li><li>фон беріть простий — стіна, плед, підлога без малюнка;</li><li>кадруйте щільно: морда й груди, решта зайва;</li><li>темну тварину знімайте на світлому тлі, світлу — на темному, інакше силует зіллється.</li></ul><p>Найкраще працює момент, коли улюбленець щойно прокинувся або зацікавлено дивиться на щось у ваших руках. Дві секунди уваги — і кадр є.</p><p>Якщо тварин у домі дві, спокуса поставити обох на один чохол велика — але кадр, де вони поруч і обидві дивляться в камеру, трапляється раз на рік. Простіше зробити інакше: взяти два окремі портрети й поставити один під одним, кожен на своєму тлі. Виглядає це чистіше за спробу зловити обох в одну секунду, і кожну морду видно повністю.</p><h3>Сюжет, про який згадують пізніше</h3><p>Окрема історія — чохол із твариною, якої вже немає. З таким замовленням приходять через місяці після втрати й часто вибачаються, ніби це дивно. Це не дивно. Фотографія в телефоні відкривається за бажанням, а спинка просто є щодня — і для багатьох це виявляється правильнішою формою пам&#39;яті, ніж альбом, у який не заглядаєш.</p><p>Технічно з ZTE Blade A76 усе нескладно: беріть кадр із найбільшою кількістю деталей на морді, ставте його так, щоб очі опинилися приблизно в середині спинки, а фон за потреби замініть суцільним кольором — це прибирає зайве оточення й лишає саму тварину.</p><p>І дрібниця з життя. Чохол із власним котом на ЗТЕ Блейд А76 гарантує одну повторювану сцену: у черзі чи в транспорті хтось обов&#39;язково запитає, як його звати.</p>',
	 '<h2>Кот, который едет с вами в кармане</h2><p>Свой пёс или кот — один из самых частых сюжетов на чехлах и самый простой в выборе: кого печатать, тут сомнений не возникает. Сложность в другом — питомца нужно снять так, чтобы на силиконе он остался узнаваемым. Получается это далеко не из каждого кадра в галерее.</p><h3>Кадр, который хорошо печатается</h3><p>Животное не позирует, поэтому в галерее обычно сотни фото и ни одного пригодного: то смазано, то видна одна спина, то фоном ковёр с узором. Несколько правил экономят час листания:</p><ul><li>снимайте при свете из окна, без вспышки — от вспышки глаза светятся зелёным, и на печати это уже не исправить;</li><li>держите камеру на уровне глаз питомца, а не сверху: вид сверху превращает морду в пятно;</li><li>фон берите простой — стена, плед, пол без рисунка;</li><li>кадрируйте плотно: морда и грудь, остальное лишнее;</li><li>тёмное животное снимайте на светлом фоне, светлое — на тёмном, иначе силуэт сольётся.</li></ul><p>Лучше всего работает момент, когда питомец только проснулся или заинтересованно смотрит на что-то в ваших руках. Две секунды внимания — и кадр есть.</p><p>Если питомцев дома двое, соблазн поставить обоих на один чехол велик — но кадр, где они рядом и оба смотрят в камеру, случается раз в год. Проще иначе: взять два отдельных портрета и поставить один под другим, каждый на своём фоне. Выглядит это чище попытки поймать обоих в одну секунду, и каждую морду видно целиком.</p><h3>Сюжет, о котором вспоминают позже</h3><p>Отдельная история — чехол с животным, которого уже нет. С таким заказом приходят спустя месяцы после потери и часто извиняются, будто это странно. Это не странно. Фотография в телефоне открывается по желанию, а спинка просто есть каждый день — и для многих это оказывается более верной формой памяти, чем альбом, в который не заглядываешь.</p><p>Технически с ZTE Blade A76 всё несложно: берите кадр с наибольшим количеством деталей на морде, ставьте его так, чтобы глаза оказались примерно в середине спинки, а фон при необходимости замените сплошным цветом — это убирает лишнее окружение и оставляет самого питомца.</p><p>И мелочь из жизни. Чехол с собственным котом на ЗТЕ Блейд А76 гарантирует одну повторяющуюся сцену: в очереди или в транспорте кто-нибудь обязательно спросит, как его зовут.</p>',
	 NULL, NULL, 1);

-- honor-magic-5-lite-5g — кут: телефон живе в автотримачі, кріплення закриває частину макета
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-honor-magic-5-lite-5g', 'template',
	 'Чохол з фото на замовлення для Huawei Honor Magic 5 Lite 5G', 'Чехол с фото на заказ для Huawei Honor Magic 5 Lite 5G',
	 'Чохол з фото для Honor Magic 5 Lite 5G — друк | FLOY', 'Чехол с фото для Honor Magic 5 Lite 5G — печать | FLOY',
	 'Друк на чохлі для Honor Magic 5 Lite 5G. Якщо телефон живе в автотримачі, макет збирають інакше — розповідаємо, що саме закриває кріплення.',
	 'Печать на чехле для Honor Magic 5 Lite 5G. Если телефон живёт в автодержателе, макет собирают иначе — рассказываем, что именно закрывает крепление.',
	 '<h2>Телефон, який півдня стоїть у тримачі</h2><p>Є окрема категорія власників: телефон у них живе не в кишені, а на кронштейні. Навігація, дзвінки в дорозі, музика, іноді відео на паузі під час стоянки. Huawei Honor Magic 5 Lite 5G у такому режимі проводить закріпленим більше часу, ніж у руці, — і для чохла це геть інші умови.</p><h3>Тримач з&#39;їдає частину макета</h3><p>Усе залежить від типу кріплення, і подумати про це варто до того, як макет зібрано.</p><p>Затискний тримач накриває бічні краї чохла приблизно на сантиметр з кожного боку — усе, що поставлено впритул до краю, зникає. Магнітний працює інакше: металева пластина клеїться приблизно на центр спинки й закриває якраз середину, те саме місце, куди рука тягнеться поставити головне.</p><p>Звідси простий висновок. Користуєтесь магнітним кріпленням — лишіть центр спокійним: рівний фон, продовження текстури, а сюжет і напис зсуньте вище або нижче. Тримач затискний — тримайте все важливе в межах середньої третини по ширині.</p><h3>Не тільки машина</h3><p>Той самий принцип діє скрізь, де телефон стоїть, а не лежить: підставка на робочому столі, кухонний тримач із рецептом, кріплення на кермі велосипеда, штатив для зйомки. Спільне в них одне — апарат закріплений спинкою до вас або до людей поруч, і бачать її довше, ніж зазвичай.</p><p>Окремий випадок — коли в машині бувають не тільки свої. Таксі, розвозка, робота з клієнтами: телефон у тримачі опиняється перед очима сторонніх по кілька годин на день. Тут виграють нейтральні сюжети — краєвид, геометрія, однотонний фон з ініціалами. Сімейні фотографії краще лишити для другого чохла, який вдягається після зміни.</p><p>Перевірити все це можна заздалегідь. Поставте телефон у свій тримач так, як він стоїть щодня, і подивіться, які зони спинки лишаються відкритими. Ті самі межі перенесіть подумки на прев&#39;ю в конструкторі — одразу стане видно, чи не потрапляє головне під затискач. Хвилина на перевірку економить розчарування, коли готовий чохол уперше опиняється в кріпленні. Особливо якщо тримач у вас не один: у машині одне кріплення, на робочому столі інше.</p><p>І останнє. Сюжет для такого сценарію варто брати такий, що не потребує пояснень. Кадр із дороги, гори, море, силует авто, ім&#39;я дитини — на Хуавей Хонор Меджик 5 Лайт 5G такі принти виглядають доречно саме тоді, коли телефон стоїть перед очима у всіх, хто в салоні.</p>',
	 '<h2>Телефон, который полдня стоит в держателе</h2><p>Есть отдельная категория владельцев: телефон у них живёт не в кармане, а на кронштейне. Навигация, звонки в дороге, музыка, иногда видео на паузе во время стоянки. Huawei Honor Magic 5 Lite 5G в таком режиме проводит закреплённым больше времени, чем в руке, — и для чехла это совсем другие условия.</p><h3>Держатель съедает часть макета</h3><p>Всё зависит от типа крепления, и подумать об этом стоит до того, как макет собран.</p><p>Прижимной держатель накрывает боковые края чехла примерно на сантиметр с каждой стороны — всё, что поставлено впритык к краю, исчезает. Магнитный работает иначе: металлическая пластина клеится примерно на центр спинки и закрывает как раз середину, то самое место, куда рука тянется поставить главное.</p><p>Отсюда простой вывод. Пользуетесь магнитным креплением — оставьте центр спокойным: ровный фон, продолжение текстуры, а сюжет и надпись сдвиньте выше или ниже. Держатель прижимной — держите всё важное в пределах средней трети по ширине.</p><h3>Не только машина</h3><p>Тот же принцип действует везде, где телефон стоит, а не лежит: подставка на рабочем столе, кухонный держатель с рецептом, крепление на руле велосипеда, штатив для съёмки. Общее у них одно — аппарат закреплён спинкой к вам или к людям рядом, и видят её дольше обычного.</p><p>Отдельный случай — когда в машине бывают не только свои. Такси, развозка, работа с клиентами: телефон в держателе оказывается перед глазами посторонних по нескольку часов в день. Здесь выигрывают нейтральные сюжеты — пейзаж, геометрия, однотонный фон с инициалами. Семейные фотографии лучше оставить для второго чехла, который надевается после смены.</p><p>Проверить всё это можно заранее. Поставьте телефон в свой держатель так, как он стоит каждый день, и посмотрите, какие зоны спинки остаются открытыми. Те же границы мысленно перенесите на превью в конструкторе — сразу станет видно, не попадает ли главное под зажим. Минута на проверку экономит разочарование, когда готовый чехол впервые оказывается в креплении. Особенно если держатель у вас не один: в машине одно крепление, на рабочем столе другое.</p><p>И последнее. Сюжет для такого сценария стоит брать не требующий пояснений. Кадр с дороги, горы, море, силуэт машины, имя ребёнка — на Хуавей Хонор Меджик 5 Лайт 5G такие принты смотрятся уместно именно тогда, когда телефон стоит перед глазами у всех, кто в салоне.</p>',
	 NULL, NULL, 1);

