-- samsung-galaxy-a24 — кут: чорно-білий макет, коли колір у кадрі тільки заважає
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-samsung-galaxy-a24', 'template',
	 'Чохол з фото на замовлення для Samsung Galaxy A24', 'Чехол с фото на заказ для Samsung Galaxy A24',
	 'Чохол з фото для Samsung Galaxy A24 — друк на замовлення | FLOY', 'Чехол с фото для Samsung Galaxy A24 — печать на заказ | FLOY',
	 'Друк вашого фото на чохлі для Samsung Galaxy A24. Чому чорно-білий кадр на спинці часто сильніший за кольоровий і які знімки виграють у монохромі.',
	 'Печать вашего фото на чехле для Samsung Galaxy A24. Почему чёрно-белый кадр на спинке часто сильнее цветного и какие снимки выигрывают в монохроме.',
	 '<h2>Коли колір тільки заважає</h2><p>Порада, яка спершу звучить дивно: переведіть своє фото в чорно-біле й подивіться на прев&#39;ю ще раз. У доброї половини випадків макет стає сильнішим. Причина проста — на чохлі працює не сюжет, а форма, а колір часто тягне увагу на себе й розсипає кадр на плями.</p><p>Samsung Galaxy A24 у цьому сенсі показовий: спинка рівна, чимала, без вигинів по краях, і будь-яка кольорова строкатість на ній помітна одразу.</p><h3>Які кадри виграють у монохромі</h3><ul><li>портрети — шкіра перестає жовтити, лишається світло й вираз обличчя;</li><li>знімки, зроблені в приміщенні при лампі, — зникає помаранчевий наліт;</li><li>міські краєвиди: асфальт, бетон і скло стають графікою, а не сірою мішаниною;</li><li>старі фотографії з альбому — вони й так близькі до монохрому;</li><li>кадри з кількома джерелами світла, де баланс кольору поплив.</li></ul><p>А от що в чорно-білому втрачає — захід сонця, море, осінній ліс, квіти, страви. Усе, де сенс кадру саме в кольорі, після переведення в сіре перетворюється на ніщо.</p><h3>Півкроку замість повного</h3><p>Є проміжний варіант, який мало хто пробує: лишити зображення чорно-білим, а колір віддати тільки напису. Червоне ім&#39;я на сірому фото, жовтий рядок унизу, синя дата в кутку. Око чіпляється рівно за одне місце, і макет виглядає навмисним, а не випадковим.</p><p>Другий прийом — знизити насиченість не до нуля, а приблизно наполовину. Кольори лишаються, але перестають сперечатись між собою. Так найчастіше рятують кадри, зняті в яскравий полудень.</p><h3>Чому це працює саме на чохлі</h3><p>Екран підсвічує зображення зсередини, і в галереї кольори завжди соковитіші. Силікон не світиться. Чорно-білого ця різниця не стосується взагалі: у нього немає стану «зблякло», є тільки світле й темне.</p><p>Звідси простий тест. Якщо вагаєтесь між двома кадрами, зробіть обидва сірими й порівняйте. Виграє той, у якому й без кольору видно, що відбувається, — значить, фотографія тримається на композиції, а не на яскравому небі.</p><p>Технічно перевести кадр у сіре найпростіше ще до завантаження — вбудований редактор галереї це вміє в будь-якому телефоні: відкрили фото, знайшли фільтри, зберегли копію. Саме копію, а не оригінал: кольорова версія знадобиться, якщо порівняння виявиться не на користь монохрому.</p><p>І дрібниця для Гелексі А24: у монохромному макеті фон теж варто лишити в сірій шкалі — світло-сірий, вугільний, майже чорний. Одна кольорова заливка під чорно-білим знімком зазвичай руйнує все, що ви до того зібрали.</p>',
	 '<h2>Когда цвет только мешает</h2><p>Совет, который поначалу звучит странно: переведите своё фото в чёрно-белое и посмотрите на превью ещё раз. В доброй половине случаев макет становится сильнее. Причина простая — на чехле работает не сюжет, а форма, а цвет часто тянет внимание на себя и рассыпает кадр на пятна.</p><p>Samsung Galaxy A24 в этом смысле показателен: спинка ровная, немаленькая, без заваленных краёв, и любая цветовая пестрота на ней заметна сразу.</p><h3>Какие кадры выигрывают в монохроме</h3><ul><li>портреты — кожа перестаёт желтить, остаётся свет и выражение лица;</li><li>снимки, сделанные в помещении при лампе, — уходит оранжевый налёт;</li><li>городские виды: асфальт, бетон и стекло становятся графикой, а не серой мешаниной;</li><li>старые фотографии из альбома — они и так близки к монохрому;</li><li>кадры с несколькими источниками света, где баланс цвета поплыл.</li></ul><p>А теряет в чёрно-белом закат, море, осенний лес, цветы, еда. Всё, где смысл кадра именно в цвете, после перевода в серое превращается в ничто.</p><h3>Полшага вместо целого</h3><p>Есть промежуточный вариант, который пробуют редко: оставить изображение чёрно-белым, а цвет отдать только надписи. Красное имя на сером снимке, жёлтая строка внизу, синяя дата в углу. Глаз цепляется ровно за одно место, и макет выглядит намеренным, а не случайным.</p><p>Второй приём — снизить насыщенность не до нуля, а примерно наполовину. Цвета остаются, но перестают спорить между собой. Так чаще всего спасают кадры, снятые ярким полуднем.</p><h3>Почему это работает именно на чехле</h3><p>Экран подсвечивает изображение изнутри, и в галерее цвета всегда сочнее. Силикон не светится. Чёрно-белого эта разница не касается вовсе: у него нет состояния «поблёкло», есть только светлое и тёмное.</p><p>Отсюда простой тест. Колеблетесь между двумя кадрами — сделайте оба серыми и сравните. Выиграет тот, где и без цвета понятно, что происходит: значит, фотография держится на композиции, а не на ярком небе.</p><p>Технически перевести кадр в серое проще всего ещё до загрузки — встроенный редактор галереи это умеет в любом телефоне: открыли фото, нашли фильтры, сохранили копию. Именно копию, а не оригинал: цветная версия пригодится, если сравнение окажется не в пользу монохрома.</p><p>И мелочь для Галакси А24: в монохромном макете фон тоже стоит оставить в серой шкале — светло-серый, угольный, почти чёрный. Одна цветная заливка под чёрно-белым снимком обычно рушит всё, что вы до этого собрали.</p>',
	 NULL, NULL, 1);

-- samsung-galaxy-s25-fe — кут: портрет людини, кадрування обличчя й фон за ним
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-samsung-galaxy-s25-fe', 'template',
	 'Чохол з фото на замовлення для Samsung Galaxy S25 FE', 'Чехол с фото на заказ для Samsung Galaxy S25 FE',
	 'Чохол з фото для Samsung Galaxy S25 FE — друк | FLOY', 'Чехол с фото для Samsung Galaxy S25 FE — печать | FLOY',
	 'Портрет на чохлі для Samsung Galaxy S25 FE. Як кадрувати обличчя, скільки лишати місця над головою і що робити з невдалим фоном за людиною.',
	 'Портрет на чехле для Samsung Galaxy S25 FE. Как кадрировать лицо, сколько оставлять места над головой и что делать с неудачным фоном за человеком.',
	 '<h2>Обличчя на спинці телефона</h2><p>Портрет — найчастіше замовлення й водночас те, з чим найчастіше промахуються. Причина рідко в якості знімка. Просто фотографія, зроблена на пам&#39;ять, і фотографія, придатна для друку на предметі, — це різні кадри.</p><p>Samsung Galaxy S25 FE беруть переважно ті, хто знімає багато: це спрощена версія флагманської лінійки, і камера тут одна з причин покупки. Портретів у галереї вистачає, питання тільки в тому, який із них поїде на чохол.</p><h3>Правило одного обличчя</h3><p>Одна людина в кадрі — майже завжди правильно. Двоє — можна, якщо вони поруч і в одному плані. Троє й більше перетворюють чохол на групову карточку, де облич не роздивитись.</p><p>Розмір теж вирішує. Найкраще читається план від грудей до маківки: обличчя займає приблизно третину висоти чохла. Портрет упритул, на весь силікон, виглядає нав&#39;язливо, а фігура в повний зріст перетворює людину на силует.</p><h3>Куди дивиться людина</h3><p>Дрібниця, яку помічають уже після друку: погляд має бути спрямований у кадр, а не з нього. Якщо людина дивиться вліво, лишіть зліва більше вільного місця. Інакше виникає відчуття, що обличчя впирається в край і хоче вийти за нього.</p><p>Друге — простір над головою. Невеликий запас потрібен обов&#39;язково: маківка, що торкається верхнього краю, читається як помилка, навіть коли все інше зроблено акуратно.</p><p>Третє — верхній лівий кут спинки зайнятий камерами. Обличчя туди заводити не варто. Найбезпечніша зона для голови — центр і трохи нижче центру.</p><h3>Що з фоном</h3><p>Фон у портреті важить майже стільки ж, скільки саме обличчя. Найкраще працюють знімки, де за людиною рівна поверхня: стіна, небо, вода, розмите тло з портретного режиму. Кухня з посудом чи вулиця з машинами позаду тягнуть увагу на себе, і на чохлі це помітніше, ніж на екрані.</p><p>Якщо фон невдалий, є два виходи. Обрізати щільніше, щоб обличчя зайняло майже всю площу. Або замінити тло суцільною заливкою й лишити саму людину — складніше, але результат ближчий до студійного.</p><p>Остання перевірка перед замовленням: подивіться на прев&#39;ю Самсунг Галаксі С25 ФЕ з відстані витягнутої руки. Впізнати людину з такої дистанції можна — макет готовий. Не можна — беріть кадр із більшим планом, а не збільшуйте той самий: обличчя стане більшим, різкість — ні. Це правило економить більше зіпсованих макетів, ніж усі інші поради разом.</p>',
	 '<h2>Лицо на спинке телефона</h2><p>Портрет — самый частый заказ и одновременно то, с чем чаще всего промахиваются. Причина редко в качестве снимка. Просто фотография, сделанная на память, и фотография, годная для печати на предмете, — разные кадры.</p><p>Samsung Galaxy S25 FE берут в основном те, кто снимает много: это упрощённая версия флагманской линейки, и камера здесь одна из причин покупки. Портретов в галерее хватает, вопрос лишь в том, какой из них поедет на чехол.</p><h3>Правило одного лица</h3><p>Один человек в кадре — почти всегда верно. Двое — можно, если они рядом и в одном плане. Трое и больше превращают чехол в групповую карточку, где лиц не разобрать.</p><p>Размер тоже решает. Лучше всего читается план от груди до макушки: лицо занимает примерно треть высоты чехла. Портрет впритык, во весь силикон, выглядит навязчиво, а фигура в полный рост превращает человека в силуэт.</p><h3>Куда смотрит человек</h3><p>Мелочь, которую замечают уже после печати: взгляд должен быть направлен в кадр, а не из него. Смотрит человек влево — оставьте слева больше свободного места. Иначе возникает ощущение, что лицо упирается в край и хочет выйти за него.</p><p>Второе — пространство над головой. Небольшой запас нужен обязательно: макушка, касающаяся верхнего края, читается как ошибка, даже когда всё остальное сделано аккуратно.</p><p>Третье — верхний левый угол спинки занят камерами. Лицо туда заводить не стоит. Самая безопасная зона для головы — центр и чуть ниже центра.</p><h3>Что с фоном</h3><p>Фон в портрете весит почти столько же, сколько само лицо. Лучше всего работают снимки, где за человеком ровная поверхность: стена, небо, вода, размытое тло из портретного режима. Кухня с посудой или улица с машинами позади тянут внимание на себя, и на чехле это виднее, чем на экране.</p><p>Если фон неудачный, выхода два. Обрезать плотнее, чтобы лицо заняло почти всю площадь. Или заменить задник сплошной заливкой и оставить самого человека — сложнее, но результат ближе к студийному.</p><p>Последняя проверка перед заказом: посмотрите на превью Самсунг Галакси С25 ФЕ с расстояния вытянутой руки. Узнать человека с такой дистанции получается — макет готов. Не получается — берите кадр с более крупным планом, а не увеличивайте тот же: лицо станет больше, резкость нет. Это правило спасает больше испорченных макетов, чем все прочие советы вместе взятые.</p>',
	 NULL, NULL, 1);

-- xiaomi-redmi-14c — кут: чохол для тих, хто далеко від рідних
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-xiaomi-redmi-14c', 'template',
	 'Чохол з фото на замовлення для Xiaomi Redmi 14C', 'Чехол с фото на заказ для Xiaomi Redmi 14C',
	 'Чохол з фото для Xiaomi Redmi 14C — друк на замовлення | FLOY', 'Чехол с фото для Xiaomi Redmi 14C — печать на заказ | FLOY',
	 'Фото рідних на чохлі для Xiaomi Redmi 14C. Знімок на спинці не треба відкривати — він просто є в руці щодня, коли близькі далеко.',
	 'Фото родных на чехле для Xiaomi Redmi 14C. Снимок на спинке не нужно открывать — он просто есть в руке каждый день, когда близкие далеко.',
	 '<h2>Коли ті, кого хочеться бачити, далеко</h2><p>Телефон і так повний фотографій рідних. Але їх треба відкривати: розблокувати, знайти альбом, прогорнути. Знімок на спинці відкривати не потрібно — він просто є, весь час, у руці. Для людей, які живуть окремо від сім&#39;ї, ця різниця виявляється більшою, ніж здається збоку.</p><p>Xiaomi Redmi 14C часто беруть саме в таких обставинах: недорогий надійний апарат для роботи в іншій країні, для навчання в іншому місті, як другий телефон у дорозі.</p><h3>Який кадр вибрати</h3><p>Не найкращий за якістю, а той, від якого стає тепліше. Замовлення тут дуже показові: постановочні студійні портрети друкують рідко. Друкують кухню, двір, руку дитини, стару світлину батьків, вікно свого дому.</p><ul><li>одна людина великим планом замість групового портрета;</li><li>кадр, знятий кимось із них, а не вами, — тоді на чохлі буквально їхній погляд;</li><li>місце замість людей: під&#39;їзд, поле, дорога, яку ви знаєте напам&#39;ять;</li><li>дитячий малюнок, надісланий у месенджері, — його теж друкують.</li></ul><h3>Той самий задум у двох напрямках</h3><p>Схема, про яку варто знати: чохли роблять обидві сторони. Ви друкуєте фото сім&#39;ї, а вдома роблять чохол із вашим — і в кожного в руці той, кого поруч немає. Коштує це менше за квиток і працює щодня, а не раз на тиждень у відеодзвінку.</p><p>Якщо телефон згодом перейде комусь із рідних, чохол лишиться разом із ним. Річ не з тих, які викидають при передачі апарата.</p><h3>Особисте, зрозуміле лише вам</h3><p>Сюжет не обов&#39;язково має читатись стороннім. Вікно, кухонний стіл, куточок кімнати, шматок паркану — для колеги це просто фото інтер&#39;єру чи двору. Для вас — конкретна адреса, до якої ви щодня подумки повертаєтесь. Такий чохол не викликає питань у людей навколо і при цьому робить свою роботу.</p><p>Ще один варіант — почерк. Записка, підпис на листівці, кілька слів рукою мами, сфотографовані й перенесені на спинку. Це працює сильніше за будь-який набраний шрифт, бо почерк упізнається миттєво, як голос.</p><p>Ще один момент — від&#39;їзд. Чохол, зроблений напередодні, устигає стати частиною зборів: його кладуть у сумку разом із документами, і в перший день на новому місці телефон уже виглядає як щось знайоме. Дрібниця, але в перші тижні знайомих речей поруч буває небагато.</p><p>Макет для Сяомі Редмі 14С збирається за кілька хвилин, а бачити його ви будете десятки разів на день — щоразу, коли дістаєте телефон із кишені.</p>',
	 '<h2>Когда те, кого хочется видеть, далеко</h2><p>Телефон и без того полон фотографий родных. Только их нужно открывать: разблокировать, найти альбом, пролистать. Снимок на спинке открывать не надо — он просто есть, всё время, в руке. Для тех, кто живёт отдельно от семьи, эта разница оказывается больше, чем кажется со стороны.</p><p>Xiaomi Redmi 14C часто берут именно в таких обстоятельствах: недорогой надёжный аппарат для работы в другой стране, для учёбы в другом городе, вторым телефоном в дорогу.</p><h3>Какой кадр выбрать</h3><p>Не лучший по качеству, а тот, от которого становится теплее. Заказы тут очень показательны: постановочные студийные портреты печатают редко. Печатают кухню, двор, руку ребёнка, старый снимок родителей, окно своего дома.</p><ul><li>один человек крупным планом вместо группового портрета;</li><li>кадр, снятый кем-то из них, а не вами, — тогда на чехле буквально их взгляд;</li><li>место вместо людей: подъезд, поле, дорога, которую знаете наизусть;</li><li>детский рисунок, присланный в мессенджере, — его тоже печатают.</li></ul><h3>Тот же замысел в две стороны</h3><p>Схема, о которой стоит знать: чехлы делают обе стороны. Вы печатаете фото семьи, а дома делают чехол с вашим — и у каждого в руке тот, кого рядом нет. Стоит это меньше билета и работает каждый день, а не раз в неделю в видеозвонке.</p><p>Если телефон со временем перейдёт кому-то из родных, чехол останется вместе с ним. Вещь не из тех, что выбрасывают при передаче аппарата.</p><h3>Личное, понятное только вам</h3><p>Сюжету не обязательно читаться посторонними. Окно, кухонный стол, угол комнаты, кусок забора — для коллеги это просто снимок интерьера или двора. Для вас — конкретный адрес, к которому вы каждый день мысленно возвращаетесь. Такой чехол не вызывает вопросов у окружающих и при этом делает своё дело.</p><p>Ещё вариант — почерк. Записка, подпись на открытке, несколько слов маминой рукой, снятые и перенесённые на спинку. Работает это сильнее любого набранного шрифта: почерк узнаётся мгновенно, как голос.</p><p>Ещё момент — отъезд. Чехол, сделанный накануне, успевает стать частью сборов: его кладут в сумку вместе с документами, и в первый день на новом месте телефон уже выглядит чем-то знакомым. Мелочь, но в первые недели знакомых вещей рядом бывает немного.</p><p>Макет для Сяоми Редми 14С собирается за несколько минут, а видеть его вы будете десятки раз в день — каждый раз, доставая телефон из кармана.</p>',
	 NULL, NULL, 1);

-- xiaomi-redmi-a5 — кут: чохол про ваше захоплення, а не логотип чужого бренду
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-xiaomi-redmi-a5', 'template',
	 'Чохол з фото на замовлення для Xiaomi Redmi A5', 'Чехол с фото на заказ для Xiaomi Redmi A5',
	 'Чохол з принтом для Xiaomi Redmi A5 — друк на замовлення | FLOY', 'Чехол с принтом для Xiaomi Redmi A5 — печать на заказ | FLOY',
	 'Свій принт на чохлі для Xiaomi Redmi A5. Чохол про ваше захоплення: як зняти снасті, інструмент чи велосипед, щоб на друку все читалось.',
	 'Свой принт на чехле для Xiaomi Redmi A5. Чехол о вашем увлечении: как снять снасти, инструмент или велосипед, чтобы на печати всё читалось.',
	 '<h2>Чохол, який розповідає, чим ви живете</h2><p>Найпоширеніший вибір для друку — люди й тварини. Але є категорія, яку майже не використовують, хоча підходить вона ідеально: те, чим ви займаєтесь у вільний час.</p><p>Риболовля, гори, бас-гітара, стара «копійка» в гаражі, в&#39;язання, шахи, бджоли, велосипед, сад під вікнами. Такий чохол виглядає інакше за всі інші вже тому, що подібного в магазині не продають у принципі.</p><h3>Не логотип, а власний кадр</h3><p>Тут є розвилка. Можна взяти емблему улюбленого клубу чи знак відомої марки — і отримати чохол, схожий на сотні таких самих. А можна взяти свою фотографію: вудку на світанку, верстак у гаражі, зібраний велосипед біля стіни, недоплетений кошик.</p><p>Різниця величезна. Логотип каже «мені це подобається». Власний кадр каже «я цим займаюсь».</p><h3>Як зняти захоплення, щоб було зрозуміло</h3><ul><li><strong>Інструмент, а не процес.</strong> Гриф гітари зблизька читається краще, ніж людина зі сцени здалеку.</li><li><strong>Один предмет замість купи.</strong> Одна муха для нахлисту на долоні виразніша за коробку з двадцятьма.</li><li><strong>Руки в кадрі.</strong> Долоні за роботою одразу додають знімку сенсу й масштабу.</li><li><strong>Простий фон.</strong> Стіл, тканина, земля, дошка, стіна майстерні.</li></ul><p>Xiaomi Redmi A5 недорогий і найчастіше не єдиний апарат у домі. Його якраз і беруть туди, де дорогим телефоном ризикувати не хочеться: у гараж, на воду, в майстерню, у поле. Виходить, що фотографія вашого заняття опиняється рівно там, де це заняття й відбувається.</p><p>Є й побічний ефект, про який розповідають самі замовники. Такий чохол працює як привід для розмови: людина, яка помітила в вас на телефоні знайомий предмет, майже завжди заговорить. За рік це десятки коротких розмов із тими, хто захоплюється тим самим.</p><p>Заперечення, яке виникає найчастіше: а раптом захоплення зміниться. Чесна відповідь — можливо. Але чохол і не мусить пережити десятиліття, він живе рівно стільки, скільки телефон, а за цей строк ваше нинішнє заняття точно нікуди не подінеться. До того ж набір захоплень у людини зазвичай доволі стійкий: змінюється інтенсивність, а не сам напрям.</p><p>Якщо занять кілька, не намагайтесь укласти всі в один макет. Візьміть те, яким займаєтесь щотижня, а не те, яке звучить красивіше. Чохол для Сяомі Редмі А5 не мусить представляти вас цілком — достатньо однієї чесної деталі, і вона скаже про вас більше за будь-який напис.</p>',
	 '<h2>Чехол, который рассказывает, чем вы живёте</h2><p>Самый распространённый выбор для печати — люди и животные. Но есть категория, которую почти не используют, хотя подходит она идеально: то, чем вы заняты в свободное время.</p><p>Рыбалка, горы, бас-гитара, старая «копейка» в гараже, вязание, шахматы, пчёлы, велосипед, сад под окнами. Такой чехол отличается от всех прочих уже тем, что подобного в магазине не продают в принципе.</p><h3>Не логотип, а собственный кадр</h3><p>Здесь развилка. Можно взять эмблему любимого клуба или знак известной марки — и получить чехол, похожий на сотни таких же. А можно взять свою фотографию: удочку на рассвете, верстак в гараже, собранный велосипед у стены, недоплетённую корзину.</p><p>Разница огромная. Логотип говорит «мне это нравится». Собственный кадр говорит «я этим занимаюсь».</p><h3>Как снять увлечение, чтобы было понятно</h3><ul><li><strong>Инструмент, а не процесс.</strong> Гриф гитары вблизи читается лучше, чем человек со сцены издалека.</li><li><strong>Один предмет вместо кучи.</strong> Одна мушка для нахлыста на ладони выразительнее коробки с двадцатью.</li><li><strong>Руки в кадре.</strong> Ладони за работой сразу добавляют снимку смысла и масштаба.</li><li><strong>Простой фон.</strong> Стол, ткань, земля, доска, стена мастерской.</li></ul><p>Xiaomi Redmi A5 недорогой и чаще всего не единственный аппарат в доме. Его как раз и берут туда, где дорогим телефоном рисковать не хочется: в гараж, на воду, в мастерскую, в поле. Выходит, что фотография вашего занятия оказывается ровно там, где это занятие и происходит.</p><p>Есть и побочный эффект, о котором рассказывают сами заказчики. Такой чехол работает поводом для разговора: человек, заметивший у вас на телефоне знакомый предмет, почти наверняка заговорит. За год это десятки коротких бесед с теми, кто увлечён тем же.</p><p>Возражение, которое возникает чаще всего: а вдруг увлечение сменится. Честный ответ — возможно. Но чехол и не обязан пережить десятилетие, он живёт ровно столько, сколько телефон, а за этот срок ваше нынешнее занятие никуда не денется. К тому же набор увлечений у человека обычно довольно устойчив: меняется интенсивность, а не само направление.</p><p>Если занятий несколько, не пытайтесь уместить все в один макет. Возьмите то, которым занимаетесь еженедельно, а не то, которое красивее звучит. Чехол для Сяоми Редми А5 не обязан представлять вас целиком — достаточно одной честной детали, и она скажет о вас больше любой надписи.</p>',
	 NULL, NULL, 1);

-- xiaomi-redmi-note-8-pro — кут: оновити вигляд апарата замість купівлі нового
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-xiaomi-redmi-note-8-pro', 'template',
	 'Чохол з фото на замовлення для Xiaomi Redmi Note 8 Pro', 'Чехол с фото на заказ для Xiaomi Redmi Note 8 Pro',
	 'Чохол з фото для Xiaomi Redmi Note 8 Pro — друк | FLOY', 'Чехол с фото для Xiaomi Redmi Note 8 Pro — печать | FLOY',
	 'Друк на чохлі для Xiaomi Redmi Note 8 Pro. Телефон 2019 року працює, а виглядає втомленим — і вигляд апарата майже цілком визначає чохол.',
	 'Печать на чехле для Xiaomi Redmi Note 8 Pro. Телефон 2019 года работает, а выглядит уставшим — и вид аппарата почти целиком определяет чехол.',
	 '<h2>Телефон працює, а виглядає втомленим</h2><p>Xiaomi Redmi Note 8 Pro вийшов у 2019 році, і чимала частина цих апаратів досі в щоденній роботі. Батарея вже не та, пам&#39;ять забита, але телефон дзвонить, знімає й показує. Міняти немає причини, крім однієї: він виглядає рівно на свої роки.</p><p>І ось тут виникає момент, який дивує багатьох. Вигляд телефона визначає передусім чохол, а не сам корпус.</p><h3>Що саме старить апарат</h3><p>Не подряпини на рамці, яких ніхто, крім власника, не бачить. Старить чохол, що пережив кілька років: розтягнутий, з витертим малюнком, потемнілий по краях, із заламаним кутом. Поруч із ним будь-який телефон виглядає як річ, яку доношують.</p><p>Свіжий силікон із власним принтом дає той самий ефект, що нові шнурки на старих черевиках, — непропорційно велику зміну за мінімум дій.</p><h3>Чого не варто чекати</h3><p>Чохол не зробить телефон швидшим і не додасть години автономності. Він змінює тільки те, що бачите ви й люди навколо. Але саме через це заперечення «навіщо вкладатись у старий телефон» тут не спрацьовує: вкладення мінімальне й не потребує, щоб апарат прожив ще два роки для окупності.</p><p>Порівняйте з ремонтом екрана або заміною батареї — рішеннями, після яких телефон дійсно мусить прослужити довго. Тут такого зобов&#39;язання немає взагалі.</p><h3>Що друкують на такі моделі</h3><p>Спостереження з замовлень: власники старих апаратів рідше беруть нейтральні сюжети. Телефон уже не новий, страху зіпсувати заводський вигляд немає — і люди дозволяють собі яскраве. Улюблений фільм, музика, кадр, який давно хотілося надрукувати, але «шкода було на новий».</p><p>Окрема категорія власників тримає цей апарат свідомо. Не через брак коштів, а тому, що все влаштовує: розмір звичний, усе працює, а новий телефон означає перенесення даних, нові звички й нові витрати. Для таких людей чохол — єдине, що взагалі має сенс оновлювати, і вибирають вони його ретельніше за власників свіжих моделей.</p><p>Ще одна деталь саме для Сяомі Редмі Ноут 8 Про: модель давня, і в магазинах під неї лишились здебільшого прозорі й чорні залишки. Вибір із двох варіантів — це не вибір, тож друк тут закриває питання остаточно.</p><p>А якщо апарат усе ж плануєте міняти, він, найімовірніше, нікуди не подінеться: стане другим номером, телефоном для дачі або перейде комусь із родини. Чохол поїде разом із ним — і в цьому другому житті виглядатиме навіть доречніше, ніж зараз.</p>',
	 '<h2>Телефон работает, а выглядит уставшим</h2><p>Xiaomi Redmi Note 8 Pro вышел в 2019 году, и немалая часть этих аппаратов до сих пор в ежедневной работе. Батарея уже не та, память забита, но телефон звонит, снимает и показывает. Менять незачем, кроме одного: выглядит он ровно на свои годы.</p><p>И вот здесь возникает момент, который многих удивляет. Вид телефона определяет прежде всего чехол, а не сам корпус.</p><h3>Что именно старит аппарат</h3><p>Не царапины на рамке, которых никто, кроме владельца, не видит. Старит чехол, переживший несколько лет: растянутый, с вытертым рисунком, потемневший по краям, с заломленным углом. Рядом с ним любой телефон выглядит вещью, которую донашивают.</p><p>Свежий силикон со своим принтом даёт эффект новых шнурков на старых ботинках — непропорционально большую перемену при минимуме действий.</p><h3>Чего ждать не стоит</h3><p>Чехол не сделает телефон быстрее и не добавит часов автономности. Он меняет только то, что видите вы и окружающие. Но именно поэтому возражение «зачем вкладываться в старый телефон» здесь не срабатывает: вложение минимальное и не требует, чтобы аппарат прожил ещё два года ради окупаемости.</p><p>Сравните с ремонтом экрана или заменой батареи — решениями, после которых телефон действительно обязан прослужить долго. Тут такого обязательства нет вовсе.</p><h3>Что печатают на такие модели</h3><p>Наблюдение из заказов: владельцы старых аппаратов реже берут нейтральные сюжеты. Телефон уже не новый, страха испортить заводской вид нет — и люди позволяют себе яркое. Любимый фильм, музыка, кадр, который давно хотелось напечатать, но «жалко было на новый».</p><p>Отдельная категория владельцев держит этот аппарат сознательно. Не из-за нехватки средств, а потому что всё устраивает: размер привычный, всё работает, а новый телефон означает перенос данных, новые привычки и новые траты. Для таких людей чехол — единственное, что вообще имеет смысл обновлять, и выбирают они его тщательнее владельцев свежих моделей.</p><p>Ещё деталь именно для Сяоми Редми Ноут 8 Про: модель давняя, и в магазинах под неё остались в основном прозрачные и чёрные остатки. Выбор из двух вариантов — это не выбор, так что печать закрывает вопрос окончательно.</p><p>А если аппарат всё же соберётесь менять, он, скорее всего, никуда не денется: станет вторым номером, телефоном для дачи или перейдёт кому-то из родни. Чехол поедет вместе с ним — и в этой второй жизни будет смотреться даже уместнее, чем сейчас.</p>',
	 NULL, NULL, 1);

-- zte-nubia-v60 — кут: увесь макет збирається просто в телефоні, порядок дій
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-zte-nubia-v60', 'template',
	 'Чохол з фото на замовлення для ZTE Nubia V60', 'Чехол с фото на заказ для ZTE Nubia V60',
	 'Чохол з фото для ZTE Nubia V60 — друк на замовлення | FLOY', 'Чехол с фото для ZTE Nubia V60 — печать на заказ | FLOY',
	 'Друк власного макета на чохлі для ZTE Nubia V60. Конструктор працює просто в телефоні — розповідаємо порядок дій, який економить час.',
	 'Печать своего макета на чехле для ZTE Nubia V60. Конструктор работает прямо в телефоне — рассказываем порядок действий, который экономит время.',
	 '<h2>Усе робиться з того самого телефона</h2><p>Уявлення, ніби для друку потрібен комп&#39;ютер, графічний редактор і хоч якесь уміння, — головна причина, чому люди відкладають замовлення на потім. Насправді конструктор відкривається в браузері телефона, а фотографії, які ви збираєтесь друкувати, лежать у ньому ж.</p><p>Тобто весь шлях від ідеї до готового макета для ZTE Nubia V60 проходить в одному пристрої, не встаючи з дивана.</p><h3>Порядок, який економить час</h3><p>Найшвидше виходить, коли робити в такій послідовності:</p><ul><li>спершу колір фону — він задає настрій усьому іншому;</li><li>потім головне зображення, одразу в потрібному масштабі;</li><li>далі напис, якщо він узагалі потрібен;</li><li>і тільки наприкінці — дрібні правки положення.</li></ul><p>Зворотний порядок, коли фон підбирають в останню чергу, зазвичай закінчується тим, що доводиться пересувати все заново. Колір під фотографією змінює її сприйняття настільки, що вже зібрана композиція перестає працювати.</p><h3>Дві дрібниці, помітні лише на телефоні</h3><p>Перша: екран невеликий, і макет на ньому виглядає щільнішим, ніж вийде насправді. Те, що на екрані здається великим написом, на чохлі буде помірним. Тому в сумнівах беріть кегль трохи більший, ніж хочеться.</p><p>Друга: яскравість. Якщо ви збираєте макет увечері з приглушеним екраном, кольори здаються глухішими, ніж вони є. Виведіть яскравість на максимум перед тим, як приймати рішення про фон.</p><p>І порада, яка коштує нуль: не намагайтесь довести все за один підхід. Зберіть варіант, відкладіть телефон на годину й гляньте знову. Око за цей час скидається, і половина потрібних правок стає очевидною.</p><p>Найдовший етап тут не збірка, а вибір знімка, і його теж можна скоротити. Відберіть три кандидати ще до того, як відкриєте конструктор, — просто позначте їх окремим альбомом. Далі кожен по черзі підставляєте у прев&#39;ю й дивитесь. Порівняти три готові варіанти швидше, ніж пригадувати, що там ще лежало в галереї.</p><h3>Головна перевага мобільного шляху</h3><p>Телефон, для якого ви робите чохол, лежить у вас у руці. Прев&#39;ю можна щохвилини звіряти з реальним апаратом: де в нього блок камер, куди припадає центр спинки, як лягає долоня й що саме закривають пальці. З комп&#39;ютера все це доводиться тримати в голові.</p><p>Разом виходить хвилин десять, і більша частина з них — вибір фотографії. Для ЗТЕ Нубія В60 це весь процес: без редакторів, без збереження файлів і без пересилань самому собі поштою.</p>',
	 '<h2>Всё делается с того же телефона</h2><p>Представление, будто для печати нужен компьютер, графический редактор и хоть какое-то умение, — главная причина, по которой заказ откладывают на потом. На деле конструктор открывается в браузере телефона, а фотографии, которые вы собираетесь печатать, лежат в нём же.</p><p>То есть весь путь от идеи до готового макета для ZTE Nubia V60 проходит в одном устройстве, не вставая с дивана.</p><h3>Порядок, который экономит время</h3><p>Быстрее всего получается в такой последовательности:</p><ul><li>сначала цвет фона — он задаёт настроение всему остальному;</li><li>потом главное изображение, сразу в нужном масштабе;</li><li>дальше надпись, если она вообще нужна;</li><li>и только в конце — мелкие правки положения.</li></ul><p>Обратный порядок, когда фон подбирают в последнюю очередь, обычно заканчивается тем, что двигать приходится всё заново. Цвет под фотографией меняет её восприятие настолько, что уже собранная композиция перестаёт работать.</p><h3>Две мелочи, заметные только на телефоне</h3><p>Первая: экран небольшой, и макет на нём выглядит плотнее, чем получится в жизни. То, что на экране кажется крупной надписью, на чехле будет умеренным. Поэтому в сомнениях берите кегль чуть больше, чем хочется.</p><p>Вторая: яркость. Если вы собираете макет вечером с приглушённым экраном, цвета кажутся глуше, чем они есть. Выведите яркость на максимум прежде, чем принимать решение о фоне.</p><p>И совет, который стоит ноль: не пытайтесь довести всё за один подход. Соберите вариант, отложите телефон на час и взгляните снова. Глаз за это время сбрасывается, и половина нужных правок становится очевидной.</p><p>Самый долгий этап здесь не сборка, а выбор снимка, и его тоже можно сократить. Отберите трёх кандидатов ещё до того, как откроете конструктор, — просто пометьте их отдельным альбомом. Дальше каждый по очереди подставляете в превью и смотрите. Сравнить три готовых варианта быстрее, чем вспоминать, что там ещё лежало в галерее.</p><h3>Главное преимущество мобильного пути</h3><p>Телефон, для которого вы делаете чехол, лежит у вас в руке. Превью можно ежеминутно сверять с реальным аппаратом: где у него блок камер, куда приходится центр спинки, как ложится ладонь и что именно закрывают пальцы. С компьютера всё это приходится держать в голове.</p><p>В сумме выходит минут десять, и большая их часть — выбор фотографии. Для ЗТЕ Нубия В60 это весь процесс: без редакторов, без сохранения файлов и без пересылок самому себе по почте.</p>',
	 NULL, NULL, 1);

-- iphone-xi-pro — кут: компактний корпус, мало площі — один сильний елемент
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-iphone-xi-pro', 'template',
	 'Чохол з фото на замовлення для iPhone 11 Pro', 'Чехол с фото на заказ для iPhone 11 Pro',
	 'Чохол з фото для iPhone 11 Pro — друк на замовлення | FLOY', 'Чехол с фото для iPhone 11 Pro — печать на заказ | FLOY',
	 'Свій принт на чохлі для iPhone 11 Pro. Корпус компактний, місця небагато — розбираємо, чому тут виграє один великий елемент замість трьох дрібних.',
	 'Свой принт на чехле для iPhone 11 Pro. Корпус компактный, места немного — разбираем, почему здесь выигрывает один крупный элемент вместо трёх мелких.',
	 '<h2>Менше площі — менше елементів</h2><p>iPhone 11 Pro — один із найкомпактніших смартфонів останніх років. Він зручно лежить у долоні й не стирчить із кишені, але для макета це означає рівно одне: місця небагато, і кожен зайвий елемент помітний.</p><p>Порівняно з великими моделями різниця відчутна. Те, що на широкій спинці читається як композиція з трьох частин, тут перетворюється на тісноту.</p><h3>Одне головне й нічого більше</h3><p>Правило для компактного корпусу просте: один сильний елемент. Одне фото. Або одне слово. Або одна форма. Спроба поєднати фотографію, напис і візерунок закінчується тим, що жодне з трьох не встигає прозвучати.</p><p>Якщо без тексту не обійтись, робіть його частиною зображення, а не окремим шаром: підпис уздовж нижнього краю, ініціали в кутку, дата дрібно під фотографією. Небагато, зате цілісно.</p><h3>Масштаб важливіший за деталі</h3><p>На маленькій спинці виграє великий план. Обличчя, а не людина в повний зріст. Одна квітка, а не букет. Морда кота, а не кіт на дивані. Загальні плани тут не працюють узагалі: деталі, які добре читались на екрані, на площі завбільшки з долоню просто зникають.</p><p>З квадратним блоком камер у верхньому лівому куті теж треба рахуватися. У iPhone 11 Pro він займає помітну частку й без того невеликої спинки, тож центр композиції варто зміщувати нижче — приблизно на середину або трохи під неї.</p><h3>Чому компактні виграють від однотонного</h3><p>Ще одне спостереження. На великому апараті суцільна заливка іноді виглядає порожньою, і її хочеться чимось доповнити. На маленькому все навпаки: щільний однорідний колір робить телефон зібраним і навіть трохи зменшує його візуально.</p><p>Тому для Айфон 11 Про однотонний чохол із дрібним знаком чи монограмою — не компроміс через брак ідей, а найвиграшніший варіант із можливих. Особливо якщо телефон обрали саме за компактність: великий строкатий принт цю рису з&#39;їдає.</p><p>Є в малої площі й приємний бік: макет збирається швидше. Вибирати доводиться менше, пересувати теж — один елемент або стоїть правильно, або ні, і видно це одразу. Ті, хто робив чохли і на великий апарат, і на компактний, зазвичай кажуть, що з другим справляються вдвічі швидше.</p><p>Перевірка, яка займає секунду: зменште прев&#39;ю на екрані до розміру сірникової коробки. Якщо й у такому вигляді видно, що зображено, — макет підходить під компактний корпус. Якщо перетворилось на плутанину, приберіть половину елементів і збільште те, що лишилось.</p>',
	 '<h2>Меньше площади — меньше элементов</h2><p>iPhone 11 Pro — один из самых компактных смартфонов последних лет. Он удобно лежит в ладони и не торчит из кармана, но для макета это означает ровно одно: места немного, и каждый лишний элемент заметен.</p><p>По сравнению с крупными моделями разница ощутимая. То, что на широкой спинке читается как композиция из трёх частей, здесь превращается в тесноту.</p><h3>Одно главное и ничего больше</h3><p>Правило для компактного корпуса простое: один сильный элемент. Одно фото. Или одно слово. Или одна форма. Попытка соединить фотографию, надпись и узор заканчивается тем, что ни одно из трёх не успевает прозвучать.</p><p>Если без текста не обойтись, делайте его частью изображения, а не отдельным слоем: подпись вдоль нижнего края, инициалы в углу, дата мелко под фотографией. Немного, зато цельно.</p><h3>Масштаб важнее деталей</h3><p>На маленькой спинке выигрывает крупный план. Лицо, а не человек в полный рост. Один цветок, а не букет. Морда кота, а не кот на диване. Общие планы здесь не работают вовсе: детали, хорошо читавшиеся на экране, на площади размером с ладонь просто исчезают.</p><p>С квадратным блоком камер в верхнем левом углу тоже надо считаться. У iPhone 11 Pro он занимает заметную долю и без того небольшой спинки, так что центр композиции стоит смещать ниже — примерно на середину или чуть под неё.</p><h3>Почему компактные выигрывают от однотонного</h3><p>Ещё наблюдение. На крупном аппарате сплошная заливка иногда смотрится пустой, и её хочется чем-нибудь дополнить. На маленьком наоборот: плотный однородный цвет делает телефон собранным и даже немного уменьшает его визуально.</p><p>Поэтому для Айфон 11 Про однотонный чехол с мелким знаком или монограммой — не компромисс от нехватки идей, а самый выигрышный из возможных вариантов. Особенно если телефон выбирали именно за компактность: крупный пёстрый принт эту черту съедает.</p><p>Есть у малой площади и приятная сторона: макет собирается быстрее. Выбирать приходится меньше, двигать тоже — один элемент либо стоит верно, либо нет, и видно это сразу. Те, кто делал чехлы и на крупный аппарат, и на компактный, обычно говорят, что со вторым справляются вдвое быстрее.</p><p>Проверка, занимающая секунду: уменьшите превью на экране до размера спичечного коробка. Если и в таком виде понятно, что изображено, — макет подходит под компактный корпус. Превратилось в путаницу — уберите половину элементов и увеличьте то, что осталось.</p>',
	 NULL, NULL, 1);

-- iphone-12-pro — кут: макет із полями і рамкою замість заливки до країв
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-iphone-12-pro', 'template',
	 'Чохол з фото на замовлення для iPhone 12 Pro', 'Чехол с фото на заказ для iPhone 12 Pro',
	 'Чохол з фото для iPhone 12 Pro — друк на замовлення | FLOY', 'Чехол с фото для iPhone 12 Pro — печать на заказ | FLOY',
	 'Фото на чохлі для iPhone 12 Pro. Зображення можна не заливати до країв — три схеми з полями, які виглядають акуратніше за суцільний принт.',
	 'Фото на чехле для iPhone 12 Pro. Изображение можно не заливать до краёв — три схемы с полями, которые выглядят аккуратнее сплошного принта.',
	 '<h2>Принт не обов&#39;язково заливати до країв</h2><p>За замовчуванням усі роблять однаково: фотографія на всю спинку, край у край. Це не єдиний шлях і часто не найкращий. Зображення з полями, коли навколо нього лишається рамка фону, виглядає спокійніше й акуратніше, а на iPhone 12 Pro із його прямими гранями ще й природніше.</p><p>Причина в тому, що телефон дванадцятої серії сам побудований на прямих лініях і чітких кутах. Рамка в макеті продовжує цю логіку, а фото, зрізане по краю, з нею сперечається.</p><h3>Три робочі схеми з полями</h3><p><strong>Рівна рамка.</strong> Однакове поле з усіх боків, приблизно в палець завширшки. Фотографія виглядає як картина в паспарту, і майже будь-який кадр від цього виграє.</p><p><strong>Поле знизу.</strong> Зверху й з боків зображення доходить до краю, а внизу лишається смуга фону — місце для імені, дати чи короткого рядка. Класична поліграфічна схема, працює завжди.</p><p><strong>Квадрат по центру.</strong> Квадратний кадр посередині, фон навколо. Зручно для знімків із соцмереж, які вже квадратні, і для портретів, де нічого зайвого в кадрі немає.</p><h3>Який колір давати полю</h3><p>Найбезпечніше — узяти колір із самої фотографії, тільки помітно темніший або світліший за її середній тон. Білі поля добре виглядають зі світлими знімками й погано з темними, чорні — навпаки. Яскраві кольори в рамці не працюють майже ніколи: вони перетягують увагу з того, що всередині.</p><p>Ширину поля робіть помітною. Тонка смужка в міліметр читається як помилка друку, а не як задум. Якщо вже рамка — то така, щоб її було видно з першого погляду.</p><h3>Коли поля не потрібні</h3><p>Є випадки, де заливка до країв сильніша: суцільні текстури, небо, вода, абстракції — усе без чіткого сюжету. Там рамка тільки обмежує. І навпаки, портрети, предмети, архітектура й старі фотографії від полів майже завжди виграють.</p><p>Є в полів і суто фізичне пояснення. Силіконовий чохол має бортик, який загинається на грані телефона, і зображення, залите до самих країв, частково йде на цей загин. З полем такого не стається: сюжет цілком лишається на площині, яку видно фронтально, а на бортик іде спокійний фон.</p><p>Ще один аргумент саме для Айфон 12 Про: блок камер у верхньому куті. Коли зображення має поле, воно природно тримається далі від модуля, і питання «а чи не зріже це половину обличчя» знімається саме собою — без підганяння макета на міліметри.</p>',
	 '<h2>Принт не обязан заливать спинку до краёв</h2><p>По умолчанию все делают одинаково: фотография во всю спинку, край в край. Это не единственный путь и часто не лучший. Изображение с полями, когда вокруг него остаётся рамка фона, выглядит спокойнее и аккуратнее, а на iPhone 12 Pro с его прямыми гранями ещё и естественнее.</p><p>Причина в том, что телефон двенадцатой серии сам построен на прямых линиях и чётких углах. Рамка в макете продолжает эту логику, а фото, срезанное по краю, с ней спорит.</p><h3>Три рабочие схемы с полями</h3><p><strong>Ровная рамка.</strong> Одинаковое поле со всех сторон, шириной примерно в палец. Фотография смотрится картиной в паспарту, и почти любой кадр от этого выигрывает.</p><p><strong>Поле снизу.</strong> Сверху и по бокам изображение доходит до края, а внизу остаётся полоса фона — место для имени, даты или короткой строки. Классическая полиграфическая схема, работает всегда.</p><p><strong>Квадрат по центру.</strong> Квадратный кадр посередине, фон вокруг. Удобно для снимков из соцсетей, которые уже квадратные, и для портретов, где ничего лишнего в кадре нет.</p><h3>Какой цвет давать полю</h3><p>Безопаснее всего взять цвет из самой фотографии, только заметно темнее или светлее её среднего тона. Белые поля хороши со светлыми снимками и плохи с тёмными, чёрные — наоборот. Яркие цвета в рамке не работают почти никогда: они перетягивают внимание с того, что внутри.</p><p>Ширину поля делайте заметной. Тонкая полоска в миллиметр читается как ошибка печати, а не как замысел. Уж если рамка — то такая, чтобы её было видно с первого взгляда.</p><h3>Когда поля не нужны</h3><p>Есть случаи, где заливка до краёв сильнее: сплошные текстуры, небо, вода, абстракции — всё без чёткого сюжета. Там рамка только ограничивает. И наоборот, портреты, предметы, архитектура и старые фотографии от полей почти всегда выигрывают.</p><p>У полей есть и чисто физическое объяснение. У силиконового чехла есть бортик, загибающийся на грань телефона, и изображение, залитое до самых краёв, частично уходит на этот загиб. С полем такого не происходит: сюжет целиком остаётся на плоскости, которую видно фронтально, а на бортик уходит спокойный фон.</p><p>Ещё довод именно для Айфон 12 Про: блок камер в верхнем углу. Когда у изображения есть поле, оно естественным образом держится дальше от модуля, и вопрос «не срежет ли это половину лица» снимается сам собой — без подгонки макета по миллиметрам.</p>',
	 NULL, NULL, 1);

-- oppo-a3 — кут: чохол про місце (фото, мапа, координати, силует)
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-oppo-a3', 'template',
	 'Чохол з фото на замовлення для OPPO A3', 'Чехол с фото на заказ для OPPO A3',
	 'Чохол з фото для OPPO A3 — друк на замовлення | FLOY', 'Чехол с фото для OPPO A3 — печать на заказ | FLOY',
	 'Друк на чохлі для OPPO A3. Чохол про місце: фотографія, фрагмент мапи, координати або силует міста — чотири способи забрати його з собою.',
	 'Печать на чехле для OPPO A3. Чехол о месте: фотография, фрагмент карты, координаты или силуэт города — четыре способа забрать его с собой.',
	 '<h2>Місце, до якого хочеться повертатись</h2><p>Люди на чохлах трапляються часто, тварини теж. А от місце — рідше, хоча важить воно нерідко не менше. Село, де минуло дитинство. Місто, у яке переїхали. Гори, куди їздите щоліта. Вулиця, на якій живе людина, за якою сумуєте.</p><p>Такий чохол не потребує пояснень стороннім і при цьому щодня нагадує вам про конкретну точку на карті.</p><h3>Чотири способи показати місце</h3><ul><li><strong>Фотографія.</strong> Найпростіше, але потрібен кадр із однією великою формою: гора, міст, вежа, лінія берега. Загальний вид з оглядового майданчика на спинці розсипається.</li><li><strong>Мапа.</strong> Фрагмент карти з кварталом чи дорогою виглядає графічно й миттєво впізнається тим, хто там жив.</li><li><strong>Координати.</strong> Два рядки цифр дрібним шрифтом на однотонному фоні. Для сторонніх — просто цифри.</li><li><strong>Силует.</strong> Обрис міста або гірського хребта одним кольором — найлаконічніший варіант із чотирьох.</li></ul><h3>Що додає точності</h3><p>Назва населеного пункту невеликим шрифтом підсилює будь-який із цих варіантів. Писати її варто так, як говорять місцеві, а не як в офіційних документах. Різниця дрібна, а відчуття зовсім інше.</p><p>Дата теж працює: рік переїзду, рік першої поїздки, рік, коли ви там жили. Одне число під зображенням додає історії більше, ніж довгий підпис.</p><h3>Кому це заходить найкраще</h3><p>Тим, хто виїхав. Тим, хто повернувся. Тим, хто щороку їздить в одне й те саме місце й возить звідти схожі фотографії. І тим, у кого є регулярний маршрут, — тоді на чохлі опиняється не точка, а лінія.</p><p>OPPO A3 часто беруть у дорогу як основний телефон, і саме в дорозі такий чохол найдоречніший. Із ним ви везете з собою не сувенір із крамниці біля вокзалу, а місце, яке справді ваше.</p><p>Якщо важливих місць два, не змішуйте їх в одному кадрі. Простіше поділити спинку по горизонталі: угорі одне, внизу друге, між ними тонка лінія. Так найчастіше роблять ті, хто виріс в одному місті, а живе в іншому, — і на чохлі опиняються обидва, не сперечаючись між собою.</p><p>Якщо вагаєтесь між фотографією й картою, є проста підказка. Фото передає, як там виглядає; карта — де це. Для рідного міста зазвичай сильніше друге, для місця відпочинку — перше. Сам макет для ОППО А3 збирається за кілька хвилин, а от вибір між цими двома підходами забирає значно більше часу — і саме він тут головний.</p>',
	 '<h2>Место, куда хочется возвращаться</h2><p>Люди на чехлах встречаются часто, животные тоже. А вот место — реже, хотя весит оно нередко не меньше. Село, где прошло детство. Город, в который переехали. Горы, куда ездите каждое лето. Улица, на которой живёт человек, по которому скучаете.</p><p>Такой чехол не требует объяснений посторонним и при этом каждый день напоминает вам о конкретной точке на карте.</p><h3>Четыре способа показать место</h3><ul><li><strong>Фотография.</strong> Проще всего, но нужен кадр с одной крупной формой: гора, мост, башня, линия берега. Общий вид со смотровой площадки на спинке рассыпается.</li><li><strong>Карта.</strong> Фрагмент карты с кварталом или дорогой выглядит графично и мгновенно узнаётся тем, кто там жил.</li><li><strong>Координаты.</strong> Две строки цифр мелким шрифтом на однотонном фоне. Для посторонних — просто цифры.</li><li><strong>Силуэт.</strong> Очертания города или горного хребта одним цветом — самый лаконичный вариант из четырёх.</li></ul><h3>Что добавляет точности</h3><p>Название населённого пункта небольшим шрифтом усиливает любой из этих вариантов. Писать его стоит так, как говорят местные, а не как в официальных документах. Разница мелкая, а ощущение совсем другое.</p><p>Дата тоже работает: год переезда, год первой поездки, год, когда вы там жили. Одно число под изображением добавляет истории больше, чем длинная подпись.</p><h3>Кому это заходит лучше всего</h3><p>Тем, кто уехал. Тем, кто вернулся. Тем, кто каждый год ездит в одно и то же место и привозит оттуда похожие фотографии. И тем, у кого есть регулярный маршрут, — тогда на чехле оказывается не точка, а линия.</p><p>OPPO A3 часто берут в дорогу как основной телефон, и как раз в дороге такой чехол уместнее всего. С ним вы везёте с собой не сувенир из лавки у вокзала, а место, которое действительно ваше.</p><p>Если важных мест два, не смешивайте их в одном кадре. Проще разделить спинку по горизонтали: сверху одно, снизу другое, между ними тонкая линия. Так чаще всего поступают те, кто вырос в одном городе, а живёт в другом, — и на чехле оказываются оба, не споря друг с другом.</p><p>Если колеблетесь между фотографией и картой, есть простая подсказка. Фото передаёт, как там выглядит; карта — где это. Для родного города обычно сильнее второе, для места отдыха — первое. Сам макет для ОППО А3 собирается за несколько минут, а вот выбор между этими двумя подходами занимает куда больше — и он здесь главный.</p>',
	 NULL, NULL, 1);

-- oppo-a6 — кут: перші дні з новим телефоном, поки оформлення ще не вирішене
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-oppo-a6', 'template',
	 'Чохол з фото на замовлення для OPPO A6', 'Чехол с фото на заказ для OPPO A6',
	 'Чохол з фото для OPPO A6 — друк на замовлення | FLOY', 'Чехол с фото для OPPO A6 — печать на заказ | FLOY',
	 'Свій принт на чохлі для OPPO A6. Перші дні з новим телефоном — найкращий момент, щоб вирішити, як він виглядатиме наступні роки.',
	 'Свой принт на чехле для OPPO A6. Первые дни с новым телефоном — лучший момент, чтобы решить, как он будет выглядеть ближайшие годы.',
	 '<h2>Поки телефон ще без чохла</h2><p>Перші дні з новим апаратом влаштовані однаково. Плівку зняли, телефон у руках голий, чохла ще немає — або є той тимчасовий прозорий, що йшов у комплекті. І саме в цей момент вирішується, як телефон виглядатиме наступні роки.</p><p>Зазвичай усе закінчується випадковою покупкою: перший-ліпший чохол біля каси, узятий за дві хвилини разом із симкою. OPPO A6 після цього стає схожим на будь-який інший OPPO A6 у місті.</p><h3>Чому саме перші дні</h3><p>Тому що звички ще немає. Через півроку телефон уже «якийсь»: до нього звикли, і міняти оформлення здається зайвим клопотом. А поки апарат новий, будь-яке рішення сприймається як частина його налаштування — як вибір рінгтона чи заставки.</p><p>Є й друга причина. У перші дні ви точно пам&#39;ятаєте, чому саме цей телефон і чому саме зараз: перша робота, переїзд, подарунок, довгоочікувана заміна старого. Оформлення, зроблене в цей момент, зазвичай виявляється осмисленішим за те, яке роблять через рік просто тому, що набрид старий чохол.</p><h3>Що робити, поки чохол у дорозі</h3><p>Цілком нормальна схема: перші дні поносити телефон у тимчасовому прозорому, а тим часом спокійно зібрати макет. Поспіх тут шкодить — макет, зроблений за три хвилини біля вітрини, і макет, обраний за вечір удома, відрізняються помітно.</p><p>Скористайтесь паузою, щоб зробити просту річ: подивіться, які фотографії ви за останній рік відкривали найчастіше. Це і є ваш сюжет. Не той, що красивий, а той, до якого ви й так повертаєтесь без жодного приводу.</p><h3>Три речі, які роблять телефон вашим</h3><p>Заставка, звук дзвінка й чохол. Перші дві змінюються за хвилину й нікому, крім вас, не видні. Третя — єдина, яку бачать усі й яка існує фізично. Дивно, що саме на ній зазвичай зупиняються на варіанті «щось прозоре, аби було». Заставку, до речі, міняють щомісяця, а чохол лишають той, що дістався випадково.</p><p>І спостереження наостанок. Ті, хто зробив друкований чохол одразу з новим телефоном, рідше повертаються до магазинних. Після власного оформлення чужий малюнок на спинці починає здаватись чимось випадковим — річ ніби ваша, а вигляд у неї нічий.</p><p>ОППО А6 у цьому нічим не особливий. Саме тому й має сенс почати з нього так, як хочеться вам, а не так, як склалось випадково біля каси.</p>',
	 '<h2>Пока телефон ещё без чехла</h2><p>Первые дни с новым аппаратом устроены одинаково. Плёнку сняли, телефон в руках голый, чехла ещё нет — или есть тот временный прозрачный, что шёл в комплекте. И как раз в этот момент решается, как телефон будет выглядеть ближайшие годы.</p><p>Обычно всё заканчивается случайной покупкой: первый попавшийся чехол у кассы, взятый за две минуты вместе с симкой. OPPO A6 после этого становится похож на любой другой OPPO A6 в городе.</p><h3>Почему именно первые дни</h3><p>Потому что привычки ещё нет. Через полгода телефон уже «какой-то»: к нему привыкли, и менять оформление кажется лишней возёй. А пока аппарат новый, любое решение воспринимается как часть его настройки — вроде выбора рингтона или обоев.</p><p>Есть и вторая причина. В первые дни вы точно помните, почему именно этот телефон и почему именно сейчас: первая работа, переезд, подарок, долгожданная замена старого. Оформление, сделанное в этот момент, обычно выходит осмысленнее того, которое делают через год просто потому, что надоел прежний чехол.</p><h3>Что делать, пока чехол в пути</h3><p>Вполне рабочая схема: первые дни поносить телефон во временном прозрачном, а тем временем спокойно собрать макет. Спешка здесь вредит — макет, сделанный за три минуты у витрины, и макет, выбранный за вечер дома, отличаются заметно.</p><p>Воспользуйтесь паузой для простого дела: посмотрите, какие фотографии вы за последний год открывали чаще всего. Это и есть ваш сюжет. Не тот, что красив, а тот, к которому вы и так возвращаетесь без всякого повода.</p><h3>Три вещи, которые делают телефон вашим</h3><p>Обои, звук звонка и чехол. Первые две меняются за минуту и никому, кроме вас, не видны. Третья — единственная, которую видят все и которая существует физически. Странно, что именно на ней обычно останавливаются на варианте «что-нибудь прозрачное, лишь бы было». Обои, кстати, меняют ежемесячно, а чехол оставляют тот, что достался случайно.</p><p>И наблюдение напоследок. Те, кто сделал печатный чехол сразу с новым телефоном, реже возвращаются к магазинным. После собственного оформления чужой рисунок на спинке начинает казаться чем-то случайным — вещь вроде ваша, а вид у неё ничей.</p><p>OPPO A6 в этом ничем не особенный. Именно поэтому и есть смысл начать с него так, как хочется вам, а не так, как сложилось случайно у кассы.</p>',
	 NULL, NULL, 1);

