-- oppo-reno13 — кут: графічний макет без жодної фотографії
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-oppo-reno13', 'template',
	 'Чохол з фото на замовлення для OPPO Reno13', 'Чехол с фото на заказ для OPPO Reno13',
	 'Чохол з принтом для OPPO Reno13 — друк на замовлення | FLOY', 'Чехол с принтом для OPPO Reno13 — печать на заказ | FLOY',
	 'Друк власного макета на чохлі для OPPO Reno13. Графіка без фотографії: смуги, коло, діагональ, патерн — кілька схем, які виглядають дорого.',
	 'Печать своего макета на чехле для OPPO Reno13. Графика без фотографии: полосы, круг, диагональ, паттерн — несколько схем, которые выглядят дорого.',
	 '<h2>Макет, у якому немає жодної фотографії</h2><p>Більшість замовлень починається з питання «яке фото поставити». Але є цілий напрямок, де фотографії немає взагалі: чиста графіка. Смуги, кола, сітка, градієнт, повторюваний елемент, велика літера. На силіконі це виглядає зовсім інакше за друковане фото — щільніше й навмисніше.</p><p>OPPO Reno13 для такого підходить особливо добре. Серію Reno роблять із прицілом на зовнішність, і покупці в неї відповідні: людині, яка обрала телефон за вигляд, графічний чохол зазвичай ближчий, ніж родинний портрет на всю спинку.</p><h3>Схеми, які працюють майже завжди</h3><ul><li><strong>Дві-три горизонтальні смуги</strong> різної ширини. Найпростіше й найстійкіше: жодна смуга не має дорівнювати іншій.</li><li><strong>Діагональ.</strong> Одна лінія, що ділить спинку під кутом, і два кольори по боках. Виглядає динамічно навіть без нічого більше.</li><li><strong>Велике коло.</strong> По центру або трохи зміщене вниз — тоді композиція перестає бути симетричною й одразу оживає.</li><li><strong>Повторюваний елемент.</strong> Один знак, розмножений сіткою. Головне — робити його достатньо великим: дрібний патерн зливається в текстуру.</li><li><strong>Одна велика літера</strong> на всю висоту, зрізана краями. Ініціал, який читається не одразу, — і саме тому цікавий.</li></ul><h3>Скільки кольорів брати</h3><p>Два. У крайньому разі три, де третій — тонка деталь. Графіка прощає багато, але не строкатість: чотири рівноправні кольори перетворюють макет на дитячий конструктор.</p><p>Найнадійніші пари — темний із теплим світлим і два сусідні відтінки одного кольору з великою різницею в яскравості. Найризикованіші — два насичені кольори однакової темноти: на межі вони починають вібрувати й стомлюють око.</p><h3>Чому це зручніше за фото</h3><p>Графічний макет не залежить від того, що лежить у галереї. Його не треба шукати, він не застаріває й не прив&#39;язаний до конкретної людини чи події. Через рік він виглядає так само, як у день замовлення.</p><p>Є й практичний бонус: у такому макеті легко обійти блок камер. Ви самі вирішуєте, де проходить лінія й де стоїть коло, — нічого не доводиться зсувати чи обрізати, як буває з фотографією.</p><p>Якщо хочеться, щоб макет усе ж був особистим, додайте одну малу деталь: ініціали в кутку, рік дрібним рядком, дві цифри дати. Геометрія лишається геометрією, але це вже ваш чохол, а не абстракція з каталогу.</p><p>Для ОППО Рено13 такий підхід особливо доречний. Телефон і без чохла виглядає доглянутим, і графіка його логіку продовжує, а не сперечається з нею.</p>',
	 '<h2>Макет, в котором нет ни одной фотографии</h2><p>Большинство заказов начинается с вопроса «какое фото поставить». Но есть целое направление, где фотографии нет вовсе: чистая графика. Полосы, круги, сетка, градиент, повторяющийся элемент, крупная буква. На силиконе это выглядит совсем иначе, чем напечатанный снимок, — плотнее и намереннее.</p><p>OPPO Reno13 для такого подходит особенно хорошо. Серию Reno делают с прицелом на внешность, и покупатели у неё соответствующие: тому, кто выбрал телефон за вид, графичный чехол обычно ближе семейного портрета во всю спинку.</p><h3>Схемы, которые работают почти всегда</h3><ul><li><strong>Две-три горизонтальные полосы</strong> разной ширины. Проще всего и устойчивее всего: ни одна полоса не должна равняться другой.</li><li><strong>Диагональ.</strong> Одна линия, делящая спинку под углом, и два цвета по сторонам. Смотрится динамично даже без всего остального.</li><li><strong>Крупный круг.</strong> По центру или чуть смещённый вниз — тогда композиция перестаёт быть симметричной и сразу оживает.</li><li><strong>Повторяющийся элемент.</strong> Один знак, размноженный сеткой. Главное — делать его достаточно крупным: мелкий паттерн сливается в текстуру.</li><li><strong>Одна большая буква</strong> во всю высоту, срезанная краями. Инициал, который читается не сразу, — потому и интересен.</li></ul><h3>Сколько цветов брать</h3><p>Два. В крайнем случае три, где третий — тонкая деталь. Графика прощает многое, но не пестроту: четыре равноправных цвета превращают макет в детский конструктор.</p><p>Самые надёжные пары — тёмный с тёплым светлым и два соседних оттенка одного цвета с большой разницей в яркости. Самые рискованные — два насыщенных цвета одинаковой темноты: на границе они начинают вибрировать и утомляют глаз.</p><h3>Чем это удобнее фотографии</h3><p>Графичный макет не зависит от того, что лежит в галерее. Его не нужно искать, он не устаревает и не привязан к конкретному человеку или событию. Через год он выглядит так же, как в день заказа.</p><p>Есть и практический бонус: в таком макете легко обойти блок камер. Вы сами решаете, где проходит линия и где стоит круг, — ничего не приходится сдвигать и обрезать, как бывает с фотографией.</p><p>Если хочется, чтобы макет всё же был личным, добавьте одну небольшую деталь: инициалы в углу, год мелкой строкой, две цифры даты. Геометрия остаётся геометрией, но это уже ваш чехол, а не абстракция из каталога.</p><p>Для ОППО Рено13 такой подход особенно уместен. Телефон и без чехла выглядит ухоженным, и графика его логику продолжает, а не спорит с ней.</p>',
	 NULL, NULL, 1);

-- realme-c71 — кут: колір корпусу під чохлом і як він впливає на світлі ділянки принта
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-realme-c71', 'template',
	 'Чохол з фото на замовлення для Realme C71', 'Чехол с фото на заказ для Realme C71',
	 'Чохол з фото для Realme C71 — друк на замовлення | FLOY', 'Чехол с фото для Realme C71 — печать на заказ | FLOY',
	 'Друк на чохлі для Realme C71. Під чохлом лишається корпус свого кольору — розповідаємо, як це врахувати в макеті й коли це взагалі неважливо.',
	 'Печать на чехле для Realme C71. Под чехлом остаётся корпус своего цвета — рассказываем, как учесть это в макете и когда это вообще неважно.',
	 '<h2>Під чохлом усе одно є телефон</h2><p>Про це рідко думають на етапі макета: чохол не висить у повітрі, під ним корпус конкретного кольору. Чорний, синій, золотистий, білий. І там, де принт світлий або малонасичений, колір апарата дає про себе знати — такі ділянки виглядають трохи інакше, ніж на екрані в конструкторі.</p><p>Realme C71 продають у кількох кольорах, тож перед складанням макета варто спершу згадати, який саме апарат у вас у руках.</p><h3>Темний корпус</h3><p>Найпоширеніший випадок і найпростіший. Темний телефон під чохлом поводиться передбачувано: насичені й темні ділянки принта лишаються собою, а великі світлі площини можуть виглядати трохи глухішими, ніж очікувалось.</p><p>Порада проста: на темному апараті не будуйте макет на ніжних пастельних відтінках. Беріть або щільні кольори, або свідомо приглушену палітру — тоді нічого не попливе.</p><h3>Світлий і кольоровий корпус</h3><p>Зі світлим телефоном усе навпаки: пастель і білі поля виглядають чисто, а глибокий чорний вимагає щільної заливки. Якщо в макеті велика чорна площина, робіть її саме чорною, а не темно-сірою.</p><p>Окремий випадок — яскравий або золотистий корпус. Тут краще не лишати в макеті великих незаповнених ділянок узагалі: будь-яка порожня площа працює на користь апарата, а не вашого зображення.</p><h3>Найпростіше рішення</h3><p>Якщо думати про це не хочеться взагалі, є універсальний вихід: залийте фон повністю. Макет, у якому немає незаповнених ділянок, від кольору корпусу практично не залежить — принт закриває всю площу, і телефон під ним стає неважливим.</p><p>Саме тому суцільний кольоровий фон — найбезпечніший варіант для будь-якої моделі й будь-якого корпусу. У прев&#39;ю ви бачите рівно те, що отримаєте.</p><p>З фотографіями це питання майже не виникає: знімок і так закриває всю площу щільним зображенням. Стосується воно передусім макетів із великими світлими полями — рамками, пастельними фонами, білим простором навколо напису.</p><p>Є й протилежний прийом — узяти колір фону в тон самого апарата. Тоді чохол і корпус читаються як одне ціле, а телефон виглядає так, ніби його випустили саме таким. Для Реалмі С71 це працює добре: у бюджетних моделей кольори зазвичай прості, і повторити їх заливкою нескладно.</p><p>І остання порада. Перш ніж замовляти, покладіть телефон поруч з екраном, на якому відкрите прев&#39;ю. Одразу видно, сперечається макет із корпусом чи продовжує його. Перевірка займає секунду, а помилок після неї стає помітно менше.</p>',
	 '<h2>Под чехлом всё равно есть телефон</h2><p>Об этом редко думают на этапе макета: чехол не висит в воздухе, под ним корпус конкретного цвета. Чёрный, синий, золотистый, белый. И там, где принт светлый или малонасыщенный, цвет аппарата даёт о себе знать — такие участки выглядят чуть иначе, чем на экране в конструкторе.</p><p>Realme C71 продаётся в нескольких цветах, так что перед сборкой макета стоит вспомнить, какой именно аппарат у вас в руках.</p><h3>Тёмный корпус</h3><p>Случай самый распространённый и самый простой. Тёмный телефон под чехлом ведёт себя предсказуемо: насыщенные и тёмные участки принта остаются собой, а большие светлые плоскости могут выглядеть чуть глуше ожидаемого.</p><p>Совет простой: на тёмном аппарате не стройте макет на нежных пастельных оттенках. Берите либо плотные цвета, либо сознательно приглушённую палитру — тогда ничего не поплывёт.</p><h3>Светлый и цветной корпус</h3><p>Со светлым телефоном всё наоборот: пастель и белые поля выглядят чисто, а глубокий чёрный требует плотной заливки. Если в макете большая чёрная плоскость, делайте её именно чёрной, а не тёмно-серой.</p><p>Отдельный случай — яркий или золотистый корпус. Тут лучше не оставлять в макете крупных незаполненных участков вовсе: любая пустая площадь работает на аппарат, а не на ваше изображение.</p><h3>Самое простое решение</h3><p>Если думать об этом не хочется совсем, есть универсальный выход: залейте фон полностью. Макет без незаполненных участков от цвета корпуса практически не зависит — принт закрывает всю площадь, и телефон под ним становится неважен.</p><p>Именно поэтому сплошной цветной фон — самый безопасный вариант для любой модели и любого корпуса. В превью вы видите ровно то, что получите.</p><p>С фотографиями этот вопрос почти не возникает: снимок и так закрывает всю площадь плотным изображением. Касается он прежде всего макетов с большими светлыми полями — рамками, пастельными фонами, белым пространством вокруг надписи.</p><p>Есть и обратный приём — взять цвет фона в тон самому аппарату. Тогда чехол и корпус читаются как одно целое, а телефон выглядит так, будто его выпустили именно таким. Для Реалми С71 это работает хорошо: у бюджетных моделей цвета обычно простые, и повторить их заливкой несложно.</p><p>И последний совет. Перед заказом положите телефон рядом с экраном, на котором открыто превью. Сразу видно, спорит макет с корпусом или продолжает его. Проверка занимает секунду, а ошибок после неё становится заметно меньше.</p>',
	 NULL, NULL, 1);

-- realme-note-70 — кут: телефон для власної справи, чохол як частина сервісу
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-realme-note-70', 'template',
	 'Чохол з фото на замовлення для Realme Note 70', 'Чехол с фото на заказ для Realme Note 70',
	 'Чохол з принтом для Realme Note 70 — друк | FLOY', 'Чехол с принтом для Realme Note 70 — печать | FLOY',
	 'Свій принт на чохлі для Realme Note 70. Якщо телефон працює разом з вами: логотип, назва справи або предмет ремесла замість випадкової картинки.',
	 'Свой принт на чехле для Realme Note 70. Если телефон работает вместе с вами: логотип, название дела или предмет ремесла вместо случайной картинки.',
	 '<h2>Телефон, який працює разом із вами</h2><p>Є ціла категорія власників, для яких телефон — робочий інструмент у прямому сенсі. Майстер манікюру, кондитер, перукар, репетитор, фотограф, майстер із ремонту, людина з невеликою крамницею в соцмережах. Телефон у них у руках цілий день, і його бачать клієнти: на столі, у руці, у момент розрахунку.</p><p>Realme Note 70 у такому сценарії — типовий вибір: недорогий апарат, який не шкода діставати в будь-яких умовах.</p><h3>Що на нього ставлять</h3><p>Не фотографію дітей — її лишають для другого телефона або для заставки. На робочому апараті працює інше:</p><ul><li>власний логотип, навіть якщо він намальований самотужки;</li><li>назва справи одним словом, великим шрифтом;</li><li>предмет ремесла: ножиці, пензлі, торт, фотоапарат, ключі;</li><li>фірмовий колір, якщо він у вас уже є в оформленні сторінки.</li></ul><p>Ефект тут не рекламний, а зовсім інший. Клієнт бачить, що людина ставиться до своєї справи як до справжньої, а не як до тимчасової підробітки. Це зчитується за секунду й без жодних слів.</p><h3>Про що не варто забувати</h3><p>Контактів на чохлі не пишуть. Номер чи адреса на спинці виглядають як оголошення на стовпі, а не як оформлення, і прочитати їх усе одно незручно. Якщо потрібен спосіб зв&#39;язку — це робота візитки, а не чохла.</p><p>Другий момент: не намагайтеся вкласти в макет усе одразу. Логотип, назва, перелік послуг і фірмовий колір разом — це вже афіша. Достатньо одного елемента, який працює як знак.</p><h3>Коли справи ще немає</h3><p>Буває, що людина тільки починає: назви немає, логотипа немає, є лише вміння. Тоді найкраще працює предмет. Фотографія власних інструментів на простому фоні — і телефон уже говорить про вас те, що потрібно.</p><p>Ще один сценарій — команда. Якщо вас двоє чи троє, однакові чохли з одним знаком коштують менше за будь-яку іншу форму фірмового стилю й помітні щодня, а не раз на місяць.</p><p>Є й проста перевірка перед замовленням. Уявіть, що клієнт бачить ваш телефон уперше й нічого про вас не знає. Що він зрозуміє за секунду? Якщо відповідь «нічого» — макет варто спростити: один великий елемент замість трьох дрібних і назва читабельним шрифтом, а не рукописним завитком, який гарний на екрані й нерозбірливий на спинці.</p><p>Зібрати макет для Реалмі Ноут 70 можна за вечір. І на відміну від вивіски чи друкованої продукції, його не страшно змінити, коли справа виросте й оформлення зміниться.</p>',
	 '<h2>Телефон, который работает вместе с вами</h2><p>Есть категория владельцев, для которых телефон — рабочий инструмент в прямом смысле. Мастер маникюра, кондитер, парикмахер, репетитор, фотограф, мастер по ремонту, человек с небольшой лавкой в соцсетях. Телефон у них в руках целый день, и его видят клиенты: на столе, в руке, в момент расчёта.</p><p>Realme Note 70 в таком сценарии — типичный выбор: недорогой аппарат, который не жалко доставать в любых условиях.</p><h3>Что на него ставят</h3><p>Не фотографию детей — её оставляют для второго телефона или для обоев. На рабочем аппарате работает другое:</p><ul><li>собственный логотип, даже если он нарисован своими силами;</li><li>название дела одним словом, крупным шрифтом;</li><li>предмет ремесла: ножницы, кисти, торт, фотоаппарат, ключи;</li><li>фирменный цвет, если он уже есть в оформлении страницы.</li></ul><p>Эффект здесь не рекламный, а совсем другой. Клиент видит, что человек относится к своему делу как к настоящему, а не как к временной подработке. Это считывается за секунду и без единого слова.</p><h3>О чём не стоит забывать</h3><p>Контактов на чехле не пишут. Номер или адрес на спинке выглядят объявлением на столбе, а не оформлением, да и прочитать их всё равно неудобно. Нужен способ связи — это работа визитки, а не чехла.</p><p>Второй момент: не пытайтесь уместить в макет всё сразу. Логотип, название, перечень услуг и фирменный цвет вместе — это уже афиша. Достаточно одного элемента, работающего как знак.</p><h3>Когда дела ещё нет</h3><p>Бывает, что человек только начинает: названия нет, логотипа нет, есть одно умение. Тогда лучше всего работает предмет. Фотография собственных инструментов на простом фоне — и телефон уже говорит о вас то, что нужно.</p><p>Ещё сценарий — команда. Если вас двое или трое, одинаковые чехлы с одним знаком обходятся дешевле любой другой формы фирменного стиля и заметны каждый день, а не раз в месяц.</p><p>Есть и простая проверка перед заказом. Представьте, что клиент видит ваш телефон впервые и ничего о вас не знает. Что он поймёт за секунду? Если ответ «ничего» — макет стоит упростить: один крупный элемент вместо трёх мелких и название читаемым шрифтом, а не рукописным завитком, который хорош на экране и неразборчив на спинке.</p><p>Собрать макет для Реалми Ноут 70 можно за вечер. И в отличие от вывески или печатной продукции, его не страшно поменять, когда дело вырастет и оформление изменится.</p>',
	 NULL, NULL, 1);

-- samsung-galaxy-a15-a155 — кут: чохол як капсула часу, прив&#39;язка до конкретного року
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-samsung-galaxy-a15-a155', 'template',
	 'Чохол з фото на замовлення для Samsung Galaxy A15 (A155)', 'Чехол с фото на заказ для Samsung Galaxy A15 (A155)',
	 'Чохол з фото для Samsung Galaxy A15 — друк | FLOY', 'Чехол с фото для Samsung Galaxy A15 — печать | FLOY',
	 'Фото на чохлі для Samsung Galaxy A15 (A155). Телефон живе два-три роки — і чохол цілком може зафіксувати саме цей період вашого життя.',
	 'Фото на чехле для Samsung Galaxy A15 (A155). Телефон живёт два-три года — и чехол вполне может зафиксировать именно этот период вашей жизни.',
	 '<h2>Чохол, який запам&#39;ятовує рік</h2><p>Телефон живе в середньому два-три роки, чохол — приблизно стільки ж. Виходить, що річ, яку ви зараз оформлюєте, точно збігається з конкретним відрізком вашого життя. Це можна просто прийняти, а можна використати.</p><p>Ідея проста: зробити чохол не «красивим взагалі», а прив&#39;язаним саме до цього року. Через два роки він працюватиме як фотографія в альбомі — тільки та фотографія весь цей час буде у вас у руці.</p><h3>Що саме фіксувати</h3><p>Найкраще працюють речі, які зараз здаються буденними:</p><ul><li>вигляд із вікна квартири, у якій ви живете саме зараз;</li><li>ваш нинішній маршрут — зупинка, поворот, під&#39;їзд;</li><li>дитина цього року, а не «взагалі»: діти змінюються швидше за все;</li><li>рік цифрами, дрібно, десь у кутку;</li><li>те, чим ви зайняті в цей період: книжка, інструмент, форма, навчання.</li></ul><p>Урочисті кадри — весілля, випускний, святкове фото — підходять для цього гірше. Вони й так добре запам&#39;ятовуються. А от звичайний вівторок згадати через два роки практично неможливо, і саме тому він цінніший.</p><h3>Samsung Galaxy A15 і його строк</h3><p>Ця модель — телефон із тих, що беруть надовго й без розрахунку швидко змінити. Він переживе кілька версій системи, кілька робіт і, можливо, переїзд. Тобто якраз той горизонт, на якому ідея капсули має сенс.</p><p>Коли телефон урешті поміняють, чохол зазвичай не викидають одразу — він лишається в шухляді. І це найдивніше в цій історії: старі чохли зберігають значно частіше, ніж старі зарядки чи навушники, хоча користі в них уже нуль.</p><h3>Як не переборщити</h3><p>Не треба перетворювати спинку на щоденник. Одного зображення й одного числа достатньо. Дата дрібним шрифтом під фотографією працює краще за будь-який підпис словами, бо не пояснює, а тільки позначає.</p><p>Окремо про те, що з таким чохлом робити потім. Найпростіше — сфотографувати його перед тим, як знімати з телефона. Один кадр у галереї, і період лишається зафіксованим двічі: у речі, яка поїде в шухляду, і в знімку, що переживе будь-який апарат. Дехто робить це системно, і за кілька років набирається дивний, але дуже точний ряд — не облич, а речей, які були з вами щодня.</p><p>І не намагайтеся вибрати «найважливіше». Візьміть те, що просто зараз перед очима: макет для Самсунг Галаксі А15 збирається за кілька хвилин, а через два роки виявиться, що саме ця дрібниця й була тим самим періодом.</p>',
	 '<h2>Чехол, который запоминает год</h2><p>Телефон живёт в среднем два-три года, чехол — примерно столько же. Выходит, что вещь, которую вы сейчас оформляете, точно совпадает с конкретным отрезком вашей жизни. Это можно просто принять, а можно использовать.</p><p>Идея простая: сделать чехол не «красивым вообще», а привязанным именно к этому году. Через два года он сработает как фотография в альбоме — только эта фотография всё время будет у вас в руке.</p><h3>Что именно фиксировать</h3><p>Лучше всего работают вещи, которые сейчас кажутся будничными:</p><ul><li>вид из окна квартиры, в которой вы живёте прямо сейчас;</li><li>ваш нынешний маршрут — остановка, поворот, подъезд;</li><li>ребёнок этого года, а не «вообще»: дети меняются быстрее всего;</li><li>год цифрами, мелко, где-нибудь в углу;</li><li>то, чем вы заняты в этот период: книга, инструмент, форма, учёба.</li></ul><p>Торжественные кадры — свадьба, выпускной, праздничное фото — подходят для этого хуже. Они и так хорошо запоминаются. А вот обычный вторник вспомнить через два года практически невозможно, и потому он ценнее.</p><h3>Samsung Galaxy A15 и его срок</h3><p>Эта модель из тех, что берут надолго и без расчёта быстро сменить. Она переживёт несколько версий системы, несколько работ и, возможно, переезд. То есть ровно тот горизонт, на котором идея капсулы имеет смысл.</p><p>Когда телефон в итоге поменяют, чехол обычно не выбрасывают сразу — он остаётся в ящике. И это самое странное во всей истории: старые чехлы хранят гораздо чаще, чем старые зарядки или наушники, хотя пользы в них уже ноль.</p><h3>Как не переборщить</h3><p>Не нужно превращать спинку в дневник. Одного изображения и одного числа достаточно. Дата мелким шрифтом под фотографией работает лучше любой подписи словами: она не объясняет, а только помечает.</p><p>Отдельно о том, что делать с таким чехлом потом. Проще всего сфотографировать его перед тем, как снимать с телефона. Один кадр в галерее — и период оказывается зафиксирован дважды: в вещи, которая уедет в ящик, и в снимке, переживающем любой аппарат. Кто-то делает это системно, и за несколько лет набирается странный, но очень точный ряд — не лиц, а вещей, бывших с вами каждый день.</p><p>И не пытайтесь выбрать «самое важное». Возьмите то, что прямо сейчас перед глазами: макет для Самсунг Галакси А15 собирается за несколько минут, а через два года окажется, что именно эта мелочь и была тем самым периодом.</p>',
	 NULL, NULL, 1);

-- poco-m4-pro-4g — кут: стара паперова фотографія з альбому на чохлі
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-poco-m4-pro-4g', 'template',
	 'Чохол з фото на замовлення для Xiaomi POCO M4 Pro 4G', 'Чехол с фото на заказ для Xiaomi POCO M4 Pro 4G',
	 'Чохол з фото для Xiaomi POCO M4 Pro 4G — друк | FLOY', 'Чехол с фото для Xiaomi POCO M4 Pro 4G — печать | FLOY',
	 'Друк старої сімейної фотографії на чохлі для Xiaomi POCO M4 Pro 4G. Як зняти картку з альбому, щоб на друку вона виглядала як слід.',
	 'Печать старой семейной фотографии на чехле для Xiaomi POCO M4 Pro 4G. Как снять карточку из альбома, чтобы на печати она выглядела как надо.',
	 '<h2>Фотографія, якої немає в телефоні</h2><p>Найсильніші макети зазвичай робляться не зі свіжих кадрів. Вони робляться зі старих паперових знімків: бабуся молода, батьки на весіллі, ви самі в чотири роки на дерев&#39;яному коні. Такі фотографії існують в одному примірнику й лежать удома в коробці з-під взуття.</p><p>Перенести їх на чохол — питання кількох хвилин. У результаті знімок, який за тридцять років бачили десять людей, опиняється у вас у руці щодня.</p><h3>Як зняти фото з альбому</h3><p>Найчастіша помилка — знімати зі спалахом. Він дає білу пляму рівно посередині й убиває всю картку. Далі за списком:</p><ul><li>світло беріть від вікна, вдень, але не пряме сонце;</li><li>картку кладіть на стіл, а не тримайте в руці;</li><li>камеру тримайте паралельно фотографії, а не під кутом — інакше прямокутник поїде;</li><li>якщо знімок під плівкою в альбомі, дістаньте його: плівка дає відблиски;</li><li>зробіть кілька кадрів з різних боків і виберіть найрівніший.</li></ul><p>Зім&#39;яті кути, подряпини й пожовклість прибирати не обов&#39;язково. На чохлі вони читаються не як дефекти, а як вік — і саме це відрізняє справжню стару картку від сучасної обробки під ретро.</p><h3>Що робити з нею далі</h3><p>Не кожна стара картка підійде, і причина не в її стані. Групові знімки на двадцять облич, зняті здалеку, на чохлі перетворюються на ряд світлих плям — тут потрібен кадр, де людей одна-дві й видно обличчя. Найкраще працюють портрети та домашні фотографії, а не офіційні зйомки на тлі драпірування.</p><p>Старі фотографії майже завжди квадратні або близькі до квадрата, тож заливати ними всю спинку не варто. Природніше поставити кадр по центру з полем навколо — приблизно так, як він лежав би на сторінці альбому.</p><p>Рік знизу дрібним шрифтом додає рівно стільки, скільки потрібно. Ім&#39;я — лише якщо на фотографії конкретна людина і ви хочете, щоб її бачили саме як її.</p><p>Xiaomi POCO M4 Pro 4G — телефон уже не новий, і в цьому є своя рима: стара картка на апараті, який теж має історію, виглядає доречніше, ніж на щойно розпакованому флагмані.</p><p>І окремо про те, чого зазвичай не роблять, а варто. Якщо картка одна, а рідних кілька, зробіть із неї чохли для всіх — сестрі, мамі, дядькові. Кожен отримає ту саму фотографію, яку роками ніхто не бачив. Це найдешевший спосіб роздати сімейний архів на руки, і працює він сильніше за будь-яку розсилку сканів у месенджері.</p>',
	 '<h2>Фотография, которой нет в телефоне</h2><p>Самые сильные макеты обычно делаются не из свежих кадров. Они делаются из старых бумажных снимков: бабушка молодая, родители на свадьбе, вы сами в четыре года на деревянной лошадке. Такие фотографии существуют в одном экземпляре и лежат дома в коробке из-под обуви.</p><p>Перенести их на чехол — дело нескольких минут. В итоге снимок, который за тридцать лет видели человек десять, оказывается у вас в руке каждый день.</p><h3>Как снять фото из альбома</h3><p>Самая частая ошибка — снимать со вспышкой. Она даёт белое пятно ровно посередине и убивает всю карточку. Дальше по списку:</p><ul><li>свет берите от окна, днём, но не прямое солнце;</li><li>карточку кладите на стол, а не держите в руке;</li><li>камеру держите параллельно фотографии, а не под углом — иначе прямоугольник поедет;</li><li>если снимок под плёнкой в альбоме, достаньте его: плёнка даёт блики;</li><li>сделайте несколько кадров с разных сторон и выберите самый ровный.</li></ul><p>Смятые углы, царапины и желтизну убирать не обязательно. На чехле они читаются не как дефекты, а как возраст — и именно это отличает настоящую старую карточку от современной обработки под ретро.</p><h3>Что делать с ней дальше</h3><p>Не всякая старая карточка подойдёт, и причина не в её состоянии. Групповые снимки на двадцать лиц, сделанные издалека, на чехле превращаются в ряд светлых пятен — тут нужен кадр, где людей один-два и лица видно. Лучше всего работают портреты и домашние фотографии, а не официальные съёмки на фоне драпировки.</p><p>Старые фотографии почти всегда квадратные или близкие к квадрату, так что заливать ими всю спинку не стоит. Естественнее поставить кадр по центру с полем вокруг — примерно так, как он лежал бы на странице альбома.</p><p>Год снизу мелким шрифтом добавляет ровно столько, сколько нужно. Имя — только если на фотографии конкретный человек и вы хотите, чтобы его видели именно как его.</p><p>Xiaomi POCO M4 Pro 4G — телефон уже не новый, и в этом есть своя рифма: старая карточка на аппарате, у которого тоже есть история, смотрится уместнее, чем на только что распакованном флагмане.</p><p>И отдельно о том, чего обычно не делают, а стоило бы. Если карточка одна, а родных несколько, сделайте из неё чехлы для всех — сестре, маме, дяде. Каждый получит ту самую фотографию, которую годами никто не видел. Это самый дешёвый способ раздать семейный архив на руки, и работает он сильнее любой рассылки сканов в мессенджере.</p>',
	 NULL, NULL, 1);

-- xiaomi-redmi-13c — кут: текстура як сюжет (дерево, камінь, тканина, бетон)
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-xiaomi-redmi-13c', 'template',
	 'Чохол з фото на замовлення для Xiaomi Redmi 13C', 'Чехол с фото на заказ для Xiaomi Redmi 13C',
	 'Чохол з принтом для Xiaomi Redmi 13C — друк | FLOY', 'Чехол с принтом для Xiaomi Redmi 13C — печать | FLOY',
	 'Принт на чохлі для Xiaomi Redmi 13C. Текстура замість картинки: дерево, камінь, тканина, бетон — і чому тут головне правильний масштаб.',
	 'Принт на чехле для Xiaomi Redmi 13C. Текстура вместо картинки: дерево, камень, ткань, бетон — и почему здесь главное правильный масштаб.',
	 '<h2>Коли сюжет — це поверхня</h2><p>Є категорія макетів, у яких немає ні людей, ні тварин, ні написів. Тільки поверхня: дерево, камінь, бетон, тканина, шкіра, іржавий метал, лід. Здалеку такий чохол не читається як надрукована картинка — він виглядає так, ніби зроблений із цього матеріалу.</p><p>Xiaomi Redmi 13C — модель масова, її бачать десятками щодня, і саме тому текстура на ній працює краще за черговий яскравий принт: телефон перестає впізнаватись як бюджетний апарат у строкатому чохлі.</p><h3>Які поверхні виглядають найкраще</h3><ul><li><strong>Дерево.</strong> Дошка з видимими кільцями або зріз — теплий і спокійний варіант, один із найпопулярніших.</li><li><strong>Камінь.</strong> Мармур, граніт, звичайний сірий валун. Головне — брати великий масштаб, а не дрібну крихту.</li><li><strong>Тканина.</strong> Груба льняна, джинсова, вовна, в&#39;язка. Виглядає майже тактильно.</li><li><strong>Бетон і штукатурка.</strong> Строгий міський варіант, добре тримає напис зверху.</li><li><strong>Вода й лід.</strong> Найживіші з усіх, але потребують контрасту, інакше перетворюються на сіру пляму.</li></ul><h3>Головне правило — масштаб</h3><p>Текстура працює тоді, коли її елементи великі. Дрібний малюнок на площі завбільшки з долоню перетворюється на шум: око бачить не дерево, а сірувату рябизну.</p><p>Правило приблизно таке: на спинку має вміщатись від трьох до семи великих елементів структури — кілька кілець дерева, кілька прожилок мармуру, кілька складок тканини. Якщо їх сотні, візьміть фрагмент і збільште його.</p><p>Про колір поверхні варто подумати заздалегідь. Світле дерево й білий бетон роблять телефон візуально легшим, темний камінь і мокра дошка — навпаки, важчим і дорожчим на вигляд. Правило те саме, що з одягом: темна поверхня прощає більше, а на світлій помітна кожна деталь макета, включно з тим, як лягає напис.</p><h3>Своя текстура замість чужої</h3><p>Найцікавіше починається, коли поверхню ви знімаєте самі. Стіл, за яким працюєте. Стіна дому в селі. Кора дерева у дворі. Двері майстерні. Для стороннього це просто гарна фактура, для вас — конкретне місце, і ніхто не здогадається, поки ви не скажете.</p><p>Знімати найпростіше при бічному світлі: воно підкреслює рельєф. Пряме світло в лоб робить будь-яку поверхню пласкою, і навіть груба дошка виглядає як шпалери.</p><p>І дрібниця для Сяомі Редмі 13С: текстурний макет добре терпить напис. Одне слово або ініціали світлим кольором поверх дерева чи бетону виглядають саме так, як задумано, — на відміну від фотографії, де текст майже завжди заважає й потребує окремого місця.</p>',
	 '<h2>Когда сюжет — это поверхность</h2><p>Есть категория макетов, где нет ни людей, ни животных, ни надписей. Только поверхность: дерево, камень, бетон, ткань, кожа, ржавый металл, лёд. Издалека такой чехол не читается как напечатанная картинка — он выглядит так, будто сделан из этого материала.</p><p>Xiaomi Redmi 13C — модель массовая, её видят десятками каждый день, и потому текстура на ней работает лучше очередного яркого принта: телефон перестаёт опознаваться как бюджетный аппарат в пёстром чехле.</p><h3>Какие поверхности выглядят лучше всего</h3><ul><li><strong>Дерево.</strong> Доска с видимыми кольцами или спил — тёплый и спокойный вариант, один из самых популярных.</li><li><strong>Камень.</strong> Мрамор, гранит, обычный серый валун. Главное — брать крупный масштаб, а не мелкую крошку.</li><li><strong>Ткань.</strong> Грубый лён, джинса, шерсть, вязка. Выглядит почти тактильно.</li><li><strong>Бетон и штукатурка.</strong> Строгий городской вариант, хорошо держит надпись сверху.</li><li><strong>Вода и лёд.</strong> Самые живые из всех, но требуют контраста, иначе превращаются в серое пятно.</li></ul><h3>Главное правило — масштаб</h3><p>Текстура работает тогда, когда её элементы крупные. Мелкий рисунок на площади размером с ладонь превращается в шум: глаз видит не дерево, а сероватую рябь.</p><p>Правило примерно такое: на спинку должно помещаться от трёх до семи крупных элементов структуры — несколько колец дерева, несколько прожилок мрамора, несколько складок ткани. Если их сотни, возьмите фрагмент и увеличьте его.</p><p>О цвете поверхности стоит подумать заранее. Светлое дерево и белый бетон делают телефон визуально легче, тёмный камень и мокрая доска — наоборот, тяжелее и дороже на вид. Правило то же, что с одеждой: тёмная поверхность прощает больше, а на светлой заметна каждая деталь макета, включая то, как ложится надпись.</p><h3>Своя текстура вместо чужой</h3><p>Самое интересное начинается, когда поверхность вы снимаете сами. Стол, за которым работаете. Стена дома в селе. Кора дерева во дворе. Дверь мастерской. Для постороннего это просто красивая фактура, для вас — конкретное место, и никто не догадается, пока вы не скажете.</p><p>Снимать проще всего при боковом свете: он подчёркивает рельеф. Прямой свет в лоб делает любую поверхность плоской, и даже грубая доска выглядит как обои.</p><p>И мелочь для Сяоми Редми 13С: текстурный макет хорошо терпит надпись. Одно слово или инициалы светлым цветом поверх дерева или бетона выглядят ровно так, как задумано, — в отличие от фотографии, где текст почти всегда мешает и требует отдельного места.</p>',
	 NULL, NULL, 1);

-- iphone-x1-max — кут: телефон сам потрапляє в чужі кадри (дзеркальні селфі, фото на столі)
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-iphone-x1-max', 'template',
	 'Чохол з фото на замовлення для iPhone 11 Pro Max', 'Чехол с фото на заказ для iPhone 11 Pro Max',
	 'Чохол з фото для iPhone 11 Pro Max — друк | FLOY', 'Чехол с фото для iPhone 11 Pro Max — печать | FLOY',
	 'Свій принт на чохлі для iPhone 11 Pro Max. Телефон регулярно потрапляє в чужі кадри — і те, що на його спинці, видно на цих фотографіях.',
	 'Свой принт на чехле для iPhone 11 Pro Max. Телефон регулярно попадает в чужие кадры — и то, что на его спинке, видно на этих фотографиях.',
	 '<h2>Телефон, який сам потрапляє на фотографії</h2><p>Ми знімаємо телефоном тисячі кадрів і майже не думаємо про те, що він і сам регулярно опиняється в кадрі. Дзеркальне селфі — апарат затуляє півобличчя. Фото зі столу в кав&#39;ярні — телефон лежить поруч із чашкою. Груповий знімок, де хтось тримає його в руці. Відеодзвінок, у якому ви піднімаєте телефон і на секунду показуєте спинку.</p><p>iPhone 11 Pro Max тут особливо помітний: він великий, і в будь-якому кадрі його не сплутати з дрібним предметом.</p><h3>Що з цього випливає</h3><p>Порожня чорна спинка на фотографії читається як пляма. Вона забирає місце, нічого не додаючи. Оформлена працює навпаки — як деталь: колір, що підтримує решту кадру, або зображення, яке додає знімку сенсу.</p><p>Найкраще в чужих кадрах поводяться прості речі: один щільний колір, велика форма, контрастна графіка. Дрібні деталі на фотографії все одно не читаються — телефон у кадрі зазвичай завбільшки із сірникову коробку.</p><h3>Дзеркальне селфі й одна пастка</h3><p>У дзеркалі все відображається навпаки. Текст на чохлі в такому кадрі буде дзеркальним і нечитабельним. Це не привід відмовлятись від напису, але знати варто заздалегідь: якщо ви часто знімаєте себе в дзеркалі, надійніше поставити на спинку зображення чи форму, а не слово.</p><p>Друга дрібниця: блискучі поверхні ловлять спалах. Матовий чохол із друком у цьому сенсі спокійніший за глянцевий пластик — відблиску, який засвічує пів телефона, не буде.</p><h3>Кому це важливо</h3><p>Тим, хто веде сторінку або просто знімає багато. Телефон у таких людей потрапляє в кадр по кілька разів на тиждень, і за рік набирається сотня фотографій, де його видно. Чохол тут працює як частина образу — так само, як годинник чи сумка, які теж потрапляють у кадр і теж щось про вас кажуть.</p><p>Для Айфон 11 Про Макс варто врахувати ще й розмір: на фотографії його спинка займає помітну площу, тож обране зображення там буде видно краще, ніж на компактній моделі. Це ще один аргумент за просте й сильне рішення замість дрібного візерунка.</p><p>Перевірити себе легко: знайдіть у галереї три-чотири кадри, де ваш телефон випадково потрапив у поле зору. Подивіться, як він там виглядає зараз. Найчастіше відповідь одна — ніяк, темна пляма без ознак. А тепер уявіть на тому самому місці колір або кадр, який вам подобається: різниця виявляється більшою, ніж здається на словах.</p>',
	 '<h2>Телефон, который сам попадает на фотографии</h2><p>Мы снимаем телефоном тысячи кадров и почти не думаем о том, что он и сам регулярно оказывается в кадре. Зеркальное селфи — аппарат закрывает пол-лица. Фото со стола в кофейне — телефон лежит рядом с чашкой. Групповой снимок, где кто-то держит его в руке. Видеозвонок, в котором вы поднимаете телефон и на секунду показываете спинку.</p><p>iPhone 11 Pro Max здесь особенно заметен: он крупный, и ни с каким мелким предметом его в кадре не спутать.</p><h3>Что из этого следует</h3><p>Пустая чёрная спинка на фотографии читается пятном. Она занимает место, ничего не добавляя. Оформленная работает наоборот — деталью: цветом, поддерживающим остальной кадр, или изображением, которое добавляет снимку смысла.</p><p>Лучше всего в чужих кадрах ведут себя простые вещи: один плотный цвет, крупная форма, контрастная графика. Мелкие детали на фотографии всё равно не читаются — телефон в кадре обычно размером со спичечный коробок.</p><h3>Зеркальное селфи и одна ловушка</h3><p>В зеркале всё отражается наоборот. Текст на чехле в таком кадре будет зеркальным и нечитаемым. Это не повод отказываться от надписи, но знать стоит заранее: если вы часто снимаете себя в зеркале, надёжнее поставить на спинку изображение или форму, а не слово.</p><p>Вторая мелочь: блестящие поверхности ловят вспышку. Матовый чехол с печатью в этом смысле спокойнее глянцевого пластика — блика, засвечивающего пол-телефона, не будет.</p><h3>Кому это важно</h3><p>Тем, кто ведёт страницу или просто много снимает. Телефон у таких людей попадает в кадр по нескольку раз в неделю, и за год набирается сотня фотографий, где он виден. Чехол тут работает частью образа — так же, как часы или сумка, которые тоже попадают в кадр и тоже что-то о вас говорят.</p><p>Для Айфон 11 Про Макс стоит учесть и размер: на фотографии его спинка занимает заметную площадь, так что выбранное изображение там видно лучше, чем на компактной модели. Ещё один довод за простое и сильное решение вместо мелкого узора.</p><p>Проверить себя легко: найдите в галерее три-четыре кадра, где ваш телефон случайно попал в поле зрения. Посмотрите, как он там выглядит сейчас. Чаще всего ответ один — никак, тёмное пятно без признаков. А теперь представьте на том же месте цвет или кадр, который вам нравится: разница оказывается больше, чем кажется на словах.</p>',
	 NULL, NULL, 1);

-- blackview-a100 — кут: другий телефон і те, що на ньому друкують
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-blackview-a100', 'template',
	 'Чохол з фото на замовлення для Blackview A100', 'Чехол с фото на заказ для Blackview A100',
	 'Чохол з фото для Blackview A100 — друк на замовлення | FLOY', 'Чехол с фото для Blackview A100 — печать на заказ | FLOY',
	 'Друк на чохлі для Blackview A100. Другий телефон оформлюють інакше за основний — головне, щоб два апарати не плутались у руках.',
	 'Печать на чехле для Blackview A100. Второй телефон оформляют иначе, чем основной, — главное, чтобы два аппарата не путались в руках.',
	 '<h2>Апарат, який лежить у другій кишені</h2><p>Другий телефон — річ буденніша, ніж здається. Робочий номер окремо від особистого. Апарат для поїздок, на який не шкода. Телефон, що лишається вдома для дитини. Резервний, куди переставляють симку, коли основний у ремонті. Blackview A100 у таких ролях трапляється часто.</p><p>І з оформленням тут інша логіка, ніж із головним телефоном.</p><h3>Головне — щоб їх не плутати</h3><p>Два апарати в одній сумці або на одному столі — це щоденні дрібні помилки: береш не той, дзвониш не з того, шукаєш не в тій кишені. Найпростіше рішення — зробити чохли максимально несхожими. Не просто різними, а контрастними: якщо основний темний, другий світлий. Рука знаходить потрібний ще до того, як ви встигаєте подивитись.</p><p>Це той рідкісний випадок, коли яскравий колір на спинці — питання не смаку, а зручності.</p><h3>Що друкують на другому</h3><p>Спостереження просте: на другому телефоні люди сміливіші. На основному — стриманий кадр, на резервному може бути що завгодно, бо його не дістають на переговорах і не показують клієнтам.</p><p>Часті варіанти: щось смішне, старе фото, яскравий колір, який на головному не наважились би поставити, напис для себе. Другий телефон — майже чернетка, де можна спробувати те, чого давно хотілось, і подивитись, як воно виглядає в житті.</p><h3>Якщо він для когось іншого</h3><p>Окремий сценарій — коли резервний апарат час від часу віддають: дитині в поїздку, бабусі на дачу, гостям. Тоді чохол варто робити нейтральним, але з однією корисною деталлю — великою помітною формою або кольором, за яким телефон легко знайти в чужому домі серед речей.</p><p>Ще один варіант, який вигадали самі замовники: на резервному телефоні друкують те, що не хочеться забути. Схему проїзду, ім&#39;я, дату, слово іншою мовою, яке ніяк не запам&#39;ятовується. Виглядає це як звичайний напис, а працює як нагадування, що завжди під рукою.</p><p>Ще одна побутова причина оформити резервний апарат: саме він найчастіше опиняється в чужих руках. Основний телефон нікому не дають, а другий беруть у дорогу, кладуть у бардачок, лишають удома. Річ, яка регулярно ходить по руках, поводиться інакше, коли на ній є ваше оформлення, — її повертають швидше й не забувають, чия вона.</p><p>Блеквью А100 у будь-якому з цих сценаріїв виграє від друку більше, ніж основний апарат. У другого телефона зазвичай узагалі немає чохла, крім того, що йшов у коробці, — а отже, і вигляду в нього ніякого немає.</p>',
	 '<h2>Аппарат, который лежит во втором кармане</h2><p>Второй телефон — вещь более обыденная, чем кажется. Рабочий номер отдельно от личного. Аппарат для поездок, который не жалко. Телефон, остающийся дома для ребёнка. Резервный, куда переставляют симку, когда основной в ремонте. Blackview A100 в таких ролях встречается часто.</p><p>И с оформлением здесь логика другая, чем у главного телефона.</p><h3>Главное — чтобы их не путать</h3><p>Два аппарата в одной сумке или на одном столе — это ежедневные мелкие промахи: берёшь не тот, звонишь не с того, ищешь не в том кармане. Самое простое решение — сделать чехлы максимально непохожими. Не просто разными, а контрастными: если основной тёмный, второй светлый. Рука находит нужный ещё до того, как вы успели посмотреть.</p><p>Это тот редкий случай, когда яркий цвет на спинке — вопрос не вкуса, а удобства.</p><h3>Что печатают на втором</h3><p>Наблюдение простое: на втором телефоне люди смелее. На основном — сдержанный кадр, на резервном может быть что угодно, потому что его не достают на переговорах и не показывают клиентам.</p><p>Частые варианты: что-нибудь смешное, старое фото, яркий цвет, который на главном поставить не решились бы, надпись для себя. Второй телефон — почти черновик, где можно попробовать давно задуманное и посмотреть, как оно выглядит в жизни.</p><h3>Если он для кого-то другого</h3><p>Отдельный сценарий — когда резервный аппарат время от времени отдают: ребёнку в поездку, бабушке на дачу, гостям. Тогда чехол стоит делать нейтральным, но с одной полезной деталью — крупной заметной формой или цветом, по которому телефон легко найти в чужом доме среди вещей.</p><p>Ещё вариант, придуманный самими заказчиками: на резервном телефоне печатают то, что не хочется забыть. Схему проезда, имя, дату, слово на другом языке, которое никак не запоминается. Выглядит это обычной надписью, а работает напоминанием, которое всегда под рукой.</p><p>Ещё одна бытовая причина оформить резервный аппарат: именно он чаще всего оказывается в чужих руках. Основной телефон никому не дают, а второй берут в дорогу, кладут в бардачок, оставляют дома. Вещь, регулярно ходящая по рукам, ведёт себя иначе, когда на ней есть ваше оформление, — её возвращают быстрее и не забывают, чья она.</p><p>Блэквью А100 в любом из этих сценариев выигрывает от печати больше основного аппарата. У второго телефона обычно вообще нет чехла, кроме того, что шёл в коробке, — а значит, и вида у него никакого нет.</p>',
	 NULL, NULL, 1);

-- infinix-note-40-pro — кут: телефон, який живе поза домом (дача, риболовля, робота на вулиці)
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-infinix-note-40-pro', 'template',
	 'Чохол з фото на замовлення для Infinix Note 40 Pro', 'Чехол с фото на заказ для Infinix Note 40 Pro',
	 'Чохол з принтом для Infinix Note 40 Pro — друк | FLOY', 'Чехол с принтом для Infinix Note 40 Pro — печать | FLOY',
	 'Принт на чохлі для Infinix Note 40 Pro. Якщо телефон живе на вулиці, помітний колір спинки важливіший за красу — і рятує апарат у траві.',
	 'Принт на чехле для Infinix Note 40 Pro. Если телефон живёт на улице, заметный цвет спинки важнее красоты — и спасает аппарат в траве.',
	 '<h2>Телефон, який більшість часу не вдома</h2><p>Є телефони, що живуть у кишені між домом і офісом. А є ті, що весь час надворі: дача, город, риболовля, будівництво, похід, поїздки на вихідні. Infinix Note 40 Pro беруть саме в таких сценаріях — це модель із тих, які не бояться взяти з собою в поле.</p><p>Для чохла це означає інші пріоритети, ніж для міського телефона.</p><h3>Помітність важливіша за красу</h3><p>Надворі телефон губиться дуже буденно: поклали на траву, на камінь, на лавку, на землю поруч із рюкзаком. Чорний прямокутник у траві шукають хвилинами, а іноді й не знаходять.</p><p>Тому яскравий чохол тут — не питання смаку. Помаранчевий, жовтий, білий, лаймовий фон видно з трьох метрів у будь-якій траві. Це той випадок, коли колір рятує річ вартістю в кілька тисяч.</p><p>Якщо яскраве не для вас, компроміс теж є: темний фон і одна велика світла форма. Здалеку працює так само, зблизька виглядає стримано.</p><h3>Що ставлять на такі телефони</h3><ul><li>карта району, у який їздять постійно;</li><li>фото місця: озеро, ліс, ділянка, вершина;</li><li>власна техніка — авто, човен, мотоцикл, велосипед;</li><li>щось із роботи, якщо телефон робочий: інструмент, матеріал, техніка.</li></ul><p>Фотографії людей тут зустрічаються рідше, і причина побутова: телефон у таких умовах часто в чужих руках, брудний і лежить казна-де, а сімейний портрет у цьому контексті багатьом здається недоречним.</p><p>Другий бік того самого: надворі телефон часто в брудних або мокрих руках і лежить екраном донизу на будь-якій поверхні. Спинка в такому режимі бачить світ значно частіше за екран, і оформлення на ній помітне більше, ніж на телефоні з кишені сорочки.</p><h3>Дрібниця, яку варто врахувати</h3><p>Улітку на сонці все виглядає інакше, ніж у кімнаті. Контрастні макети на яскравому світлі читаються нормально, а от ніжні переходи й пастель просто зникають — око бачить світлу пляму. Якщо телефон більшу частину часу на вулиці, беріть контраст із запасом.</p><p>І ще про сюжет. Якщо телефон роками їздить із вами в те саме місце, найкраще працює кадр саме звідти, знятий у міжсезоння: літні фотографії з зеленню схожі одна на одну, а той самий берег у листопаді впізнається миттєво.</p><p>І ще: Інфінікс Ноут 40 Про — апарат чималий, у чохлі він у руці добре помітний. Це аргумент за просту велику композицію, яку видно повністю, а не за дрібний сюжет, що вимагає розглядати.</p>',
	 '<h2>Телефон, который большую часть времени не дома</h2><p>Есть телефоны, живущие в кармане между домом и офисом. А есть те, что всё время на улице: дача, огород, рыбалка, стройка, поход, поездки на выходные. Infinix Note 40 Pro берут именно в таких сценариях — это модель из тех, что не боятся взять с собой в поле.</p><p>Для чехла это означает другие приоритеты, чем для городского телефона.</p><h3>Заметность важнее красоты</h3><p>На улице телефон теряется очень буднично: положили на траву, на камень, на скамейку, на землю рядом с рюкзаком. Чёрный прямоугольник в траве ищут минутами, а иногда и не находят.</p><p>Поэтому яркий чехол здесь — не вопрос вкуса. Оранжевый, жёлтый, белый, лаймовый фон видно с трёх метров в любой траве. Это тот случай, когда цвет спасает вещь стоимостью в несколько тысяч.</p><p>Если яркое не для вас, компромисс тоже есть: тёмный фон и одна крупная светлая форма. Издалека работает так же, вблизи выглядит сдержанно.</p><h3>Что ставят на такие телефоны</h3><ul><li>карта района, в который ездят постоянно;</li><li>фото места: озеро, лес, участок, вершина;</li><li>собственная техника — машина, лодка, мотоцикл, велосипед;</li><li>что-нибудь из работы, если телефон рабочий: инструмент, материал, техника.</li></ul><p>Фотографии людей здесь встречаются реже, и причина бытовая: телефон в таких условиях часто в чужих руках, грязный и лежит где придётся, а семейный портрет в этом контексте многим кажется неуместным.</p><p>Обратная сторона того же: на улице телефон часто в грязных или мокрых руках и лежит экраном вниз на любой поверхности. Спинка в таком режиме видит свет гораздо чаще экрана, и оформление на ней заметнее, чем на телефоне из кармана рубашки.</p><h3>Мелочь, которую стоит учесть</h3><p>Летом на солнце всё выглядит иначе, чем в комнате. Контрастные макеты при ярком свете читаются нормально, а нежные переходы и пастель просто исчезают — глаз видит светлое пятно. Если телефон большую часть времени на улице, берите контраст с запасом.</p><p>И ещё о сюжете. Если телефон годами ездит с вами в одно и то же место, лучше всего работает кадр именно оттуда, снятый в межсезонье: летние фотографии с зеленью похожи одна на другую, а тот же берег в ноябре узнаётся мгновенно.</p><p>И ещё: Инфиникс Ноут 40 Про — аппарат немаленький, в чехле он в руке хорошо заметен. Это довод за простую крупную композицию, которую видно целиком, а не за мелкий сюжет, требующий разглядывания.</p>',
	 NULL, NULL, 1);

-- oneplus-15 — кут: шкода закривати корпус нового флагмана, чохол як продовження вигляду
INSERT INTO `articles`
	(`created_at`, `updated_at`, `site`, `alias`, `type`,
	 `title_uk`, `title_ru`, `meta_title_uk`, `meta_title_ru`,
	 `meta_description_uk`, `meta_description_ru`, `text_uk`, `text_ru`,
	 `image_file`, `link_arr`, `publish`)
VALUES
	(NOW(), NOW(), 'floy', 'printcase-oneplus-15', 'template',
	 'Чохол з фото на замовлення для OnePlus 15', 'Чехол с фото на заказ для OnePlus 15',
	 'Чохол з фото для OnePlus 15 — друк на замовлення | FLOY', 'Чехол с фото для OnePlus 15 — печать на заказ | FLOY',
	 'Свій принт на чохлі для OnePlus 15. Шкода закривати корпус нового флагмана — розбираємо три підходи, у яких чохол продовжує вигляд апарата.',
	 'Свой принт на чехле для OnePlus 15. Жаль закрывать корпус нового флагмана — разбираем три подхода, в которых чехол продолжает вид аппарата.',
	 '<h2>Шкода закривати телефон, за який щойно заплатили</h2><p>Відчуття знайоме: купили гарний апарат, тримаєте його в руці — і розумієте, що будь-який чохол зробить його схожим на всі інші. OnePlus 15 саме з таких телефонів: у нього своя зовнішність, і ховати її під силікон трохи шкода.</p><p>Логічний висновок «ходитиму без чохла» тримається зазвичай тижнів зо два. Далі йде перший невдалий контакт зі столом, і питання вирішується само собою — але вже без вибору.</p><h3>Компроміс, який справді працює</h3><p>Якщо чохол усе одно буде, нехай він не заміняє вигляд телефона, а продовжує його. Три підходи, які дають саме такий результат:</p><ul><li><strong>Колір у тон корпусу.</strong> Заливка, максимально близька до заводського відтінку. Телефон виглядає як телефон, тільки в чохлі.</li><li><strong>Один знак на порожньому полі.</strong> Дрібна монограма, лінія чи символ у нижній частині — решта спинки однотонна.</li><li><strong>Темний матовий фон.</strong> Найнейтральніше з можливого: ні з чим не сперечається й виглядає дорожче за прозорий пластик.</li></ul><p>Усі три об&#39;єднує одне: у них немає спроби перекричати сам апарат.</p><h3>Аргумент на користь друку</h3><p>Прозорий чохол здається очевидним рішенням, але саме він найгірше поводиться з часом і при цьому нічого не додає. Друкований дає те, чого корпус дати не може, — конкретно вашу деталь. Апарат однаковий у мільйонів людей, ініціали чи дата — ні.</p><p>Є й сценарій для тих, хто вагається: зробити два чохли. Один спокійний, у тон корпусу, для щодня; другий вільніший — для випадків, коли хочеться, щоб телефон виглядав по-вашому. Разом вони коштують менше за один аксесуар із фірмової крамниці.</p><h3>Коли все ж хочеться яскравого</h3><p>Буває й протилежне бажання: телефон помітний, і хочеться, щоб це бачили. Тоді працює зворотний прийом — чохол, який навмисно контрастує з корпусом: світлий на темному апараті, насичений колір на сріблястому. Головне, щоб рішення було одне й сильне, а не набір із трьох ідей, які сперечаються між собою.</p><p>Є й четвертий шлях, про який згадують рідше: почати з нейтрального чохла, а другий зробити через місяць, коли ви вже точно знатимете, як цей телефон почувається в руці й де саме на спинці лежать пальці. Рішення, прийняте в перший день після покупки, і рішення через місяць користування часто виявляються зовсім різними.</p><p>Зібрати макет для ВанПлюс 15 можна за вечір, і це той рідкісний випадок, коли думати над ним варто довше, ніж збирати: сам телефон уже задає половину відповіді, лишається не зіпсувати другу.</p>',
	 '<h2>Жаль закрывать телефон, за который только что заплатили</h2><p>Ощущение знакомое: купили красивый аппарат, держите его в руке — и понимаете, что любой чехол сделает его похожим на все остальные. OnePlus 15 как раз из таких телефонов: у него своя внешность, и прятать её под силикон немного жаль.</p><p>Логичный вывод «буду ходить без чехла» держится обычно недели две. Дальше случается первый неудачный контакт со столом, и вопрос решается сам собой — но уже без выбора.</p><h3>Компромисс, который действительно работает</h3><p>Если чехол всё равно будет, пусть он не заменяет вид телефона, а продолжает его. Три подхода, дающие именно такой результат:</p><ul><li><strong>Цвет в тон корпусу.</strong> Заливка, максимально близкая к заводскому оттенку. Телефон выглядит телефоном, только в чехле.</li><li><strong>Один знак на пустом поле.</strong> Мелкая монограмма, линия или символ в нижней части — остальная спинка однотонная.</li><li><strong>Тёмный матовый фон.</strong> Самое нейтральное из возможного: ни с чем не спорит и выглядит дороже прозрачного пластика.</li></ul><p>Все три объединяет одно: в них нет попытки перекричать сам аппарат.</p><h3>Довод в пользу печати</h3><p>Прозрачный чехол кажется очевидным решением, но именно он хуже всех ведёт себя со временем и при этом ничего не добавляет. Печатный даёт то, чего корпус дать не может, — конкретно вашу деталь. Аппарат одинаков у миллионов людей, инициалы или дата — нет.</p><p>Есть и сценарий для колеблющихся: сделать два чехла. Один спокойный, в тон корпусу, на каждый день; второй свободнее — для случаев, когда хочется, чтобы телефон выглядел по-вашему. Вместе они обходятся дешевле одного аксессуара из фирменного магазина.</p><h3>Когда всё-таки хочется яркого</h3><p>Бывает и обратное желание: телефон заметный, и хочется, чтобы это видели. Тогда работает противоположный приём — чехол, намеренно контрастирующий с корпусом: светлый на тёмном аппарате, насыщенный цвет на серебристом. Главное, чтобы решение было одно и сильное, а не набор из трёх идей, спорящих между собой.</p><p>Есть и четвёртый путь, о котором вспоминают реже: начать с нейтрального чехла, а второй сделать через месяц, когда вы уже точно будете знать, как этот телефон чувствуется в руке и где именно на спинке лежат пальцы. Решение, принятое в первый день после покупки, и решение через месяц пользования часто оказываются совсем разными.</p><p>Собрать макет для ВанПлюс 15 можно за вечер, и это тот редкий случай, когда думать над ним стоит дольше, чем собирать: сам телефон уже задаёт половину ответа, остаётся не испортить вторую.</p>',
	 NULL, NULL, 1);
